INSERT INTO categories(id,name_en,name_fa,icon,sort) VALUES('t1212','1212 Words You Need to Pass the TOEFL','۱۲۱۲ لغت ضروری تافل','📗',12) ON CONFLICT(id) DO UPDATE SET name_en=excluded.name_en, name_fa=excluded.name_fa, icon=excluded.icon, sort=excluded.sort;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:20-or-so','20 or so','phr','تقریباً ۲۰، حدود ۲۰','20 roughly','There were 20 or so students waiting outside the lecture hall.','[["There were 20 or so students waiting outside the lecture hall.","حدود بیست دانشجو بیرون سالن سخنرانی منتظر بودند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:a-host-of','a host of','phr','تعداد زیاد','/həʊst/ · great number','A host of friends came to see me off.','[["A host of friends came to see me off.","جمعی از دوستان برای بدرقه من آمده بودند."],["We are faced with a host of problems.","ما با انبوهی از مشکلات روبرو هستیم."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:access','access','n','اجازه دسترسی، دسترسی','/ˈækses/ · reach','Many villages still lack access to clean water.','[["Many villages still lack access to clean water.","بسیاری از روستاها هنوز به آب سالم دسترسی ندارند."],["Students have free access to the library.","دسترسی دانش آموزان به کتابخانه رایگان است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:account','account','n','توضیح دادن کتبی یا شفاهی','/əˈkaʊnt/ · description- a written or spoken description that says what happens in an event or process','They can even delete your account.','[["They can even delete your account.","حتی می‌توانند حساب کاربری شما را حذف کنند."],["My account is in the negative.","حساب من منفی است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:account-for','account for','phr','توضیح دادن، تشکیل دادن','explain-to form a particular amount or part of something','I take accountability for my mistake.','[["I take accountability for my mistake.","من مسئولیت اشتباهم را می‌پذیرم."],["All the passengers are accounted for.","تمام مسافران شناسایی شده‌اند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:accurate','accurate','adj','دقیق، صحیح','/ˈakjʊrət/ · correct- correct and true in every detail','The report gives an accurate picture.','[["The report gives an accurate picture.","گزارش تصویری دقیق ارائه می‌دهد."],["Make sure your measurements are accurate.","اطمینان حاصل کنید که اندازه گیری‌های شما دقیق است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:actually','actually','adv','در واقع','/ˈaktʃʊəli/ · 1) in fact used to emphasize the real or exact truth of a situation 2) (spoken) used to add new information to what you have just said, to give your opinion, or to start a new conversation','This apple is actually a cake!','[["This apple is actually a cake!","این سیب در واقع یک کیک است!"],["What he said was actually true.","چیزی که او گفت واقعاً درست بود."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:added','added','adj','به اضافه ی','/ˈædɪd/ · extra- in addition to what is usual or expected','Food coloring is added to sweets.','[["Food coloring is added to sweets.","رنگ خوراکی به شیرینی‌ها اضافه می‌شود."],["We added something new to it.","یه چیز جدید بهش اضافه کردیم."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:admit','admit','v','پذیرفتن، قبول کردن، اعتراف کردن، اجازه داخل شدن دادن','/ədˈmɪt/ · to agree unwillingly that something is true, confess; to let in; to allow someone to enter','You have to admit your mistakes.','[["You have to admit your mistakes.","باید اشتباهاتت را بپذیری."],["I admit that it influenced me.","اعتراف می‌کنم که روی من تأثیر گذاشت."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:advance','advance','n','پیشرفت، توسعه','/ədˈvæns/ · improvement, a change, discovery, or invention that brings progress','His answer was planned in advance.','[["His answer was planned in advance.","پاسخ او از قبل برنامه‌ریزی شده بود."],["Next time, please give advance notice.","دفعه بعد، لطفاً از قبل اطلاع دهید."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:affair','affair','n','امر، کار','/əˈfer/ · matter, an event or set of related events, especially one that is impressive or shocking','The banquet was a grand affair.','[["The banquet was a grand affair.","ضیافت، ضیافت باشکوهی بود."],["Few desire this state of affairs.","کمتر کسی آرزوی این وضعیت را دارد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:afford','afford','v','از عده بر امدن، تهیه کردن، فراهم کردن','/əˈf ɔːrd/ · provide, to provide something or allow something to happen','I can''t afford a new car.','[["I can''t afford a new car.","من نمی‌توانم ماشین جدید بخرم."],["We can''t afford to waste any more time.","ما نمی‌توانیم بیشتر از این زمان را تلف کنیم."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:air','air','v','ابراز کردن، بیان کردن (نظر یا احساس)؛ هوا','/er/ · feeling','The air here is too dry.','[["The air here is too dry.","اینجا هوا خیلی خشکه."],["Wasps are dancing in the air.","زنبورها در هوا می‌رقصند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:alleged','alleged','adj','بیان‌شده، ادعا‌شده، گزارش‌شده','/əˈledʒd/ · asserted, reported, supposed;an alleged crime, fact etc is one that someone says has happened or is true, although it has not been proved','He was arrested for allegedly stealing a boat.','[["He was arrested for allegedly stealing a boat.","او به اتهام سرقت یک قایق دستگیر شد."],["He allegedly committed many infractions against the law.","او ظاهراً مرتکب تخلفات زیادی علیه قانون شده است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:allow','allow','v','اجازه دادن','/əˈlaʊ/ · enable','My parents allow me to stay up late on Fridays.','[["My parents allow me to stay up late on Fridays.","پدر و مادرم به من اجازه می‌دهند جمعه‌ها تا دیروقت بیدار بمانم."],["Smoking is not allowed inside the building.","استعمال دخانیات در داخل ساختمان ممنوع است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:amazing','amazing','adj','شگفت‌انگیز','/əˈmeɪzɪŋ/ · remarkable','The view from the mountain was amazing.','[["The view from the mountain was amazing.","منظره ای از کوه فوق العاده بود."],["You did an amazing job on this project.","شما در این پروژه کار شگفت انگیزی انجام دادید."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ancient','ancient','adj','باستانی، مهن، قدیمی','/ˈeɪnʃ(ə)nt/ · antique, old- belonging to a long time in old history','We studied ancient Egyptian culture.','[["We studied ancient Egyptian culture.","ما فرهنگ مصر باستان را مطالعه کردیم."],["Ancient Persia was a powerful empire.","ایران باستان یک امپراتوری قدرتمند بود."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:anxiety','anxiety','n','اضطراب، نگرانی','/aŋˈzʌɪəti/ · worry, the state of feeling nervous or worried that something bad is going to happen','Is that what they call anxiety!','[["Is that what they call anxiety!","به این میگن اضطراب!"],["I get anxiety when I drive.","موقع رانندگی اضطراب می‌گیرم."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:apart-from','apart from','prep','به غیر از','except for','Everything apart from that is perfect.','[["Everything apart from that is perfect.","همه چیز به جز این کامل است."],["No one knows apart from me.","هیچکس جز خودم نمیدونه."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:apparent','apparent','adj','واضح، مشخص','/əˈpærənt/ · obvious','For no apparent reason, he left.','[["For no apparent reason, he left.","بدون هیچ دلیل مشخصی رفت."],["It was apparent that he was tired.","معلوم بود که خسته است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:apparently','apparently','adv','ظاهراً','/əˈparəntli/ · apparentlyclearly, seemingly- used to say that you have heard that something is true, although you are not completely sure about it','No one can hear me, apparently.','[["No one can hear me, apparently.","ظاهراً کسی صدایم را نمی‌شنود."],["Apparently, it was a rush job.","ظاهراً کار عجله‌ای بوده."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:appeal','appeal','v','جذابیت، تقاضا، تقاضا کردن','/əˈpēl/ · 1) (n) attraction-being attractive-a quality that makes people like something or someone.2) (n) an urgent request for something important. 3) (v) to make a serious public request for help, money, information etc','You can appeal to the court.','[["You can appeal to the court.","شما می‌توانید به دادگاه شکایت کنید."],["The ruling can still be appealed.","این حکم هنوز قابل تجدیدنظرخواهی است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:appear','appear','v','به نظر رسیدن','/əˈpir/ · seem-come into sight; become visible or noticeable, typically without visible agent or apparent cause','A rainbow appeared in the sky.','[["A rainbow appeared in the sky.","رنگین کمانی در آسمان ظاهر شد."],["A strange man appeared at the door.","مرد عجیبی دم در ظاهر شد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:appearance','appearance','n','ظهور، پیدایش، ظاهر','/əˈpirəns/ · 1) arrival/ rise, when something new begins to exist or starts being used 2)showing up-the way that someone or something looks.','He has a laid back appearance.','[["He has a laid back appearance.","او ظاهری آرام و خونسرد دارد."],["Yuri was ashamed of his appearance.","یوری از ظاهرش شرمنده بود."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:application','application','n','کاربرد','/ˌapləˈkāSH(ə)n/ · use, the action of putting something into operation','Glass has wide applications in architecture.','[["Glass has wide applications in architecture.","شیشه کاربردهای گسترده ای در معماری دارد."],["Open data makes application development easier.","داده‌های باز، توسعه‌ی برنامه‌ها را آسان‌تر می‌کند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:approach','approach','n','نزدیک شدن، روش','/əˈprəʊtʃ/ · 1)move toward-come near or nearer to (someone or something) in distance or time 2)method','We need a new approach to the problem.','[["We need a new approach to the problem.","ما به یک رویکرد جدید برای مشکل نیاز داریم."],["Her approach to teaching is very creative.","رویکرد او به تدریس بسیار خلاقانه است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:approximately','approximately','adv','تقریباً','/əˈprɒksɪmətli/ · roughly-used to show that something is almost, but not completely, accurate or exact; roughly.','The lake is approximately 10 km long.','[["The lake is approximately 10 km long.","طول این دریاچه تقریباً 10 کیلومتر است."],["The journey takes approximately three hours.","سفر تقریباً سه ساعت طول می‌کشد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:architecture','architecture','n','معماری','/ˈɑːrkətektʃər/ · structure- the style and design of a building or bulidings','He studied architecture in Rome.','[["He studied architecture in Rome.","او در رم معماری خواند."],["Ghardaia has a unique architecture.","غاردایا معماری منحصر به فردی دارد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:article','article','n','قلم، شی','/ˈɑːr.tɪ.kəl/ · item, object','Automated systems can classify news articles.','[["Automated systems can classify news articles.","سیستم‌های خودکار می‌توانند مقالات خبری را طبقه‌بندی کنند."],["I read a very good article.","یه مقاله خیلی خوب خوندم."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:as-a-rule','as a rule','phr','به طور کلی','in general, as a general rule','As a rule, governments are worse than their peoples.','[["As a rule, governments are worse than their peoples.","قاعدتاً دولت‌ها از ملت‌هایشان بدترند."],["As a rule the corbel table carries the gutter.","به عنوان یک قاعده، میز پیشخوان، ناودان را حمل می‌کند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:assistance','assistance','n','کمک','/əˈsɪstəns/ · help-the action of helping someone by sharing work','The work was completed with the assistance of carpenters.','[["The work was completed with the assistance of carpenters.","کار با کمک نجاران تکمیل شد."],["Can we offer him any assistance?","آیا می‌توانیم به او کمکی ارائه دهیم؟"]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:assume','assume','v','فرض کردن','/əˈsjuːm/ · believe, suppose, take on- 1. suppose to be the case, without proof','I assume you have heard the news.','[["I assume you have heard the news.","فکر می‌کنم شما این خبر را شنیده اید."],["I assumed that you already knew.","من حدس زدم که شما قبلا می‌دانستید."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:at-random','at random','phr','به صورت تصادفی، بدون الگوی خاص','without a definite pattern','Pick a movie at random.','[["Pick a movie at random.","یک فیلم را به طور تصادفی انتخاب کنید."],["I was chosen at random.","من به طور تصادفی انتخاب شدم."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:available','available','adj','موجود، در دسترس','/əˈveɪ.lə.bəl/ · obtainable, attainable','Is this room available tonight?','[["Is this room available tonight?","آیا این اتاق امشب موجود است؟"],["The new book is available in all bookstores.","کتاب جدید در تمامی کتابفروشی‌ها موجود است."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:avenue','avenue','n','روش','/ˈævənuː/ · means, method, a possible way of achieving something','The museum is on Fifth Avenue.','[["The museum is on Fifth Avenue.","این موزه در خیابان پنجم است."],["This city has many wide avenues.","این شهر خیابان‌های عریض زیادی دارد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:aware-of','aware of','phr','آگاه از','/əˈwer/ · familiar with','She was aware of it.','[["She was aware of it.","او از آن آگاه بود."],["Are you aware of this?","آیا از این موضوع آگاه هستید؟"]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:back-up','back up','phr','کپی پشتیبان تهیه کردن، حمایت کردن','support','Could you please back up a little?','[["Could you please back up a little?","میشه لطفا یه کم عقب‌تر بایستی؟"],["Make sure you back up your files.","مطمئن شوید که از فایل‌هایتان نسخه پشتیبان تهیه کرده‌اید."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:barely','barely','adv','تنها، فقط','/ˈberli/ · just, only with great difficulty or effort','The frightened girl could barely speak.','[["The frightened girl could barely speak.","دخترک وحشت‌زده به سختی می‌توانست حرف بزند."],["Our stepfather barely looks at us.","ناپدری‌مان به ندرت به ما نگاه می‌کند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:battle','battle','n','مبارزه، ستیز، نبرد، نزاع، نبرد کردن، جنگ کردن','/ˈbætl/ · struggle, combat, fight','Everyone is fighting their own battles.','[["Everyone is fighting their own battles.","هر کسی در حال مبارزه با مشکلات خودش است."],["They all perished in the battle.","همه آنها در نبرد هلاک شدند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:be-consistent-with','be consistent with','phr','سازگار با','be compatible with','The results are consistent with earlier studies.','[["The results are consistent with earlier studies.","نتایج با مطالعات قبلی مطابقت دارد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:be-entitled-to','be entitled to','phr','حق داشتن، مستحق بودن','/ɪnˈtaɪtl/ · have the right','Every customer will be entitled to a ticket to take part in the raffle.','[["Every customer will be entitled to a ticket to take part in the raffle.","هر مشتری حق دارد یک بلیط برای شرکت در قرعه‌کشی دریافت کند."],["If you join this club, you will be entitled to use all of its facilities.","با عضویت در این باشگاه، می‌توانید از تمام امکانات آن استفاده کنید."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:being','being','n','بودن، موجود','creature','Slaves were not considered human beings.','[["Slaves were not considered human beings.","بردگان انسان محسوب نمی‌شدند."],["He is good at being embarassing.","او در خجالت دادن مهارت دارد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:boom','boom','n','رونق، توسعه','/buːm/ · expansion','The tourism boom boosted the local economy.','[["The tourism boom boosted the local economy.","رونق گردشگری اقتصاد محلی را تقویت کرد."],["A loud boom was heard.","صدای غرشی بلند به گوش رسید."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:boost','boost','v','ترقی دادن، جلوبردن، بالابردن','/buːst/ · raise','Keeping clean can boost your confidence.','[["Keeping clean can boost your confidence.","تمیز نگه داشتن می‌تواند اعتماد به نفس شما را افزایش دهد."],["Martha boosted up her style.","مارتا استایلش را ارتقا داد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:branch','branch','n','شعبه، بخش، شاخه','/bræntʃ/ · division','A bird was sitting on a branch.','[["A bird was sitting on a branch.","پرنده ای روی شاخه ای نشسته بود."],["We were snagged on the branch.","ما به شاخه چسبیده بودیم."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:brilliant','brilliant','adj','درخشان','/ˈbrɪljənt/ · bright','That was a brilliant bit of soldiering.','[["That was a brilliant bit of soldiering.","اون یه بخش درخشان از سربازی بود."],["Jayjay came up with a brilliant idea.","جیجی ایده‌ی فوق‌العاده‌ای به ذهنش رسید."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:broad-appeal','broad appeal','phr','محبوبیت گسترده','wide popularity','The film has broad appeal for both children and adults.','[["The film has broad appeal for both children and adults.","این فیلم جذابیت گسترده‌ای برای کودکان و بزرگسالان دارد."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:by-and-large','by and large','phr','روی هم رفته، به طور کلی','for the most part','By and large, language is a tool for concealing the truth.','[["By and large, language is a tool for concealing the truth.","در واقع، زبان ابزاری برای پنهان کردن حقیقت است."],["By and large, reporters don''t hesitate to intrude on one''s privacy.","روی هم رفته، خبرنگاران از ورود به حریم خصوصی افراد ابایی ندارند."]]','t1212',1,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:central','central','adj','مهم، اصلی، اساسی','/ˈsentrəl/ · essential, of the greatest importance','Jews have no central authority.','[["Jews have no central authority.","یهودیان هیچ مرجع مرکزی ندارند."],["Ziri lives in central Algeria.","زیری در مرکز الجزایر زندگی می‌کند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:certain','certain','adj','تعیین‌شده، مشخص‌شده','/ˈsɜːrtn/ · specified','He will certainly not go unpunished.','[["He will certainly not go unpunished.","او مطمئناً بدون مجازات نخواهد ماند."],["He has a certain brooding charm.","او جذابیت خاصی دارد."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:champion','champion','v','دفاع کردن، پشتیبانی کردن از، ترویج کردن','/ˈtʃæmpiən/ · promote','I wanted to make her a champion.','[["I wanted to make her a champion.","می‌خواستم او را قهرمان کنم."],["Ziri was a former hammer throwing champion.","زیری قهرمان سابق پرتاب چکش بود."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:channel','channel','v','هدایت کردن، فراهم کردن','/ˈtʃænl/ · direct, guide, provide','the river is confined in a narrow channel','[["the river is confined in a narrow channel","رودخانه در یک کانال باریک محدود شده است"],["In short, the goal of marketing is to channel a shopper’s choices toward a single, specific product.","به‌طور خلاصه، هدف بازاریابی این است که انتخاب‌های خریدار را به سمت یک محصول واحد و مشخص هدایت کند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:chief','chief','n','رئیس، پیشرو، عمده، مهم','/tʃiːf/ · major, principal, most important','He became a police chief.','[["He became a police chief.","او رئیس پلیس شد."],["Mayas is a chief notary.","مایاس یک سردفتر اسناد رسمی است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:choose','choose','v','انتخاب کردن','/tʃuːz/ · opt','You can choose any book you like.','[["You can choose any book you like.","شما می‌توانید هر کتابی را که دوست دارید انتخاب کنید."],["It was hard to choose between the two jobs.","انتخاب بین این دو شغل سخت بود."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:classic','classic','adj','معمولی، نوعی','/ˈklæsɪk/ · typical','He loves a classic beef burger.','[["He loves a classic beef burger.","او عاشق برگر گوشت گاو کلاسیک است."],["This film is a cult classic.","این فیلم یک اثر کلاسیک کالت است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:clear','clear','adj','آشکار، واضح','/klɪə/ · visible, apparent, evident, explicit','Fish swim in the clear river.','[["Fish swim in the clear river.","ماهی‌ها در رودخانه‌ی زلال شنا می‌کنند."],["Uh, now, let me be clear.","حالا، بذار واضح بگم."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:close','close','adj','دقیق، با دقت؛ نزدیک','careful','He is closely related to us.','[["He is closely related to us.","او با ما نسبت فامیلی نزدیکی دارد."],["I closed my eyes to rest.","چشمامو بستم تا استراحت کنم."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:collect','collect','v','جمع‌آوری','/kəˈlekt/ · gather, stack up','He collects old coins.','[["He collects old coins.","او سکه‌های قدیمی را جمع آوری می‌کند."],["The teacher collected our homework at the end of class.","معلم تکالیف ما را در پایان کلاس جمع آوری کرد."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:commonly','commonly','adv','رایج، معمولی','/ˈkɒmənli/ · 1)often 2)generally/normally','Methanal is commonly known as formaldehyde.','[["Methanal is commonly known as formaldehyde.","متانال معمولاً به عنوان فرمالدئید شناخته می‌شود."],["Drugstores are commonly known as pharmacies.","داروخانه‌ها معمولاً به عنوان داروخانه شناخته می‌شوند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:complaint','complaint','n','اعتراض، شکایت','/kəmˈpleɪnt/ · protest','There is no complaint at all.','[["There is no complaint at all.","اصلاً شکایتی در کار نیست."],["Did you lodge a formal complaint?","آیا شکایت رسمی ارائه دادید؟"]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:completely','completely','adv','به طور کامل، کاملاً','/kəmˈpliːtli/ · totally','All this happened completely by accident.','[["All this happened completely by accident.","همه اینها کاملاً تصادفی اتفاق افتاد."],["He is completely isolated from society.","او کاملاً از جامعه منزوی است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:complex','complex','n','شبکه، مجموعه اپارتمان، پر نقش و نگار، پیچیده','/ˈkɒmpleks/ · 1) system (n), a group of buildings, or a large building with many parts, used for a particular purpose, 2) elaborate (adj)','Photosynthesis is a highly complex process.','[["Photosynthesis is a highly complex process.","فتوسنتز یک فرآیند بسیار پیچیده است."],["In the early 19th century, a German doctor thought he could answer these complex questions.","در اوایل قرن نوزدهم، یک پزشک آلمانی فکر کرد که می‌تواند به این پرسش‌های پیچیده پاسخ دهد."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:complicated','complicated','adj','پیچیده، بغرنج','/ˈkɑːm.plə.keɪ.tɪd/ · 1)complex 2)made things more difficult','This is a complicated legal case.','[["This is a complicated legal case.","این یک پرونده حقوقی پیچیده است."],["Dude, you make everything so complicated!","بابا، شما همه چیز را خیلی پیچیده می‌کنید!"]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:component','component','n','جز، اجزا','/kəmˈpoʊ.nənt/ · constituent','Companies make electronic components for computers.','[["Companies make electronic components for computers.","شرکت‌ها قطعات الکترونیکی را برای کامپیوترها تولید می‌کنند."],["The factory produces components for cars.","این کارخانه قطعات خودرو را تولید می‌کند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:composition','composition','n','ترکیب، مخلوط','/ˌkɒmpəˈzɪʃən/ · mixture','The painting''s composition affects emotion.','[["The painting''s composition affects emotion.","ترکیب بندی نقاشی بر احساسات تأثیر می‌گذارد."],["The composition balances light and shape.","این ترکیب نور و شکل را متعادل می‌کند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:comprehensive','comprehensive','adj','کامل، جامع، قابل فهم','/ˌkɒmprɪˈhensɪv/ · complete, understandable, thorough','The report gives a comprehensive overview.','[["The report gives a comprehensive overview.","گزارش یک مرور کلی ارائه می‌دهد."],["We need a comprehensive plan to reduce pollution.","برای کاهش آلودگی به یک برنامه جامع نیاز داریم."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:concern','concern','n','نگرانی، دغدغه؛ موضوع مهم','/kənˈsɜːn/ · interest, a matter of interest or importance to someone','There is growing concern about pollution.','[["There is growing concern about pollution.","نگرانی در مورد آلودگی وجود دارد."],["Your safety is our main concern.","امنیت شما دغدغه اصلی ماست."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consider','consider','v','در نظر گرفتن','/kənˈsɪdə/ · think about, view as','We are considering moving abroad.','[["We are considering moving abroad.","ما در حال بررسی مهاجرت به خارج هستیم."],["Please consider my suggestion.","لطفا به پیشنهاد من توجه کنید."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consistent','consistent','adj','پایدار، منظم','/kənˈsɪstənt/ · regular, uniform, steady, constant','We need to be consistent in our approach.','[["We need to be consistent in our approach.","ما باید در رویکرد خود ثابت قدم باشیم."],["Practice makes vocal tone more consistent.","تمرین باعث می‌شود لحن صدا منسجم‌تر شود."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:constant','constant','adj','ثابت، پایدار','/ˈkɒnstənt/ · stable, fixed, firm','The house is in constant need of repairs.','[["The house is in constant need of repairs.","خانه دائما نیاز به تعمیر دارد."],["You complained constantly as a child.","تو بچگی مدام غر می‌زدی."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:constantly','constantly','adv','همیشه، پیوسته','/ˈkɒnstəntli/ · always, invariably','You complained constantly as a child.','[["You complained constantly as a child.","تو بچگی مدام غر می‌زدی."],["Catherine is constantly talking in memes.","کاترین مدام با میم حرف می‌زند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:constitution','constitution','n','ساختار، ساختمان، ساخت، ترکیب، تشکل','/ˌkɑːn.stəˈtuː.ʃən/ · component','Laws may not contradict the constitution.','[["Laws may not contradict the constitution.","قوانین نمی‌توانند با قانون اساسی مغایرت داشته باشند."],["Everyone has to obey the constitution.","همه باید از قانون اساسی اطاعت کنند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contain','contain','v','حاوی بودن، (در بر)داشتن، شامل بودن، محتوی بودن، دارا بودن','/kənˈteɪn/ · include','This drink contains a lot of sugar.','[["This drink contains a lot of sugar.","این نوشیدنی حاوی مقدار زیادی قند است."],["This box contains old photographs.","این جعبه حاوی عکس‌های قدیمی است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contemporary','contemporary','adj','امروزی، جدید، مدرن، معاصر','/kənˈtem.pə.rer.i/ · modern','He was a contemporary of Shakespeare.','[["He was a contemporary of Shakespeare.","او معاصر شکسپیر بود."],["She is a famous contemporary artist.","او یک هنرمند مشهور معاصر است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:continued','continued','adj','پیوسته، مسلسل','/kənˈtɪn.juːd/ · constant, incessant','She continued working on the project.','[["She continued working on the project.","او به کار روی پروژه ادامه داد."],["I continued walking along the lake.","به راه رفتن در امتداد دریاچه ادامه دادم."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:contribute','contribute','v','اعانه دادن، همکاری یا کمک کردن، مشارکت کردن','/kənˈtrɪbjuːt/ · 1) to give money, help, ideas etc to something 2)to help to make something happen','Everyone contributed to the project.','[["Everyone contributed to the project.","همه در این پروژه مشارکت داشتند."],["Pollution contributes to climate change.","آلودگی به تغییرات آب و هوایی کمک می‌کند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:core','core','n','مرکز، میانگاه، وسط','/kɔːr/ · center, hub, nucleus','Debt is at the core of the problem.','[["Debt is at the core of the problem.","بدهی هسته اصلی مشکل است."],["The Earth''s core is extremely hot.","هسته زمین بسیار داغ است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:counter','counter','v','مقابله کردن، تلا فی کردن، جواب دادن، معامله بمثل کردن با','/ˈkaʊn.tɚ/ · oppose, speak or act in opposition to','Luis cleaned the kitchen counter.','[["Luis cleaned the kitchen counter.","لوئیس پیشخوان آشپزخانه را تمیز کرد."],["Edmundo was behind the counter.","ادموندو پشت پیشخوان بود."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:counter-to','counter to','phr','در مقابل، برخلاف','/ˈkaʊntər/ · in the opposite of','The thief vaulted over the counter to reach the cash register.','[["The thief vaulted over the counter to reach the cash register.","دزد از روی پیشخوان پرید تا به صندوق برسد."],["He left the beef out on the counter to thaw.","او گوشت گاو را روی پیشخوان گذاشت تا یخ آن آب شود."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:couple','couple','v','جفت شدن یا کردن، به هم پیوستن، به هم وصل کردن، همبند کردن، همبسته کردن','/ˈkʌp.əl/ · associate, combine','They make a handsome couple.','[["They make a handsome couple.","آنها یک زوج خوش تیپ می‌سازند."],["He was spying on the couple.","او داشت جاسوسی آن زوج را می‌کرد."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:covered','covered','adj','شامل‌شده، در برگرفته‌شده','/ˈkʌv.ɚd/ · included, coated','Her face is covered with freckles.','[["Her face is covered with freckles.","صورتش پوشیده از کک و مک است."],["The field is covered in flowers.","دشت پوشیده از گل است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:create','create','v','آفریدن، خلق کردن، هست کردن','/kriˈeɪt/ · invent, manufacture','He believes the universe was created by a big explosion.','[["He believes the universe was created by a big explosion.","او معتقد است که جهان بر اثر یک انفجار بزرگ ایجاد شده است."],["Gall wondered if the functions of the brain created bumps on a person’s skull (the skull is the bone around a person’s head).","گال از خود پرسید که آیا عملکردهای مغز روی جمجمهٔ انسان برآمدگی ایجاد می‌کنند (جمجمه استخوانی است که دور سر انسان را گرفته است)."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:creative','creative','adj','خلاق، سازنده، خلاقه، آفریدگر','/kriˈeɪ.tɪv/ · inventive, innovative','He encouraged them to think creatively.','[["He encouraged them to think creatively.","او آنها را تشویق می‌کرد که خلاقانه فکر کنند."],["When do you feel most creative?","چه زمانی بیشترین احساس خلاقیت را دارید؟"]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:crisis','crisis','n','بحران، شور، بزنگاه، سرگشتگی','/ˈkraɪ.sɪs/ · disturbance, tension','Crisis response requires teamwork and leadership.','[["Crisis response requires teamwork and leadership.","مقابله با بحران نیازمند کار تیمی و رهبری است."],["Crisis response needs preparation and communication.","واکنش به بحران نیاز به آمادگی و ارتباطات دارد."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:critical','critical','adj','بحرانی، بسیار مهم، حیاتی','/ˈkrɪt.ɪ.kəl/ · crucial, essential','She quickly developed critical thinking skills.','[["She quickly developed critical thinking skills.","او به سرعت مهارت‌های تفکر انتقادی را در خود پرورش داد."],["They think critically about every step.","آنها در مورد هر قدم با دقت فکر می‌کنند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:current','current','adj','کنونی، فعلی، جاری','/ˈkɝː.ənt/ · present','The river has a strong current.','[["The river has a strong current.","رودخانه جریان قوی دارد."],["We are currently clean on OPSEC.","ما در حال حاضر در OPSEC پاک هستیم."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:debate','debate','n','مباحثه، بگومگو، جر و بحث','/dɪˈbeɪt/ · argue, dispute','There has been much discussion about prices.','[["There has been much discussion about prices.","در مورد قیمت‌ها بحث‌های زیادی شده است."],["There is a heated debate about nuclear power.","بحث‌های داغی در مورد انرژی هسته ای وجود دارد."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:degree','degree','n','حد، میزان، درجه','/dɪˈɡriː/ · extent, measure','What is the degree of visibility?','[["What is the degree of visibility?","میزان دید چقدر است؟"],["He got a degree in economics.","او مدرک اقتصاد گرفت."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:demand','demand','n','تقاضا، نیاز','/dɪˈmɑːnd/ · need','Demand for electric cars is rising.','[["Demand for electric cars is rising.","تقاضا برای خودروهای برقی در حال افزایش است."],["There is a high demand for doctors in rural areas.","تقاضای زیادی برای پزشک در مناطق روستایی وجود دارد."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:design','design','v','طراحی کردن، خلق کردن','/dɪˈzaɪn/ · create, draw, plan','She designed a new logo for the company.','[["She designed a new logo for the company.","او لوگوی جدیدی برای این شرکت طراحی کرد."],["These structures used a new construction design.","این سازه‌ها از طرح ساخت جدیدی استفاده کردند."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:despite','despite','prep','علی رغم، به رغم، بر خلاف، با وجود','/dɪˈspaɪt/ · even though, notwithstanding, in spite of','He won despite being injured.','[["He won despite being injured.","او با وجود مصدومیت پیروز شد."],["Despite everything, he trusted them.","با وجود همه چیز، او به آنها اعتماد داشت."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:determine','determine','v','مشخص کردن، معلوم کردن','/dɪˈtɜːmɪn/ · figure out, specify, define','Choice, not chance, determines your destiny.','[["Choice, not chance, determines your destiny.","انتخاب، نه شانس، سرنوشت شما را تعیین می‌کند."],["Have you determined when it happened?","آیا مشخص کرده‌اید که چه زمانی این اتفاق افتاده است؟"]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:disorder','disorder','n','بی نظمی','/dɪsˈɔːdə/ · anarchy','The problems and disorder are over.','[["The problems and disorder are over.","مشکلات و نابسامانی‌ها تمام شد."],["What is causing colony collapse disorder?","چه چیزی باعث اختلال فروپاشی کلونی می‌شود؟"]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:diversity','diversity','n','تنوع','/dɪˈvɝː.sə.ti/ · varietydiversity','There was considerable diversity in the style of the reports.','[["There was considerable diversity in the style of the reports.","تنوع قابل توجهی در سبک گزارش‌ها وجود داشت."],["The rainforest has an amazing diversity of plants.","جنگل‌های بارانی دارای تنوع شگفت انگیزی از گیاهان است."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:domestic','domestic','adj','خانگی، داخلی','/dəˈmestik/ · home, 1) relating to or happening in one particular country and not involving any other countries opposute of foreign.2) relating to family relationships and life at home','Unfortunately his domestic life wasn''t very happy.','[["Unfortunately his domestic life wasn''t very happy.","متأسفانه زندگی خانگی او چندان شاد نبود."],["The team must also decide if the focus will be on domestic sales or if the baby food will be exported to foreign countries.","تیم همچنین باید تصمیم بگیرد که تمرکز بر فروش داخلی باشد یا غذای کودک به کشورهای خارجی صادر شود."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:drive','drive','n','انگیزه، محرک','/draɪv/ · incentive, movement, push, impetus, inducement','He often drives at dangerous speeds.','[["He often drives at dangerous speeds.","او اغلب با سرعت خطرناک رانندگی می‌کند."],["I drive from home to work.","من از خانه تا محل کار با ماشین می‌روم."]]','t1212',2,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:earn','earn','v','به دست آوردن','/ɜːrn/ · acquire, gain','They earned a lot of money.','[["They earned a lot of money.","آنها پول زیادی به دست آوردند."],["I wish I could earn more.","کاش می‌توانستم درآمد بیشتری داشته باشم."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ease','ease','v','تسهیل کردن','/iːz/ · facilitate','We will do it with ease.','[["We will do it with ease.","ما این کار را با خیال راحت انجام خواهیم داد."],["I am not always at ease.","من همیشه راحت نیستم."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:elite','elite','n','نخبه','/eɪˈliːt/ · excellent person','Grassroots movements will crush the elite.','[["Grassroots movements will crush the elite.","جنبش‌های مردمی، نخبگان را در هم خواهند شکست."],["Algeria has a corrupt business elite.","الجزایر یک طبقه ثروتمند فاسد دارد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:emergency','emergency','n','ضروری، اضطراری، غیر منتظره، بحران','/ɪˈmɜːrdʒənsi/ · crisis, urgent situation','Call 115 in an emergency.','[["Call 115 in an emergency.","در مواقع اضطراری با ۱۱۵ تماس بگیرید."],["The plane made an emergency landing.","هواپیما فرود اضطراری داشت."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enable','enable','v','قادر ساختن','/ɪˈneɪbəl/ · allow','The loan enabled Jan to buy the house.','[["The loan enabled Jan to buy the house.","وام به جان این امکان را داد که خانه را بخرد."],["Technological development enabled scientific development.","توسعه فناوری، توسعه علمی را ممکن ساخت."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:encourage','encourage','v','ترغیب کردن، تشویق کردن، دلگرم کردن','/ɪnˈkɜːrɪdʒ/ · stimulate, persuade','My coach encouraged me to keep trying.','[["My coach encouraged me to keep trying.","مربی ام مرا تشویق کرد که به تلاش ادامه دهم."],["The government encourages people to recycle.","دولت مردم را به بازیافت تشویق می‌کند."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:end','end','n','منظور، مقصود','/end/ · purpose, aim, intention','His end has not yet come.','[["His end has not yet come.","پایان او هنوز فرا نرسیده است."],["How much longer until it ends?","چقدر دیگه مونده تا تموم بشه؟"]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enjoy','enjoy','v','دارا بودن، بهره‌مند بودن از؛ لذت بردن','/ɪnˈdʒɔɪ/ · experience, benefit from, to have a particular ability or advantage','I enjoy reading books.','[["I enjoy reading books.","از خواندن کتاب لذت می‌برم."],["Did you enjoy the movie?","آیا از فیلم لذت بردید؟"]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ensure','ensure','v','مطمئن شدن','/ɪnˈʃʊr/ · guarantee','The book ensured his success.','[["The book ensured his success.","کتاب موفقیت او را تضمین کرد."],["Please ensure that all windows are closed.","لطفا مطمئن شوید که همه پنجره‌ها بسته هستند."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:entirely','entirely','adv','کاملاً','/ɪnˈtaɪr.li/ · wholly, completely and in every possible way','My style is entirely my own.','[["My style is entirely my own.","سبک من کاملاً مختص خودم است."],["You desire to have me entirely.","تو تمام و کمال آرزوی داشتن مرا داری."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:environment','environment','n','زمینه، محیط','/ɪnˈvaɪrənmənt/ · setting, surroundings','We must protect the environment.','[["We must protect the environment.","ما باید از محیط زیست محافظت کنیم."],["Children need a safe and happy home environment.","کودکان به یک محیط خانه امن و شاد نیاز دارند."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:episode','episode','n','قسمت، رویداد، زمان معین','/epəsəʊd/ · event, incident, occasion','This TV series consists of eleven episodes.','[["This TV series consists of eleven episodes.","این مجموعه تلویزیونی شامل یازده قسمت است."],["There will be no more new episodes.","دیگه قسمت جدیدی نخواهد بود."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:era','era','n','دوران، عصر','/ˈɪrə/ · period','The revolution heralded a new era.','[["The revolution heralded a new era.","انقلاب، نویدبخش دوران جدیدی بود."],["Welcome to the era of wokeism.","به عصر بیداری خوش آمدید."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:essential','essential','adj','مهم، حیاتی','/ɪˈsenʃəl/ · crucial, vital, indispensable, principal, integral','Water is essential for life.','[["Water is essential for life.","آب برای زندگی ضروری است."],["It''s essential to book tickets in advance.","رزرو بلیط از قبل ضروری است."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:essentially','essentially','adv','اساساً','/ɪˈsenʃəli/ · fundamentally','Porcupine quills are essentially modified hairs.','[["Porcupine quills are essentially modified hairs.","تیغ‌های جوجه تیغی اساساً موهای اصلاح‌شده هستند."],["Love is an essentially selfish passion.","عشق اساساً یک اشتیاق خودخواهانه است."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:established','established','adj','موجود، واجد شرایط','/ɪˈstæblɪʃt/ · qualified, have been in existence for a long time and therefore recognized and generally accepted.','This guy is very well established.','[["This guy is very well established.","این مرد خیلی خوب جا افتاده."],["Edmundo established contact with the base.","ادموندو با پایگاه ارتباط برقرار کرد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:establishment','establishment','n','تشکیل','/ɪˈstæblɪʃmənt/ · formation, the act of starting an organization, relationship, or system','The establishment of the first colleges took place in the 1600s.','[["The establishment of the first colleges took place in the 1600s.","تأسیس اولین کالج‌ها در دهه ۱۶۰۰ میلادی اتفاق افتاد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:eventually','eventually','adv','در نهایت','/ɪˈventʃuəli/ · finally, later, ultimately, in the end','He eventually found a job.','[["He eventually found a job.","او سرانجام شغلی پیدا کرد."],["After many attempts, he eventually passed the exam.","او پس از تلاش‌های فراوان در نهایت امتحان را پس داد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:evidence','evidence','n','مدرک','/ˈevɪdəns/ · proof','There is no evidence of life on Mars.','[["There is no evidence of life on Mars.","هیچ مدرکی از حیات در مریخ وجود ندارد."],["There is no evidence that he stole the money.","هیچ مدرکی دال بر دزدیدن پول وجود ندارد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exercise','exercise','v','استفاده کردن از','/ˈeksərsaɪz/ · use, employ, practice, formal to use a power, right, or quality that you have','When do you prefer to exercise?','[["When do you prefer to exercise?","چه زمانی را برای ورزش کردن ترجیح می‌دهید؟"],["He is exercising on the beach.","او در ساحل ورزش می‌کند."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:expand','expand','v','گسترش دادن، توسعه پیدا کردن','/ɪkˈspænd/ · increase, stretch','The company plans to expand overseas.','[["The company plans to expand overseas.","این شرکت قصد دارد در خارج از کشور گسترش یابد."],["Metal expands when it is heated.","فلز با گرم شدن منبسط می‌شود."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:explore','explore','v','کشف کردن، بررسی کردن','/ɪkˈsplɔː/ · investigate, probe','Together, we could explore the world.','[["Together, we could explore the world.","با هم، می‌توانستیم دنیا را کشف کنیم."],["I find joy in exploring stories.","من از کاوش در داستان‌ها لذت می‌برم."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:express','express','v','بیان کردن، ارتباط برقرار کردن','/ɪkˈspres/ · communicate, convey, show','I wanted to express my condolences.','[["I wanted to express my condolences.","می‌خواستم مراتب تسلیت خودم را ابراز کنم."],["Express it in your own words.","آن را با کلمات خودتان بیان کنید."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:extend','extend','v','گسترش دادن، کشش دادن، منبسط کردن','/ɪkˈstend/ · stretch, expand, develop','The bridge has been extended.','[["The bridge has been extended.","پل امتداد یافته است."],["You may extend the house.","شما می‌توانید خانه را گسترش دهید."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:extensive','extensive','adj','گسترده، توسعه یافته، بزرگ','/ɪkˈstensɪv/ · substantial, broad, large, comprehensive','An extensive viewpoint that covers everything is important.','[["An extensive viewpoint that covers everything is important.","یک دیدگاه جامع که همه چیز را پوشش دهد، مهم است."],["Her job requires her to travel extensively.","شغل او ایجاب می‌کند که سفرهای زیادی داشته باشد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:extraordinary','extraordinary','adj','فوق العاده، استثنایی','/ɪkˈstrɔːdənəri/ · exceptional, phenomenal','The main shareholder requested an extraordinary meeting.','[["The main shareholder requested an extraordinary meeting.","سهامدار اصلی درخواست تشکیل مجمع فوق العاده کرد."],["I was meant to accomplish extraordinary feats.","قرار بود من به دستاوردهای خارق‌العاده‌ای برسم."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fair','fair','adj','با انصاف، نسبتاً خوب، بی غرض','/feə/ · significant, goodish, just','It''s not fair that I always wash the dishes.','[["It''s not fair that I always wash the dishes.","این انصاف نیست که من همیشه ظرف‌ها را می‌شوم."],["The judge was fair to both sides.","قاضی با هر دو طرف منصف بود."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:far-reaching','far-reaching','adj','گسترده، دامنه‌دار','broad/extensive, wide-ranging','These policies had far-reaching consequences for the geopolitics of the region.','[["These policies had far-reaching consequences for the geopolitics of the region.","این سیاست‌ها پیامدهای گسترده‌ای برای ژئوپلیتیک منطقه داشت."],["The societal implications of this research are likely to be far-reaching.","پیامدهای اجتماعی این تحقیق احتمالاً بسیار گسترده خواهد بود."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fashion','fashion','n','مد، رسم، شیوه؛ ساختن (با دست)، شکل دادن','/ˈfæʃən/ · [n] way, a style of clothes, hair, behaviour etc that is fashionable','She dressed in her customary fashion.','[["She dressed in her customary fashion.","او طبق معمول لباس می‌پوشید."],["Her fashion sense is always admired.","حس مد او همیشه مورد تحسین است."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:figure-out','figure out','phr','کشف کردن','map, work out, solve','Have you figured out what happened?','[["Have you figured out what happened?","فهمیدی چی شده؟"],["Did you figure out the problem?","مشکل رو متوجه شدید؟"]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:finding','finding','n','کشف','discovery','Finding the right opportunity requires patience.','[["Finding the right opportunity requires patience.","پیدا کردن فرصت مناسب نیاز به صبر و شکیبایی دارد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fixed','fixed','adj','ثابت، معین','/fɪkst/ · firm, constant, stable, steady','I know you fixed the car.','[["I know you fixed the car.","می‌دانم که ماشین را تعمیر کردی."],["They fixed the potholes with tar.","چاله‌ها را با قیر درست کردند."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:flow','flow','n','جریان، گردش','/floʊ/ · movement, motion, current','The streams flow into the river.','[["The streams flow into the river.","جویبارها به رودخانه می‌ریزند."],["Water is flowing from the fountains.","آب از چشمه‌ها جاری است."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:focus','focus','v','متمرکز کردن','/ˈfəʊkəs/ · concentrate','She tried to focus her mind on her work.','[["She tried to focus her mind on her work.","سعی کرد ذهنش را روی کارش متمرکز کند."],["The organization focuses on wildlife conservation.","این سازمان بر حفاظت از حیات وحش تمرکز دارد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:follow','follow','v','دنبال کردن، پیروی کردن','/ˈfɑːloʊ/ · track, pursue, chase','Follow me; I know the way.','[["Follow me; I know the way.","دنبالم کن؛ من راه رو بلدم"],["Please follow the instructions carefully.","لطفا دستورالعمل‌ها را با دقت دنبال کنید."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:for-instance','for instance','phr','برای مثال','for example','Everybody is good at something and you, for instance, are a liar.','[["Everybody is good at something and you, for instance, are a liar.","هر کسی در چیزی خوب است و مثلاً تو دروغگو هستی."],["For instance, what would you have done if you were in my place?","مثلاً اگه جای من بودی چیکار میکردی؟"]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:foster','foster','v','پرورش دادن، غذا دادن، تشویق کردن','/ˈfɑːstər/ · promote the development of, encourage, urge, bring up','Fostering an inclusive mindset is important.','[["Fostering an inclusive mindset is important.","پرورش یک طرز فکر فراگیر مهم است."],["Clashing ideas can foster deeper insights.","ایده‌های متضاد می‌توانند بینش‌های عمیق‌تری را پرورش دهند."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:function','function','n','عملکرد','/ˈfʌŋkʃən/ · operation, utility','The function of the heart is to pump blood.','[["The function of the heart is to pump blood.","وظیفه قلب پمپاژ خون است."],["This button has several functions.","این دکمه چندین عملکرد دارد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fund','fund','n','منابع مالی','/fʌnd/ · money, an amount of money that is collected and kept for a particular purpose','He seeks funding for his project.','[["He seeks funding for his project.","او به دنبال تأمین مالی برای پروژه‌اش است."],["Gabor is taking back his funding.","گابور بودجه‌اش را پس می‌گیرد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fundamental','fundamental','adj','اساسی، بنیادی','/fʌndəˈmentl/ · basic, essential, vital, crucial','Education is a fundamental right.','[["Education is a fundamental right.","آموزش یک حق اساسی است."],["There are fundamental differences between the two systems.","تفاوت‌های اساسی بین این دو سیستم وجود دارد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:gap','gap','n','شکاف، وقفه','/ɡæp/ · opening, slot, hole','There is a huge gap between the two.','[["There is a huge gap between the two.","بین این دو، شکاف عظیمی وجود دارد."],["It requires patience and empathy to bridge gaps.","برای از بین بردن شکاف‌ها به صبر و همدلی نیاز است."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:gear','gear','n','دنده، چرخ دنده','/ɡɪr/ · adjust, the machinery in a vehicle such as a car, truck, or bicycle that you use to go comfortably at different speeds','She always cycles in the highest gear.','[["She always cycles in the highest gear.","او همیشه با بالاترین دنده دوچرخه‌سواری می‌کند."],["I changed gear as the road sloped.","با شیب تند جاده دنده را عوض کردم."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:genuine','genuine','adj','واقعی، اصل','/ˈdʒenjuɪn/ · true, real, origional, sincere','She showed genuine interest in my work.','[["She showed genuine interest in my work.","او علاقه واقعی به کار من نشان داد."],["This bag is made of genuine leather.","این کیف از چرم طبیعی ساخته شده است."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:giant','giant','adj','قوی هیکل','/ˈdʒaɪənt/ · huge, extremely big, and much bigger than other things of the same type','Ernesto is crazy about giant robots.','[["Ernesto is crazy about giant robots.","ارنستو دیوانه‌ی ربات‌های غول‌پیکر است."],["A giant lizard destroyed the city.","یک مارمولک غول پیکر شهر را ویران کرد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:give-rise-to','give rise to','phr','منجر شدن به، باعث شدن','produce, lead to, to be the reason why something happens, especially something bad or unpleasant','Such a plan will give rise to many problems.','[["Such a plan will give rise to many problems.","چنین طرحی مشکلات زیادی را به دنبال خواهد داشت."],["Every win eventually gives rise to a failure.","هر پیروزی در نهایت منجر به یک شکست می‌شود."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:given','given','adj','معین، معلوم','/ˈɡɪvən/ · particular, previously arranged, specified','I have given up on him.','[["I have given up on him.","من از او قطع امید کرده‌ام."],["She has given up on her.","او از او دست کشیده است."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ground','ground','n','سبب','/graʊnd/ · reason, cause','The barley was ground into flour.','[["The barley was ground into flour.","جو را آسیاب می‌کردند و به آرد تبدیل می‌کردند."],["Please evacuate to higher ground immediately.","لطفا فوراً به مناطق مرتفع‌تر بروید."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:guarantee','guarantee','v','تضمین کردن؛ ضمانت','/ɡærənˈti/ · ensure','They wanted a guarantee that the document was authentic.','[["They wanted a guarantee that the document was authentic.","آنها ضمانت می‌خواستند که سند معتبر باشد."],["The TV comes with a two-year guarantee.","تلویزیون دارای دو سال گارانتی می‌باشد."]]','t1212',3,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:have-nothing-to-do-with','have nothing to do with','phr','به کسی یا چیزی ارتباطی نداشتن','in no relation to','Cucumbers have nothing to do with cake.','[["Cucumbers have nothing to do with cake.","خیار هیچ ربطی به کیک ندارد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hence','hence','adv','بنابراین','/hens/ · therefore','His mother was Italian, hence his name - Luca.','[["His mother was Italian, hence his name - Luca.","مادر او ایتالیایی بود، از این رو نام او - لوکا."],["Boredom is itself boring, hence it tends to feed on itself.","کسالت خودش کسالت‌آور است، از این رو تمایل دارد از خودش تغذیه کند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:heritage','heritage','n','سنت، میراث','/ˈherətɪdʒ/ · legacy, tradition','Heritage sites attract millions of visitors.','[["Heritage sites attract millions of visitors.","سایت‌های میراثی میلیون‌ها بازدید کننده را به خود جذب می‌کنند."],["Your existence keeps our heritage alive.","وجود شما میراث ما را زنده نگه می‌دارد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hide','hide','v','پنهان کردن','/haɪd/ · conceal','The hedgehog is hiding its head.','[["The hedgehog is hiding its head.","جوجه تیغی سرش را پنهان کرده است."],["Where did the little boy hide?","پسر کوچک کجا پنهان شده بود؟"]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hire','hire','v','استخدام کردن، اجاره کردن','/haɪr/ · employ','She hired a good defence lawyer.','[["She hired a good defence lawyer.","او یک وکیل مدافع خوب استخدام کرد."],["Can I hire a tour guide?","آیا می‌توانم یک راهنمای تور استخدام کنم؟"]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hold','hold','v','نگه داشتن، در بر داشتن؛ معتبر بودن','/held/ · support-keep up','Fear has taken hold of her.','[["Fear has taken hold of her.","ترس وجودش را فرا گرفته است."],["The negotiations were put on hold.","مذاکرات به حالت تعلیق درآمد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:however','however','adv','در عین حال','/haʊˈevə/ · yet, but','The students'' parents, however, seem worried.','[["The students'' parents, however, seem worried.","با این حال، والدین دانش‌آموزان نگران به نظر می‌رسند."],["However, the future is still unclear.","با این حال، آینده هنوز مشخص نیست."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:huge','huge','adj','بزرگ','/hjuːdʒ/ · large, enormous, colossal, massive','That would be a huge help.','[["That would be a huge help.","این کمک بزرگی خواهد بود."],["He was making a huge mistake.","او داشت اشتباه بزرگی مرتکب می‌شد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ice-sheet','ice sheet','n','صفحه یخی، یخچال قاره‌ای','glacier','Antarctica''s ice sheets store 70% of Earth''s freshwater.','[["Antarctica''s ice sheets store 70% of Earth''s freshwater.","صفحات یخی قطب جنوب 70 درصد آب شیرین زمین را ذخیره می‌کنند."],["About two-thirds of global sea level rise is due to meltwater from glaciers and ice sheets.","حدود دو سوم افزایش سطح آب دریاهای جهان به دلیل ذوب شدن یخچال‌های طبیعی و صفحات یخی است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:immigration','immigration','n','جابجایی، مهاجرت','/ˌɪmɪˈɡreɪʃən/ · movement, emigration','There are strict limits on immigration.','[["There are strict limits on immigration.","محدودیت‌های سختی برای مهاجرت وجود دارد."],["Oleg went to the immigration office.","اولگ به اداره مهاجرت رفت."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:in-fact','in fact','phr','در حقیقت','actually','In fact, I am coming.','[["In fact, I am coming.","راستش، من دارم میام."],["In fact, Algeria has everything.","در واقع، الجزایر همه چیز دارد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:in-great-demand','in great demand','phr','پرطرفدار، مورد تقاضای زیاد','in (great) popularity','If all went according to her plan, she would be in great demand.','[["If all went according to her plan, she would be in great demand.","اگر همه چیز طبق برنامه او پیش می‌رفت، تقاضای زیادی برای او وجود داشت."],["Those books are always in great demand.","این کتاب‌ها همیشه تقاضای زیادی دارند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:in-respect-to','in respect to','phr','درباره، با توجه به','in term of, in regard to','In respect to your question, I have nothing to say.','[["In respect to your question, I have nothing to say.","در مورد سوالت، من حرفی برای گفتن ندارم."],["We were asked what our rights are in respect to CCTV monitoring at work.","از ما پرسیده شد که حقوق ما در رابطه با نظارت دوربین مداربسته در محل کار چیست."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:in-the-long-run','in the long run','phr','در نهایت، در دراز مدت','eventually, over or after a long period of time','In the long run, changes will be necessary.','[["In the long run, changes will be necessary.","در درازمدت، تغییرات ضروری خواهند بود."],["What would it matter in the long run?","در درازمدت چه اهمیتی خواهد داشت؟"]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:indicate','indicate','v','ثابت کردن نشان دادن','/demənˌstrāt/ · demonstrate, imply','The results indicate a strong link.','[["The results indicate a strong link.","نتایج نشان دهنده یک پیوند قوی است."],["Dark clouds indicate that rain is coming.","ابرهای تیره نشان می‌دهد که باران در راه است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:infrastructure','infrastructure','n','زیرساخت، ساختار','/ˈinfrəˌstrəkCHər/ · foundation','The country needs better infrastructure.','[["The country needs better infrastructure.","کشور به زیرساخت‌های بهتری نیاز دارد."],["Roads, bridges and railways are part of a city''s infrastructure.","جاده‌ها، پل‌ها و راه آهن بخشی از زیرساخت‌های یک شهر هستند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:initial','initial','adj','اولیه، ابتدایی، آغازین','/ɪˈnɪʃəl/ · first, in the beginning','What was his initial reaction?','[["What was his initial reaction?","واکنش اولیه او چه بود؟"],["Stealing a painting or small object may be easy initially.","دزدیدن یک نقاشی یا شیء کوچک ممکن است در ابتدا آسان باشد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:initially','initially','adv','در ابتدا','/iˈniSHəlē/ · originally, at first [adv]','Felix tried to brush it off initially.','[["Felix tried to brush it off initially.","فلیکس اول سعی کرد بی‌خیالش شود."],["Elias initially had no intention to eat.","الیاس در ابتدا قصد غذا خوردن نداشت."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:innovation','innovation','n','نوآوری','/ˌinəˈvāSHən/ · new, novelty','The printing press was a major innovation.','[["The printing press was a major innovation.","چاپخانه یک نوآوری بزرگ بود."],["Innovation is the key to the company''s success.","نوآوری کلید موفقیت شرکت است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:instant','instant','adj','فوری، آنی؛ لحظه','/ˈinstənt/ · [adjective], immediate [noun], a moment','Do you believe in instant attraction?','[["Do you believe in instant attraction?","آیا به جذب فوری اعتقاد دارید؟"],["In an instant, life changed forever.","در یک لحظه، زندگی برای همیشه تغییر کرد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:institute','institute','n','موسسه؛ بنیاد نهادن، برقرار کردن','/ˈɪnstɪtjuːt/ · [noun], academy. [verb], to introduce or start a system, establishe','They have instituted new policies to increase public safety.','[["They have instituted new policies to increase public safety.","آنها سیاست‌های جدیدی را برای افزایش امنیت عمومی وضع کرده اند."],["For that reason, some schools have instituted “reality training” for social networkers.","به همین دلیل، برخی دانشگاه‌ها «آموزش واقعیت» را برای کاربران شبکه‌های اجتماعی راه انداخته‌اند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intense','intense','adj','شدید','/ɪnˈtens/ · strong, of extreme force, degree, or strength','The heat was intense.','[["The heat was intense.","گرما شدید بود."],["She felt intense pressure before the exam.","قبل از امتحان فشار شدیدی را احساس می‌کرد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:judge','judge','n','قاضی، داور؛ قضاوت کردن','/dʒʌdʒ/ · estimate 1)noun, someone who decides on the result of a competition 2)verb, to decide on the result of a competition','Judging others only reflects your insecurities.','[["Judging others only reflects your insecurities.","قضاوت کردن دیگران فقط نشان دهنده‌ی ناامنی‌های شماست."],["You are nobody to judge me.","تو کسی نیستی که بخوای منو قضاوت کنی."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:key','key','adj','بسیار مهم و ضروری','/kiː/ · significant, critical, of paramount or crucial importance','I lost my keys last night.','[["I lost my keys last night.","دیشب کلیدهام رو گم کردم."],["I gave my friend his keys.","کلیدها را به دوستم دادم."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:landscape','landscape','n','چشم انداز، منظره','/ˈlænd.skeɪp/ · scenery, a large area of countryside, a view or picture of the countryside, or the art of making such pictures','Glaciers shaped the landscape.','[["Glaciers shaped the landscape.","یخچال‌های طبیعی منظره را شکل داده اند."],["The desert landscape was beautiful at sunset.","منظره کویر هنگام غروب زیبا بود."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:large','large','adj','بزرگ، وسیع','/lɑːrdʒ/ · extensive, big','What is this new, large building?','[["What is this new, large building?","این ساختمان جدید و بزرگ چیست؟"],["A large animal is eating you.","یک حیوان بزرگ دارد تو را می‌خورد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:largely','largely','adv','تاحد زیادی، به طور عمده','/ˈlɑːrdʒ.li/ · mostly or mainly','The success of the project was largely due to her hard work.','[["The success of the project was largely due to her hard work.","موفقیت این پروژه تا حد زیادی به دلیل سخت کوشی او بود."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:launch','launch','v','راه اندازی کردن، شروع کردن','/lɑːntʃ/ · initiate, start, embark','The investigation has been launched.','[["The investigation has been launched.","تحقیقات آغاز شده است."],["They launched a new mission.","آنها ماموریت جدیدی را آغاز کردند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:liberal','liberal','adj','گسترده در زمینه آموزش','/ˈlɪbərəl/ · extensive, vast, wide','The miners may enjoy a rough kind of fun—including occasional fights—but the community takes a liberal attitude toward this behavior.','[["The miners may enjoy a rough kind of fun—including occasional fights—but the community takes a liberal attitude toward this behavior.","معدنچیان شاید از نوعی تفریح خشن — از جمله دعواهای گاه‌به‌گاه — لذت ببرند، اما جامعه نگرشی آزادمنشانه نسبت به این رفتار دارد."],["Is this politician conservative or liberal?","آیا این سیاستمدار محافظه‌کار است یا لیبرال؟"]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:link','link','v','متصل کردن','/lɪŋk/ · connect, consist of, put together','He retained strong links with the media.','[["He retained strong links with the media.","او ارتباط قوی با رسانه‌ها داشت."],["He believed that each area of the brain was linked to a certain behavior, such as bravery.","او باور داشت که هر ناحیهٔ مغز به رفتار خاصی، مانند شجاعت، مربوط است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:maintain','maintain','v','نگه داشتن، حفظ کردن، ادامه دادن','/meɪnˈteɪn/ · continue, preserve, cause or enable (a condition or state of affairs) to continue','It is hard to maintain an old house.','[["It is hard to maintain an old house.","نگهداری از یک خانه قدیمی سخت است."],["It''s important to maintain a healthy weight.","حفظ وزن سالم بسیار مهم است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:make-one-s-way','make one''s way','phr','رفتن، راه خود را پیمودن','travel, to go towards something','The explorers made their way slowly through the thick forest.','[["The explorers made their way slowly through the thick forest.","کاوشگران به آرامی از میان جنگل انبوه عبور کردند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:manage','manage','v','اداره کردن، گرداندن','/ˈmænɪdʒ/ · be able, administer','She manages a small team.','[["She manages a small team.","او یک تیم کوچک را مدیریت می‌کند."],["How did you manage to finish so fast?","چطور توانستی اینقدر سریع تمام کنی؟"]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:marked','marked','adj','مشخص، علامتدار','/mɑːrkt/ · considerable, significant, clearly noticeable; evident','Your face is marked with melancholy.','[["Your face is marked with melancholy.","چهره‌ات پر از غم و اندوه است."],["Miroslav marked that in his journal.","میروسلاو این را در دفتر خاطراتش ثبت کرد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mask','mask','n','نقاب، ماسک؛ پوشاندن، پنهان کردن','/mæsk/ · 1) cover, disguise.2) 2 to hide your feelings or the truth about a situation','Jorge was kidnapped by masked thugs.','[["Jorge was kidnapped by masked thugs.","خورخه توسط اراذل و اوباش نقابدار ربوده شد."],["Too much makeup can mask individuality.","آرایش زیاد می‌تواند فردیت را بپوشاند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:massive','massive','adj','عظیم، بزرگ، کلان','/massive/ · enormous, huge, vast, large and heavy or solid','He launched a massive search operation.','[["He launched a massive search operation.","او عملیات جستجوی گسترده‌ای را آغاز کرد."],["He lived in a massive house.","او در یک خانه‌ی بزرگ و مجلل زندگی می‌کرد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:matter','matter','n','موضوع، ماده','/ˈmætər/ · issue, affair','He kept calm no matter what.','[["He kept calm no matter what.","او تحت هر شرایطی آرامش خود را حفظ کرد."],["My faith is a private matter.","ایمان من یک مسئله خصوصی است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:maximum','maximum','n','بیشترین، بیشینه','/ˈmæksəməm/ · greatest size, the greatest or highest amount possible','He faces a maximum of seven years in prison.','[["He faces a maximum of seven years in prison.","او با حداکثر هفت سال زندان مواجه است."],["The goal is always the maximum profit.","هدف همیشه حداکثر سود است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mean','mean','n','متوسط، میانگین','/miːn/ · average, medium, mediocre','What meaning does your life have?','[["What meaning does your life have?","زندگی شما چه معنایی دارد؟"],["Do you know what aorist means?","آیا می‌دانید ماضی به چه معناست؟"]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:merely','merely','adv','فقط، صرفا، همین قدر','/ˈmɪr.li/ · no more than, only, simply, just(used to emphasize how small or unimportant something or someone is)','I am merely stating the obvious here.','[["I am merely stating the obvious here.","من اینجا فقط بدیهیات را بیان می‌کنم."],["It was merely a matter of time.","فقط مسئله زمان بود."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:minute','minute','adj','بسیار کوچک','/maɪˈnut/ · very small, tiny, minuscule, miniature','The train is fiften minutes late.','[["The train is fiften minutes late.","قطار پانزده دقیقه تأخیر دارد."],["I drew that in five minutes.","من آن را در پنج دقیقه کشیدم."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mirror','mirror','v','منعکس کردن','/ˈmɪrər/ · reflect, show a reflection of','Stay away from windows and mirrors.','[["Stay away from windows and mirrors.","از پنجره‌ها و آینه‌ها دور بمانید."],["I saw you in the mirror.","تو را در آینه دیدم."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mode','mode','n','سبک، طرز، طریقه','/moʊd/ · manner, style, method','Cars, buses, and trains are popular modes of transportation.','[["Cars, buses, and trains are popular modes of transportation.","ماشین‌ها، اتوبوس‌ها و قطارها روش‌های محبوب حمل‌ونقل هستند."],["I was in full paranoia mode.","من در حالت پارانویای کامل بودم."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:monitor','monitor','v','نظارت کردن','/ˈmɒnɪtə/ · observe, check the progress or quality of (something) over a period of time','The temperature is carefully monitored.','[["The temperature is carefully monitored.","دما به دقت کنترل می‌شود."],["If a fan’s picture matches one in the database, security officials could closely monitor him or her and perhaps even make an arrest.","اگر عکس یک تماشاگر با عکسی در پایگاه داده مطابقت داشت، مقامات امنیتی می‌توانستند او را از نزدیک زیر نظر بگیرند و شاید حتی بازداشتش کنند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mount','mount','v','بالا رفتن، صعود کردن، سوار شدن','/maʊnt/ · grow, climb, increase, climb up (stairs, a hill, or other rising surface)','And he mounted a cherub and flew.','[["And he mounted a cherub and flew.","و او بر کروبی سوار شد و پرواز کرد."],["They mounted their horses and rode off.","سوار اسب‌هایشان شدند و رفتند."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:narrow','narrow','v','محدود کردن','/ˈnærəʊ/ · limit, restrict, confine, curb [v]','I drove down a narrow road.','[["I drove down a narrow road.","در یک جاده باریک رانندگی کردم."],["She squeezed into that narrow space.","او خودش را در آن فضای تنگ جا داد."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:nature','nature','n','طبیعت، ذات','/ˈneɪtʃə/ · character, disposition, temperament','Miracles happen every day in nature.','[["Miracles happen every day in nature.","معجزه هر روز در طبیعت اتفاق می‌افتد."],["Human nature is hard to change.","ذات انسان به سختی قابل تغییر است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:nearly','nearly','adv','تقریباً','/ˈnɪəli/ · almost, closely, approximately','I nearly drowned because of you.','[["I nearly drowned because of you.","نزدیک بود به خاطر تو غرق بشم."],["That''s nearly impossible to read.","خواندن آن تقریباً غیرممکن است."]]','t1212',4,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:necessary','necessary','adj','لازم، ضروری، واجب','/ˈnesəseri/ · required','Is it necessary to book in advance?','[["Is it necessary to book in advance?","آیا نیاز به رزرو قبلی هست؟"],["The doctor said surgery was necessary.","دکتر گفت عمل جراحی لازم است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:note','note','v','توجه کردن، اشاره کردن، یادداشت کردن','/noʊt/ · record, something that you write down to remind you of something','Everything he observed, he noted down.','[["Everything he observed, he noted down.","هر چیزی را که مشاهده می‌کرد، یادداشت می‌کرد."],["Other influences are important to note.","توجه به سایر تأثیرات نیز حائز اهمیت است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:notice','notice','n','اطلاع، خبر','/ˈnəʊtɪs/ · a written announcement / statement','Yes, we had noticed that too.','[["Yes, we had noticed that too.","بله، ما هم متوجه این موضوع شده بودیم."],["I noticed that back then, too.","من هم آن موقع متوجه این موضوع شدم."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:novel','novel','adj','جدید','/ˈnɑː.vəl/ · new','What is this adventure novel about?','[["What is this adventure novel about?","این رمان ماجراجویی درباره چیست؟"],["They read too many spy novels.","آنها رمان‌های جاسوسی زیادی می‌خوانند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:now-and-then','now and then','phr','گاهی اوقات','occasionally','Everyone slips up now and then.','[["Everyone slips up now and then.","هر از گاهی همه اشتباه می‌کنند."],["Now and then, I miss you.","حالا و بعد، دلم برات تنگ میشه."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:objective','objective','n','هدف','/əbˈdʒektɪv/ · purpose, target, aim, goal','to achieve/meet/accomplish your objectives','[["to achieve/meet/accomplish your objectives","برای دستیابی به / برآورده کردن / دستیابی به اهداف خود"],["Objective analysis requires avoiding personal bias.","تحلیل عینی مستلزم اجتناب از سوگیری شخصی است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:obtain','obtain','v','بدست اوردن، فراهم کردن، گرفتن','/əbˈteɪn/ · acquire','You will need to obtain permission from the principal.','[["You will need to obtain permission from the principal.","شما باید از مدیر اصلی اجازه بگیرید."],["Rain filled lakes and rivers where they could obtain water to drink and catch fish to eat.","باران دریاچه‌ها و رودخانه‌ها را پر می‌کرد؛ جایی که می‌توانستند آب برای نوشیدن به دست آورند و ماهی بگیرند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:obvious','obvious','adj','بدیهی، اشکار، مشهود','/ˈɑːbviəs/ · evident, clear','The answer is obvious.','[["The answer is obvious.","پاسخ واضح است."],["It''s obvious that she is very talented.","معلوم است که او بسیار با استعداد است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:obviously','obviously','adv','به‌طور آشکار یا معلوم، بدیهی است که','/ˈɑːbviəsli/ · clearly, apparently','Obviously, it was an unsubstantiated rumour.','[["Obviously, it was an unsubstantiated rumour.","بدیهی است که این یک شایعه بی‌اساس بود."],["You guys are obviously extremely busy.","معلومه سرتون خیلی شلوغه."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:occasion','occasion','n','فرصت مناسب، موقعیت، پیشامد','/əˈkeɪʒən/ · event, moment, occurrence','It is the perfect occasion.','[["It is the perfect occasion.","این مناسبت بی‌نظیری است."],["It was a riotous occasion.","این یک مناسبت آشوبگرانه بود."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:occasionally','occasionally','adv','گهگاه، گاه و بیگاه، بعضی از اوقات','/əˈkeɪʒənəli/ · once in a while','Learning a language occasionally leads to fluency.','[["Learning a language occasionally leads to fluency.","یادگیری یک زبان گاهی اوقات منجر به تسلط بر آن زبان می‌شود."],["Speech, occasionally, fails to articulate human sentiments.","گفتار، گاهی اوقات، از بیان احساسات انسانی عاجز می‌ماند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:on-the-whole','on the whole','phr','در کل، به طور عمده','1)in general 2)mainly','Americans, on the whole, are talkative people.','[["Americans, on the whole, are talkative people.","آمریکایی‌ها، در کل، آدم‌های پرحرفی هستند."],["The television was on the whole time.","تلویزیون تمام مدت روشن بود."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ongoing','ongoing','adj','جاری، در دست اقدام','/ˈɑːnˌɡoʊɪŋ/ · current','The negotiations are still ongoing.','[["The negotiations are still ongoing.","مذاکرات همچنان ادامه دارد."],["Research into the disease is ongoing.","تحقیقات در مورد این بیماری ادامه دارد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:option','option','n','گزینه، انتخاب','/ˈɑːpʃən/ · choice, alternative','You have the options of staying home or coming with us.','[["You have the options of staying home or coming with us.","شما گزینه‌های ماندن در خانه یا آمدن با ما را دارید."],["For me, war is an option.","برای من، جنگ یک گزینه است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:originally','originally','adv','دراصل، در آغاز کار، در ابتدا','/əˈrɪdʒənəli/ · at the first','The structure was originally a monastery.','[["The structure was originally a monastery.","این بنا در اصل یک صومعه بوده است."],["Many great truths were originally blasphemous.","بسیاری از حقایق بزرگ در ابتدا کفرآمیز بودند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:outcome','outcome','n','پی امد، حاصل، نتیجه','/ˈaʊtkʌm/ · result','It was impossible to predict the outcome of the election.','[["It was impossible to predict the outcome of the election.","پیش بینی نتیجه انتخابات غیرممکن بود."],["The outcome of the experiment was surprising.","نتیجه آزمایش شگفت آور بود."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pace','pace','n','تندی، سرعت، گام','/peɪs/ · speed','I process things at a quick pace.','[["I process things at a quick pace.","من با سرعت بالایی مسائل را پردازش می‌کنم."],["How do I slow down my pace?","چطور سرعتم رو کم کنم؟"]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:particularly','particularly','adv','به خصوص، مخصوصاً','/pərˈtɪkjələrli/ · especially','They have always lived particularly frugally.','[["They have always lived particularly frugally.","آنها همیشه به طور خاص با صرفه جویی زندگی کرده اند."],["Elias is not particularly strong himself.","الیاس خودش خیلی قوی نیست."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:partly','partly','adv','تاحدی، نسبتاً','/ˈpɑːrtli/ · in some degree','You''ve been found partly responsible.','[["You''ve been found partly responsible.","تو تا حدی مسئول شناخته شدی."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:peak','peak','n','نقطه ماکزیمم','/piːk/ · 1)top 2)highest point 3)maximum 4)time of the greatest activity 5)summit/climax','Sales peaked in July.','[["Sales peaked in July.","فروش در ماه جولای به اوج خود رسید."],["Traffic usually peaks at eight in the morning.","اوج ترافیک معمولا ساعت هشت صبح است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:permanent','permanent','adj','پایا، همیشگی، دایمی، پایدار','/ˈpɜːrmənənt/ · 1)forever 2)lasting','He is looking for a permanent position.','[["He is looking for a permanent position.","او به دنبال یک موقعیت دائمی است."],["Did you say this was permanent?","گفتی این دائمیه؟"]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:personality','personality','n','شخصیت، هویت','/ˌpɜːrsəˈnæləti/ · character, trait','He has a very strong personality.','[["He has a very strong personality.","او شخصیت بسیار قوی‌ای دارد."],["Animals, just like humans, have personalities.","حیوانات، درست مانند انسان‌ها، شخصیت دارند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:piece-together','piece together','phr','سر هم کردن و بهم متصل کردن قطعات و پاره‌های چیزی','/piːs/ · joining, to put all the separate parts of an object into the correct order or position','She seamed the two crocheted pieces together.','[["She seamed the two crocheted pieces together.","او دو تکه قلاب‌بافی شده را به هم دوخت."],["I''m trying to piece together what happened.","دارم سعی می‌کنم اتفاقات رو کنار هم بذارم."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:popular','popular','adj','محبوب، مشهور','/ˈpɑːpjələr/ · broad appeal, widespread','Football is popular all over the world.','[["Football is popular all over the world.","فوتبال در سراسر جهان محبوب است."],["Football is the most popular sport in Iran.","فوتبال پرطرفدارترین ورزش ایران است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:portion','portion','n','بخش، قسمت','/ˈpɔːrʃn/ · constituent, part, a part of a whole; an amount or piece of something','I accept my portion of the blame.','[["I accept my portion of the blame.","من سهم خود را از تقصیر می‌پذیرم."],["Our portion has been eaten.","سهم ما خورده شد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:potential','potential','adj','بالقوه، پتانسیل، استعداد','/pəˈtenʃəl/ · 1) possible-latent (adj) 2)capability','This student has great potential.','[["This student has great potential.","این دانش آموز پتانسیل بالایی دارد."],["Solar energy has enormous potential.","انرژی خورشیدی پتانسیل بسیار بالایی دارد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:precious','precious','adj','گرانبها، ارزشمند','/ˈpreʃ.əs/ · valuable','Time is more precious than money.','[["Time is more precious than money.","زمان از پول گرانبهاتر است."],["He knows this time is precious.","او می‌داند که این زمان ارزشمند است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:previous','previous','adj','قبلی','/ˈpriːviəs/ · past','I had met them the previous day.','[["I had met them the previous day.","روز قبل آنها را ملاقات کرده بودم."],["Previously, elevators had been used for lifting things on ships or in factories.","پیش از آن، از آسانسورها برای بالا بردن اجناس در کشتی‌ها یا کارخانه‌ها استفاده می‌شد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:previously','previously','adv','قبلا','/ˈpriːviəsli/ · before','Previously, they were like us.','[["Previously, they were like us.","قبلاً آنها مثل ما بودند."],["Tom was a soldier previously.","تام قبلاً سرباز بود."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:primarily','primarily','adv','در درجه اول','/praɪˈmerəli/ · mainly','The language is primarily spoken within families.','[["The language is primarily spoken within families.","این زبان عمدتاً در خانواده‌ها صحبت می‌شود."],["The report primarily references opinion articles.","این گزارش عمدتاً به مقالات نظری اشاره دارد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:primary','primary','adj','اولیه','/ˈpraɪmeri/ · dominant','Their primary objective is to make money.','[["Their primary objective is to make money.","هدف اصلی آنها کسب درآمد است."],["She teaches at a primary school.","او در یک مدرسه ابتدایی تدریس می‌کند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prime','prime','adj','نخست','/praɪm/ · main','Smoking is the prime cause of lung disease.','[["Smoking is the prime cause of lung disease.","سیگار عامل اصلی بیماری‌های ریوی است."],["2 is a prime number.","عدد ۲ یک عدد اول است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:principal','principal','adj','اصلی، ضروری، عمده','/ˈprɪnsəpəl/ · essential, major','His principal reason for making the journey was to visit his family.','[["His principal reason for making the journey was to visit his family.","دلیل اصلی او برای این سفر دیدار با خانواده اش بود."],["Have you guys seen the principal?","بچه‌ها، مدیر مدرسه رو دیدید؟"]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:principle','principle','n','اصل، قانون، استاندارد','/ˈprɪnsəpəl/ · rule, standard','the basic principles of business management','[["the basic principles of business management","اصول اساسی مدیریت کسب و کار"],["The machine works on a simple principle.","دستگاه بر اساس یک اصل ساده کار می‌کند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prior','prior','adj','قبلی','/ˈpraɪər/ · previous, before','The defendant had a prior record of convictions.','[["The defendant had a prior record of convictions.","متهم سابقه محکومیت قبلی داشت."],["We had a prior commitment.","ما از قبل تعهد داشتیم."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:priority','priority','n','اولویت','/praɪˈɔːrəti/ · ranking preference','Safety is our top priority.','[["Safety is our top priority.","ایمنی اولویت اصلی ماست."],["Safety should be our first priority.","ایمنی باید اولویت اول ما باشد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:process','process','n','روند','/ˈprɑːses/ · purify, cater, perform a series of mechanical or chemical operations on (something) in order to change or preserve it','Photosynthesis is a complex process.','[["Photosynthesis is a complex process.","فتوسنتز یک فرآیند پیچیده است."],["Learning a language is a slow process.","یادگیری زبان فرآیندی کند است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prominent','prominent','adj','برجسته، اصلی، مهم','/ˈprɑːmɪnənt/ · eminent, principal, outstanding, important, preeminent','She is a prominent scientist.','[["She is a prominent scientist.","او یک دانشمند برجسته است."],["The castle stands in a prominent position on the hill.","این قلعه در موقعیت برجسته ای بر روی تپه قرار دارد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:promote','promote','v','بالا بردن؛ تشویق کردن','/prəˈmoʊt/ · encourage, enhance, advocate','The campaign promotes healthy eating.','[["The campaign promotes healthy eating.","این کمپین تغذیه سالم را ترویج می‌کند."],["She was promoted to manager.","او به سمت مدیر ارتقا یافت."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:property','property','n','ویژگی، مشخصه، کیفیت','/ˈprɑːpərti/ · characteristic, quality, an attribute of something','The property will soon be redeveloped.','[["The property will soon be redeveloped.","ملک به زودی بازسازی خواهد شد."],["I was sleeping on public property.","من در ملک عمومی خوابیده بودم."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:proposal','proposal','n','پیشنهاد','/prəˈpoʊzəl/ · suggestion, idea, offer, scheme','I completely agree with this proposal.','[["I completely agree with this proposal.","من کاملاً با این پیشنهاد موافقم."],["I feel fascinated by that proposal.","احساس می‌کنم مجذوب آن پیشنهاد شده‌ام."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:provided','provided','conj','اگر','/prəˈvaɪdɪd/ · if, while, on the condition or understanding that','The fig provided shade this year.','[["The fig provided shade this year.","امسال انجیر سایه ایجاد کرد."],["He received everything they provided him.","او هر آنچه را که آنها برایش فراهم می‌کردند، دریافت می‌کرد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:quarter','quarter','n','خوابگاه','/ˈkwɔːrtər/ · residences, rooms that are provided for soldiers, servants, etc. to live in, district','What is the method for quartering?','[["What is the method for quartering?","روش کوارتر کردن چیست؟"],["Four horses quartered the condemned man.","چهار اسب مرد محکوم را چهارنعل بستند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:radical','radical','adj','شدید، مفرط','/ˈrædɪkəl/ · drastic, extreme, fundamental','The government introduced radical changes to the education system.','[["The government introduced radical changes to the education system.","دولت تغییرات اساسی در نظام آموزشی ایجاد کرد."],["He promised to do things radically different.","او قول داد که کارها را کاملاً متفاوت انجام دهد."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:random','random','adj','تصادفی، شانسی','/ˈrændəm/ · chance, arbitrary','The computer will generate apparently random numbers.','[["The computer will generate apparently random numbers.","کامپیوتر اعداد ظاهرا تصادفی تولید می‌کند."],["These similarities seemed too numerous to be random coincidences.","این شباهت‌ها بیش از آن بودند که تصادفی باشند."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:range','range','v','در بر گرفتن','/preposition]/ · vary, to include a variety of different things or people in addition to those mentioned','The drug is effective against a range of bacteria.','[["The drug is effective against a range of bacteria.","این دارو در برابر طیف وسیعی از باکتری‌ها موثر است."],["Tom must be out of range.","تام حتماً از دسترس خارج شده است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rare','rare','adj','نادر، کمیاب، غیر معمول','/rer/ · scarce, unusual, infrequent','This is a rare bird.','[["This is a rare bird.","این پرنده کمیاب است."],["It''s rare to see snow in Bushehr.","به ندرت در بوشهر برف دیده می‌شود."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rate','rate','n','نرخ، میزان؛ ارزیابی کردن','/reɪt/ · classify, consider to be of a certain quality, standard, or rank.','The unemployment rate rose to 8 percent.','[["The unemployment rate rose to 8 percent.","نرخ بیکاری به 8 درصد رسید."],["The birth rate has fallen in many countries.","نرخ تولد در بسیاری از کشورها کاهش یافته است."]]','t1212',5,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rather-than','rather than','phr','به جای','/ˈræðər ðən/ · instead of','Hand in hand, rather than betraying!','[["Hand in hand, rather than betraying!","دست در دست هم، به جای خیانت!"],["I felt sad rather than angry.","بیشتر از اینکه عصبانی باشم، احساس غم می‌کردم."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ready','ready','adj','آماده، پذیرا','/ˈredi/ · receptive','Are you ready to go?','[["Are you ready to go?","برای رفتن آماده ای؟"],["Are you ready for the exam?","آیا برای امتحان آماده اید؟"]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reasonable','reasonable','adj','معقول، منصفانه و معقول','/ˈriːzənəbəl/ · fair and sensible, suitable','The prices are very reasonable.','[["The prices are very reasonable.","قیمت‌ها بسیار مناسب است."],["There must be a reasonable explanation.","باید توضیح معقولی وجود داشته باشد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:refuse','refuse','v','رد کردن، نپذیرفتن؛ زباله','/ˈrefuːs/ · 1) [n] garbage, trash, waste, 2) [v] reject','He refused to answer the question.','[["He refused to answer the question.","او از پاسخ دادن به سوال خودداری کرد."],["She refused the job offer.","او پیشنهاد کار را رد کرد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:regardless','regardless','adv','بدون در نظر گرفتن، صرفنظر از','/riˈgärdləs/ · without considering','We all deserve respect, regardless of status.','[["We all deserve respect, regardless of status.","همه ما، صرف نظر از جایگاه و مقام، شایسته احترام هستیم."],["He came regardless of my instructions.","او بدون توجه به دستور من آمد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:relative','relative','adj','نسبی، فامیلی، مرتبط','/ˈrelətɪv/ · comparative.1.noun, relation. 2.adjective, having a particular quality when compared with something else','I have relatives in that village.','[["I have relatives in that village.","من در آن روستا اقوامی دارم."],["Have you got any relatives abroad?","آیا در خارج از کشور اقوامی دارید؟"]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reputation','reputation','n','شهرت','/ˌrepjəˈteɪʃən/ · fame nfamous adj','Cooperation enhances one''s reputation in a group.','[["Cooperation enhances one''s reputation in a group.","همکاری باعث افزایش شهرت فرد در یک گروه می‌شود."],["His reputation is built on reliability.","شهرت او بر پایه قابل اعتماد بودن بنا شده است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reserve','reserve','v','ذخیره کردن، اندوختن','/rɪˈzɜːv/ · save','Did you reserve a hotel room?','[["Did you reserve a hotel room?","اتاق هتل رزرو کردی؟"],["Did you reserve the whole place?","کل جا رو رزرو کردی؟"]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:resident','resident','n','ساکن، مقیم','/ˈrezɪdənt/ · inhabitant','Many local inhabitants have objected to the scheme.','[["Many local inhabitants have objected to the scheme.","بسیاری از ساکنان محلی با این طرح مخالفت کرده اند."],["The criminal is terrifying local residents.","این جنایتکار ساکنان محلی را وحشت زده کرده است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reveal','reveal','v','آشکار کردن','/rɪˈviːl/ · manifest, reveal, show, make known','The report revealed some surprising facts.','[["The report revealed some surprising facts.","این گزارش حقایق شگفت انگیزی را فاش کرد."],["The investigation revealed new information.","تحقیقات اطلاعات جدیدی را فاش کرد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:revenue','revenue','n','درآمد','/ˈrevənjuː/ · income','Tourism generates substantial tax revenue.','[["Tourism generates substantial tax revenue.","گردشگری درآمد مالیاتی قابل توجهی ایجاد می‌کند."],["Nevertheless, other companies have sped past you in the race for fame and the revenue that goes with it.","با این حال، شرکت‌های دیگر در رقابت برای شهرت و درآمدی که با آن همراه است از شما جلو زده‌اند."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:revolution','revolution','n','تغییر اساسی','/ˌrevəˈluːʃən/ · dramatic change','The king knew that there was a threat of revolution.','[["The king knew that there was a threat of revolution.","شاه می‌دانست که خطر انقلاب وجود دارد."],["The Industrial Revolution began in Britain.","انقلاب صنعتی در بریتانیا آغاز شد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rise','rise','v','ظهور کردن','/raɪz/ · emerge','In the east, the sun rises.','[["In the east, the sun rises.","در شرق، خورشید طلوع می‌کند."],["Rents are rising in major cities.","اجاره بها در شهرهای بزرگ رو به افزایش است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:risk','risk','n','خطر','/rɪsk/ · danger','I was aware of the risks.','[["I was aware of the risks.","من از خطرات آگاه بودم."],["I take risks that pay off.","من ریسک‌هایی را می‌پذیرم که نتیجه می‌دهند."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:role','role','n','نقش، وظیفه','/rəʊl/ · function','They want to limit the role of government.','[["They want to limit the role of government.","آنها می‌خواهند نقش دولت را محدود کنند."],["Evidence suggests that both play a role in determining ambition.","شواهد نشان می‌دهد که هر دو در تعیین جاه‌طلبی نقش دارند."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:roughly','roughly','adv','تقریباً','/ˈrʌfli/ · almost, approximately','Our event has roughly fifty participants.','[["Our event has roughly fifty participants.","رویداد ما تقریباً پنجاه شرکت‌کننده دارد."],["Boris was roughly fourteen kilometers away.","بوریس تقریباً چهارده کیلومتر دورتر بود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:route','route','n','مسیر، راه','/ruːt/ · path n','We live on a rural route.','[["We live on a rural route.","ما در یک مسیر روستایی زندگی می‌کنیم."],["The Silk Road was a famous trade route.","جاده ابریشم یک مسیر تجاری معروف بود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sample','sample','n','نمونه','/ˈsɑːmpəl/ · example','A preoperative sample is necessary.','[["A preoperative sample is necessary.","نمونه برداری قبل از عمل ضروری است."],["Are they collecting samples today?","آیا امروز نمونه‌ها را جمع‌آوری می‌کنند؟"]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:save-for','save for','prep','به جز','/seɪv fər/ · except for','Everything was quiet, save for the wind.','[["Everything was quiet, save for the wind.","همه جا ساکت بود، جز باد."],["The best is saved for last.","بهترین برای آخر نگه داشته می‌شود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scale','scale','n','مقیاس، اندازه','/skeɪl/ · magnitude','The map''s scale shows the real-world distance.','[["The map''s scale shows the real-world distance.","مقیاس نقشه فاصله دنیای واقعی را نشان می‌دهد."],["The scales of this snake are black.","فلس‌های این مار سیاه است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:score','score','n','تعداد زیادی از','/skɔːr/ · a large number of n.','Whoever scores the most points, wins.','[["Whoever scores the most points, wins.","هر کس بیشترین امتیاز را کسب کند، برنده می‌شود."],["He writes scores for independent films.","او برای فیلم‌های مستقل موسیقی متن می‌نویسد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:screen','screen','v','محافظت کردن، جلوگیری کردن، فیلتر کردن','/skriːn/ · filter v','The screen is too small to read.','[["The screen is too small to read.","صفحه نمایش برای خواندن خیلی کوچک است."],["He was glued to the screen.","او به صفحه نمایش چسبیده بود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:seek','seek','v','در جستجوی (موضوعی غیر فیزیکی)، تلاش برای','/siːk/ · attempt','During the war, she sought asylum in Spain.','[["During the war, she sought asylum in Spain.","در طول جنگ، او از اسپانیا درخواست پناهندگی کرد."],["They are seeking jobs in a city.","آن‌ها در شهر به دنبال کار هستند."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:separate','separate','adj','جداگانه، مختلف، متمایز','/ˈsep.ɚ.ət/ · different','I will answer this question separately.','[["I will answer this question separately.","من به این سوال جداگانه پاسخ خواهم داد."],["Some words should be written separate.","بعضی از کلمات باید جدا نوشته شوند."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sequence','sequence','n','دنباله، رشته، توالی، سری','/ˈsiː.kwəns/ · series','Put the events in the correct sequence.','[["Put the events in the correct sequence.","وقایع را در ترتیب صحیح قرار دهید."],["The DNA sequence of the virus has been identified.","توالی DNA ویروس شناسایی شده است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:set-in','set in','phr','شروع شدن (و ادامه یافتن)','/set in/ · start','Nothing is set in stone yet.','[["Nothing is set in stone yet.","هنوز هیچ چیز قطعی نشده است."],["Monotony can set in over time.","یکنواختی می‌تواند به مرور زمان ایجاد شود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:set-off','set off','phr','به راه انداختن، باعث شدن؛ راهی شدن','/set off/ · begin','When will we set off?','[["When will we set off?","کی راه می‌افتیم؟"],["Vladimir set off the fireworks.","ولادیمیر آتش بازی را روشن کرد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:settle','settle','v','ساکن شدن، ته نشین شدن، مستقر شدن','/ˈset.əl/ · inhabit','He settled in a big city.','[["He settled in a big city.","او در یک شهر بزرگ ساکن شد."],["I settled in for the night.","من برای شب مستقر شدم."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:severe','severe','adj','شدید، خشن','/səˈvɪr/ · harsh','All of his illnesses are severe.','[["All of his illnesses are severe.","همه بیماری‌هایش شدید است."],["He has contracted a severe disease.","او به بیماری سختی مبتلا شده است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shield','shield','n','محافظ، سپر','/ʃiːld/ · protect','I lied to shield you.','[["I lied to shield you.","برای محافظت از تو دروغ گفتم."],["Ziri attempted to shield himself.","زیری سعی کرد خودش را سپر کند."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shift','shift','v','تغییر، تغییر مکان، شیفت دادن','/ʃɪft/ · change, move','a marked shift in attitudes towards women','[["a marked shift in attitudes towards women","تغییر چشمگیر نگرش نسبت به زنان"],["As the sun shifted across the sky, the short piece of wood created shadows on the long piece.","همان‌طور که خورشید در آسمان جابه‌جا می‌شد، تکه‌چوب کوتاه روی تکه‌چوب بلند سایه می‌انداخت."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:significant','significant','adj','قابل توجه، معنادار، مهم','/sɪɡˈnɪf.ə.kənt/ · meaningful, important','There was a significant drop in crime.','[["There was a significant drop in crime.","کاهش قابل توجهی در جرم و جنایت وجود داشت."],["There has been a significant increase in prices.","افزایش قابل توجهی در قیمت‌ها داشته است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:site','site','n','محل، موقعیت، جا، مکان','/saɪt/ · locate','Hard hats must be worn on the construction site.','[["Hard hats must be worn on the construction site.","کلاه‌های سخت باید در محل ساخت و ساز استفاده شود."],["She was told that a police detective would be at the site in a few minutes.","به او گفته شد که یک کارآگاه پلیس تا چند دقیقهٔ دیگر در محل خواهد بود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:size-up','size up','phr','ارزیابی کردن، سنجیدن','reckon up to, measure, assessreckon, to think or suppose somethingThe police reckon that whoever killed Dad was with him earlier that day.','Do you have this one in a size up?','[["Do you have this one in a size up?","اینو سایز بزرگتر هم دارید؟"],["He sized up the situation and acted immediately.","او اوضاع را ارزیابی کرد و فوراً اقدام کرد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:slightly','slightly','adv','کمی، تاحدودی، تاحدی','/ˈslaɪt.li/ · somewhat','He slightly tilted towards that side.','[["He slightly tilted towards that side.","کمی به آن سمت متمایل شد."],["I love you deeply, not slightly.","من تو را عمیقاً دوست دارم، نه جزئی."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:so-far','so far','phr','تاکنون، تا به حال، تا حال حاضر','/soʊ_fɑːr/ · until present, up to now, up to present','So far, everything is good.','[["So far, everything is good.","تا اینجا همه چیز خوب است."],["Nothing has happened so far.","تا الان که اتفاقی نیفتاده."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sort','sort','n','نوع، گونه','/sɔːrt/ · kind, type','This sort of thing rarely happens.','[["This sort of thing rarely happens.","این جور چیزا به ندرت اتفاق میفته."],["I need some sort of stimulation.","به یه جورایی تحریک نیاز دارم."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sought-after','sought-after','adj','مطلوب','/ˈsɑːt ˌæf.tɚ/ · desired','Adriano''s star quality made him a sought-after speaker at conferences.','[["Adriano''s star quality made him a sought-after speaker at conferences.","کیفیت بالای آدریانو، او را به سخنران محبوبی در کنفرانس‌ها تبدیل کرده بود."],["This is the most sought-after resort in all of the Bahamas.","این محبوب‌ترین تفرجگاه در تمام باهاما است."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:source','source','n','منبع','/sɔːrs/ · origin n.','The sun is the main source of energy.','[["The sun is the main source of energy.","خورشید منبع اصلی انرژی است."],["The sun warmed them and was a source of light.","خورشید آن‌ها را گرم می‌کرد و منبع نور بود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:speak-of','speak of','phr','نشان دادن','/spiːk ɑːv/ · indicate','Her silence speaks of strength.','[["Her silence speaks of strength.","سکوتش از قدرتش حکایت دارد."],["We speak of her positively.","ما درباره او مثبت صحبت می‌کنیم."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:specific','specific','adj','خاص','/spəˈsɪf.ɪk/ · particular','Could you be more specific about what you''re looking for?','[["Could you be more specific about what you''re looking for?","آیا می‌توانید در مورد آنچه به دنبال آن هستید دقیق‌تر بگویید؟"],["He wanted to know the specific time they had returned home.","او می‌خواست زمان دقیق بازگشت آن‌ها به خانه را بداند."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:specifically','specifically','adv','به طور مشخص','/spəˈsɪf.ɪ.kəl.i/ · specially','What specifically are you concerned about?','[["What specifically are you concerned about?","مشخصاً نگران چه چیزی هستید؟"],["I didn''t mean anyone specifically.","منظورم شخص خاصی نبود."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:speed','speed','v','سرعت گرفتن','/I)/ · increase the rate of v.','He often drives at dangerous speeds.','[["He often drives at dangerous speeds.","او اغلب با سرعت خطرناک رانندگی می‌کند."],["I was speeding the movie up.","داشتم سرعت فیلم رو زیاد می‌کردم."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spell','spell','n','دوره','/spel/ · period of time n.','Do you have a favorite spell?','[["Do you have a favorite spell?","آیا طلسم مورد علاقه‌ای دارید؟"],["Spell your first name for me.","اسم کوچکت را برایم هجی کن."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:split','split','v','شکافتن، قسمت کردن','/splɪt/ · divide','The people split into two parties.','[["The people split into two parties.","مردم به دو دسته تقسیم شدند."],["Congress is split over the issue.","کنگره بر سر این موضوع اختلاف نظر دارد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spot','spot','v','کشف کردن','/spɑːt/ · catch, identify, see','Excuse me, is this spot available?','[["Excuse me, is this spot available?","ببخشید، این مکان موجوده؟"],["Find me a free spot, please.","لطفا یه جای خالی برام پیدا کن."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spread','spread','v','انتشار دادن','/spred/ · distribute','The fire spread across the fields.','[["The fire spread across the fields.","آتش به مزارع سرایت کرد."],["He was spreading rumors in town.","او در شهر شایعه پراکنی می‌کرد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:steady','steady','adj','ثابت','/ˈsted.i/ · stable, constant, firm','He tried to keep his breathing steady.','[["He tried to keep his breathing steady.","سعی کرد نفس‌هایش را منظم نگه دارد."],["She loaded her rifle with steady hands.","او تفنگش را با دستانی محکم پر کرد."]]','t1212',6,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stem','stem','v','ناشی شدن از','/stem/ · arise','Cut the stems before putting the flowers in water.','[["Cut the stems before putting the flowers in water.","قبل از قرار دادن گل‌ها در آب، ساقه‌ها را ببرید."],["It stemmed from my parents neglect.","از بی‌توجهی پدر و مادرم سرچشمه می‌گرفت."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:strategy','strategy','n','استراتژی','/ˈstræt.ə.dʒi/ · plan','He was a genius when it came to military strategy.','[["He was a genius when it came to military strategy.","او در مورد استراتژی نظامی نابغه بود."],["Hydroponics is one strategy to help provide food to the billions of people on our planet.","هیدروپونیک یکی از راهبردها برای کمک به تأمین غذای میلیاردها انسانِ روی سیارهٔ ما است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:strike','strike','v','وارد شدن، برخورد کردن با','/straɪk/ · come into, contract with','The train drivers are on strike.','[["The train drivers are on strike.","رانندگان قطار در اعتصاب هستند."],["I saw lightning strike the house.","دیدم که رعد و برق به خانه برخورد کرد."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:string','string','n','رشته','/strɪŋ/ · series','The different colored strings indicate different fillings.','[["The different colored strings indicate different fillings.","رشته‌های رنگی مختلف، مواد پرکننده‌ی مختلف را نشان می‌دهند."],["Every life is a string of defeats.","هر زندگی رشته‌ای از شکست‌هاست."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:strip','strip','v','برهنه کردن، رفع کردن، خلع کردن','/strɪp/ · remove','Cut the pepper into strips.','[["Cut the pepper into strips.","فلفل را به صورت نواری برش دهید."],["Ziri removed the weather stripping.","زیری پوشش آب و هوا را برداشت."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:subject-to','subject to','phr','در معرض، دستخوش، منوط به','/ˈsʌb.dʒekt/ · vulnerable to','They were subjected to terrible conditions.','[["They were subjected to terrible conditions.","آنها در شرایط وحشتناکی قرار داشتند."],["Miroslav changed the subject to parenthood.","میروسلاو موضوع را به والدین بودن تغییر داد."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:subsequent','subsequent','adj','متعاقب','/ˈsʌb.sɪ.kwənt/ · ensuing, later, following in time','Subsequent studies confirmed the result.','[["Subsequent studies confirmed the result.","مطالعات بعدی نتیجه را تایید کرد."],["The disease and its subsequent treatment took a year.","این بیماری و درمان بعدی آن یک سال طول کشید."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:substantial','substantial','adj','اساسی، قابل توجه','/səbˈstæn.ʃəl/ · large amount/considerable, essential, sturdy, actual, significant, enough','We need more substantial evidence.','[["We need more substantial evidence.","ما به شواهد محکم‌تری نیاز داریم."],["There is a substantial difference!","تفاوت اساسی وجود دارد!"]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:suitable','suitable','adj','مناسب','/ˈsuː.tə.bəl/ · appropriate','The film is not suitable for children.','[["The film is not suitable for children.","این فیلم برای کودکان مناسب نیست."],["What is that suitable for?","اون برای چی مناسبه؟"]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:suspect','suspect','v','شک داشتن، سوء ظن داشتن، ظن کردن','/səˈspekt/ · believe, doubt','Why then would you suspect him?','[["Why then would you suspect him?","پس چرا باید به او شک کنی؟"],["Do the police have a suspect?","آیا پلیس مظنونی دارد؟"]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:take','take','v','نیاز داشتن، لازم داشتن، مستلزم بودن','/teɪkpleɪs/ · require','They enjoy taking jabs at me.','[["They enjoy taking jabs at me.","از اینکه به من ضربه بزنند لذت می‌برند."],["Hurry up and take a bath.","زود باش برو حمام کن."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:take-place','take place','phr','صورت گرفتن','/teɪkpleɪs/ · occur','The meeting takes place weekly.','[["The meeting takes place weekly.","جلسه به صورت هفتگی برگزار می‌شود."],["Leonid saw that take place.","لئونید شاهد این اتفاق بود."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:task','task','n','وظیفه، کار، تکلیف','/tæsk/ · work','perform/ complete a task','[["perform/ complete a task","انجام / تکمیل یک کار"],["Schools usually fail to accurately assess the abilities of autistic children because classroom tasks are not appropriate for them.","مدارس معمولاً نمی‌توانند توانایی‌های کودکان اوتیسمی را به‌درستی ارزیابی کنند، چون فعالیت‌های کلاس برای آن‌ها مناسب نیست."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:technique','technique','n','تکنیک، شیوه','/tekˈnik/ · method','We learned some techniques for relieving stress.','[["We learned some techniques for relieving stress.","چند تکنیک برای رهایی از استرس یاد گرفتیم."],["They also learned about new cooking techniques.","آن‌ها همچنین با روش‌های جدید آشپزی آشنا شدند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tend','tend','v','مواظب بودن، گرایش داشتن','/tend/ · care for, to be likely to happen','People tend to sleep less in summer.','[["People tend to sleep less in summer.","مردم در تابستان کمتر می‌خوابند."],["I tend to wake up early in the summer.","من معمولا در تابستان زود از خواب بیدار می‌شوم."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:terminal','terminal','adj','پایان، انتها','/ˈtɜr·mə·nəl/ · final','There was corrosion around the battery terminals.','[["There was corrosion around the battery terminals.","خوردگی در اطراف ترمینال‌های باتری وجود داشت."],["The terminals of the battery are loose.","ترمینال‌های باتری شل هستند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:therefore','therefore','adv','بنابر این، از این رو','/ˈðeərˌfɔr/ · consequently, in that purpose conj) hence','I write, therefore I am.','[["I write, therefore I am.","من می‌نویسم، پس هستم."],["I think therefore I discredit.","فکر می‌کنم، بنابراین بی‌اعتبارش می‌کنم."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:through','through','prep','از میان، از وسط','/θruː/ · by','You made a promise. Follow through.','[["You made a promise. Follow through.","قول دادی. به قولت عمل کن."],["Smart devices communicate through digital networks.","دستگاه‌های هوشمند از طریق شبکه‌های دیجیتال با هم ارتباط برقرار می‌کنند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:throughout','throughout','prep','در سرتاسر، در سراسر، در تمام','/θruːˈaʊt/ · during the period','We trudged throughout the city.','[["We trudged throughout the city.","با قدم‌های لرزان در سراسر شهر گشتیم."],["Sperm production continues throughout adulthood.","تولید اسپرم در تمام دوران بزرگسالی ادامه دارد."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:thus','thus','adv','بنابراین، در نتیجه، بدین ترتیب، از اینرو','/ðʌs/ · consequently, therefore','The river has a low drop and thus flows slowly.','[["The river has a low drop and thus flows slowly.","این رودخانه شیب کمی دارد و به همین دلیل جریان آرامی دارد."],["Thus far, no one has managed to solve this problem.","تا الان کسی موفق به حل این مشکل نشده است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tie','tie','n','همبستگی، پیوند، (الفت و غیره) رشته، رابطه','/taɪ/ · connection, relation','He was tied to a tree.','[["He was tied to a tree.","او را به درخت بسته بودند."],["Which tie do you like best?","کدام کراوات را بیشتر دوست دارید؟"]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:to-be-sure','to be sure','phr','مسلما، حتما، مطمئنا، بی شک، قطعا، یقینا','certainly','Michael had to be sure.','[["Michael had to be sure.","مایکل باید مطمئن می‌شد."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:to-some-extent','to some extent','phr','تاحدی','with limitations','What he says is true to some extent.','[["What he says is true to some extent.","حرفش تا یه حدی درسته."],["I can understand you to some extent.","تا حدودی میتونم درکت کنم."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:track','track','n','مسیر، راه، خط، دنبال کردن','/træk/ · 1)a narrow path or road with a rough uneven surface, 2) follow, observe','Is the full track available anywhere?','[["Is the full track available anywhere?","آهنگ کاملش جایی موجوده؟"],["My assistant keeps track of that.","دستیار من این موضوع را پیگیری می‌کند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:transfer','transfer','v','انتقال دادن','/ˈtræns.fɝː/ · move','I''d like to transfer $500 to my checking account.','[["I''d like to transfer $500 to my checking account.","من می‌خواهم 500 دلار به حساب جاری خود منتقل کنم."],["Some diseases easily transfer from one person to another.","برخی بیماری‌ها به‌آسانی از فردی به فرد دیگر منتقل می‌شوند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:trend','trend','n','تمایل، روند، گرایش','/trend/ · movement, tendency','The graph shows an upward trend.','[["The graph shows an upward trend.","نمودار روند صعودی را نشان می‌دهد."],["There is a growing trend toward online shopping.","روند رو به رشدی به سمت خرید آنلاین وجود دارد."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:turn','turn','v','تبدیل شدن، تغییر کردن','/tɜːrn/ · change to','Her face turned red with embarrassment.','[["Her face turned red with embarrassment.","صورتش از خجالت قرمز شد."],["He is waiting for his turn.","او منتظر نوبتش است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:typical','typical','adj','معمول','/ˈtɪpɪkəl/ · ordinary','She typically entered the house early.','[["She typically entered the house early.","او معمولاً زود وارد خانه می‌شد."],["Today is another typically hectic day.","امروز هم یکی دیگر از روزهای معمولاً شلوغ و پرمشغله است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ultimate','ultimate','adj','نهایی','/ˈʌltəmət/ · in the end','However, as the earth’s population increases, human activity will ultimately destroy the oceans unless immediate steps are taken.','[["However, as the earth’s population increases, human activity will ultimately destroy the oceans unless immediate steps are taken.","اما با افزایش جمعیت زمین، فعالیت انسان سرانجام اقیانوس‌ها را نابود خواهد کرد، مگر اینکه فوراً اقداماتی انجام شود."],["Our ultimate goal is to protect the forest.","هدف نهایی ما حفاظت از جنگل است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ultimately','ultimately','adv','در نهایت','/ˈʌltəmətli/ · finally, eventually','Ultimately, he has only himself to blame.','[["Ultimately, he has only himself to blame.","در نهایت فقط خودش مقصر است."],["Ultimately, the decision is yours.","در نهایت تصمیم با شماست."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:uniform','uniform','adj','یکسان، یکنواخت','/ˈjuːnəfɔːm/ · without variation','He was on duty and in uniform.','[["He was on duty and in uniform.","او در حال انجام وظیفه و یونیفرم بود."],["You should be wearing your uniform.","تو باید یونیفرمت رو بپوشی."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unique','unique','adj','منحصر به فرد','/juːˈniːk/ · distinctive, distinct, sole','Each person''s DNA is unique.','[["Each person''s DNA is unique.","DNA هر فرد منحصر به فرد است."],["Every person''s fingerprints are unique.","اثر انگشت هر فردی منحصر به فرد است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unique-to','unique to','phr','منحصرا وابسته به یک فرد یا مکان یا موجود در یک مکان','/juːˈniːk/ · only found in','Maltese has a number of idiomatic expressions that are unique to the language.','[["Maltese has a number of idiomatic expressions that are unique to the language.","زبان مالتی تعدادی اصطلاح دارد که منحصر به این زبان هستند."],["Montage is a language unique to cinematography.","مونتاژ زبانی منحصر به فرد در سینما است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vast','vast','adj','وسیع','/vɑːst/ · extended, extensive, immense, large number, huge','The Sahara is a vast desert.','[["The Sahara is a vast desert.","صحرا یک بیابان وسیع است."],["A vast majority of people agreed.","اکثریت قریب به اتفاق مردم موافق بودند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vehicle','vehicle','n','روش','/ˈviːɪkəl/ · means, method, way','A truck driver died last night when his vehicle overturned.','[["A truck driver died last night when his vehicle overturned.","یک راننده کامیون شب گذشته بر اثر واژگونی خودرو جان خود را از دست داد."],["Electric vehicles reduce urban air pollution.","خودروهای برقی آلودگی هوای شهری را کاهش می‌دهند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:via','via','prep','به وسیله ی','/ˈvaɪə/ · by means of, by the way of','They came to Europe via Turkey.','[["They came to Europe via Turkey.","آنها از طریق ترکیه به اروپا آمدند."],["I prefer to travel via bus.","من ترجیح می‌دهم با اتوبوس سفر کنم."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vital','vital','adj','حیاتی، وابسته بزندگی، واجب، اساسی','/ˈvaɪtl/ · critical, essential','Survival is a vital necessity.','[["Survival is a vital necessity.","بقا یک ضرورت حیاتی است."],["Having mutual regard is vital.","داشتن احترام متقابل حیاتی است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:volume','volume','n','تعداد میزان، مقدار','/ˈvɑːljəm/ · quantity','The volume is too loud. Can you turn the volume down?','[["The volume is too loud. Can you turn the volume down?","صدا خیلی بلند است. میتونی صدا رو کم کنی؟"],["He took those terms from a volume.","او آن اصطلاحات را از یک جلد کتاب برداشت."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:wanting','wanting','adj','ناکافی، فاقد','/ˈwɑːntɪŋ/ · inadequate','The plan was found wanting in several important ways.','[["The plan was found wanting in several important ways.","این طرح از چندین جهت مهم ناقص تشخیص داده شد."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:whatever','whatever','conj','هرچه، هر انچه، هر قدر، هر چه','/wʌtˈevər/ · in any case','Whatever you do, do it wisely.','[["Whatever you do, do it wisely.","هر کاری که انجام می‌دهید، عاقلانه انجام دهید."],["Please take whatever cakes you want.","لطفا هر کیکی که دوست دارید بردارید."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:whereas','whereas','conj','در حالیکه، درحقیقت، با این حال','/werˈæz/ · however','He is kind, whereas she is cruel.','[["He is kind, whereas she is cruel.","او مهربان است، در حالی که او ظالم است."],["Whereas others pick ten berries, she picks ten litres.","در حالی که دیگران ده توت می‌چینند، او ده لیتر می‌چیند."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:while','while','conj','در حالی که، با اینکه','/evening/ · although','Enjoy it all while you can.','[["Enjoy it all while you can.","تا می‌توانید از همه چیز لذت ببرید."],["She took my hand while walking.","موقع راه رفتن دستمو گرفت."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:whole','whole','adj','تمام','/həʊl/ · entire','I have the whole week off.','[["I have the whole week off.","من کل هفته رو تعطیلم."],["Open data benefits the whole society.","داده‌های باز به نفع کل جامعه است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:with-respect-to','with respect to','phr','با توجه به، از لحاظ، در مورد','in terms of','Revelation is necessarily out of the question with respect to those books.','[["Revelation is necessarily out of the question with respect to those books.","وحی لزوماً در مورد آن کتاب‌ها منتفی است."],["The derivatives of distance with respect to time are velocity, acceleration, and jerk.","مشتقات مسافت نسبت به زمان عبارتند از سرعت، شتاب و جرک."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:within','within','prep','در داخل','/wiT͟Hˈin/ · inside','It is not within my control.','[["It is not within my control.","در حیطه کنترل من نیست."],["Is that within your skill set?","آیا این در محدوده مهارت‌های شماست؟"]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:witness','witness','n','شاهد؛ شهادت دادن، دیدن','/ˈwɪtnəs/ · observe','The police are looking for witnesses.','[["The police are looking for witnesses.","پلیس به دنبال شاهدان است."],["The witness described the thief to the police.","شاهد ماجرا دزد را به پلیس توضیح داد."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:yet','yet','adv','هنوز','/jet/ · however','He is not a man yet.','[["He is not a man yet.","او هنوز مرد نشده است."],["His end has not yet come.","پایان او هنوز فرا نرسیده است."]]','t1212',7,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:a-matter-of-speculation','a matter of speculation','phr','فرض، گمان','supposition','The exact age of the cave paintings is still a matter of speculation.','[["The exact age of the cave paintings is still a matter of speculation.","قدمت دقیق نقاشی‌های غار هنوز محل گمانه‌زنی است."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:abandon','abandon','v','رها کردن (کسی یا مکانی) بدون قصد بازگشت، ترک کردن','/əˈbændən/ · give up, desert; leave without planning to come back; quit','They abandoned the old car in the desert.','[["They abandoned the old car in the desert.","ماشین قدیمی را در بیابان رها کردند."],["They had to abandon their car in the snow.","آنها مجبور شدند ماشین خود را در برف رها کنند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:absorb','absorb','v','جذب کردن آب یا مواد دیگر یا اطلاعات','/əbˈzɔːb/ · appeal, learn, take into; take in a liquid, gas or other substance from the surface or space around','Plants absorb carbon dioxide.','[["Plants absorb carbon dioxide.","گیاهان دی اکسید کربن را جذب می‌کنند."],["Children absorb new languages quickly.","کودکان به سرعت زبان‌های جدید را جذب می‌کنند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:abstract','abstract','adj','انتزاعی','/ˈæbstrækt/ · Not concrete and realistic;not obviously related to every- day experience','Truth and beauty are abstract concepts.','[["Truth and beauty are abstract concepts.","حقیقت و زیبایی مفاهیمی انتزاعی هستند."],["He was an abstract artist.","او یک هنرمند انتزاعی بود."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:absurd','absurd','adj','مضحک، مسخره','/əb-ɜːrd/ · ridiculous, completely stupid or unreasonable','The men laughed riotously at his absurd impressions.','[["The men laughed riotously at his absurd impressions.","مردها از تصورات پوچ او با صدای بلند خندیدند."],["The most absurd things happen in this country.","عجیب‌ترین اتفاقات در این کشور رخ می‌دهد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:abundance','abundance','n','فراوانی، وفور','/əˈbʌndəns/ · great number, large amount, host of','We have food in abundance.','[["We have food in abundance.","ما به وفور غذا داریم."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:accessible','accessible','adj','قابل دسترس','/əkˈsesəbəl/ · easy to approach; obtainable','Education should be accessible to all.','[["Education should be accessible to all.","آموزش باید در دسترس همه باشد."],["The museum is accessible to wheelchair users.","این موزه برای افراد ویلچر قابل دسترسی است."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:accidental','accidental','adj','غیر منتظره','/ˌæksəˈdentl/ · unexpected','The knife accidentally gashes her hand.','[["The knife accidentally gashes her hand.","چاقو به طور تصادفی دستش را زخمی می‌کند."],["He accidentally drank a cleaning product.","او به طور تصادفی یک محصول تمیزکننده را نوشید."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:accommodate','accommodate','v','جا دادن','/əˈkleɪmd/ · provide for, achieve- if a room, building etc can ~ a particular a number of people or thing, it has enough space for them','The big opening along Africa’s western coast would easily accommodate the “hump” in South America’s eastern coastline.','[["The big opening along Africa’s western coast would easily accommodate the “hump” in South America’s eastern coastline.","فرورفتگی بزرگ در امتداد ساحل غربی آفریقا به‌راحتی «برآمدگی» ساحل شرقی آمریکای جنوبی را در خود جای می‌دهد."],["Tom accommodated them for free.","تام آنها را به صورت رایگان اسکان داد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:accomplished','accomplished','adj','بسیار ماهر','/əˈkʌmplɪʃt/ · skilled-very skilful because you had a lot of experience of doing something','What have you accomplished this morning?','[["What have you accomplished this morning?","امروز صبح چه کارهایی انجام داده‌اید؟"],["Lorenzo accomplished his goal for sure.","لورنزو مطمئناً به هدفش رسید."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:acknowledge','acknowledge','v','تشخیص دادن، اذعان کردن، اعتراف کردن','/əkˈnɒlɪdʒ/ · 1) recognize(if people~ something, they recognize how good or important it is)-2) to admit or accept that something is true','He acknowledged his mistake.','[["He acknowledged his mistake.","او به اشتباه خود اعتراف کرد."],["He acknowledged that he had made a mistake.","او اعتراف کرد که اشتباه کرده است."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:adjacent','adjacent','adj','کنار','/əˈdʒeɪs(ə)nt/ · nearby, neighboring;a room, building, piece of land etc that is ~ to something is next to it','The lab is adjacent to the library.','[["The lab is adjacent to the library.","آزمایشگاه در مجاورت کتابخانه قرار دارد."],["They live in adjacent apartments.","آنها در آپارتمان‌های مجاور زندگی می‌کنند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:adjust','adjust','v','تنظیم کردن، وقف دادن','/əˈdʒʌst/ · modify, to change something slightly, especially to make it more correct, effective, or suitable','It took time to adjust myself to motherhood.','[["It took time to adjust myself to motherhood.","زمان برد تا خودم را با مادری وفق دهم."],["He adjusted the brim of his hat.","لبه کلاهش را مرتب کرد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:admire','admire','v','تحسین کردن','/ədˈmaɪəˈmaɪr/ · to respect somebody for what they are or for what they have done','Others admire my resilience and strength.','[["Others admire my resilience and strength.","دیگران مقاومت و قدرت مرا تحسین می‌کنند."],["The students admire her leadership skills.","دانش‌آموزان مهارت‌های رهبری او را تحسین می‌کنند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:adopt','adopt','v','تصویب کردن','/ˈdɑːpt/ · (low, rule) to formally approve a proposal, amendment etc, especially by voting; enact','You forgot to adopt the sentence.','[["You forgot to adopt the sentence.","یادت رفت جمله رو اصلاح کنی."],["Did you know you were adopted?","می‌دانستی که به فرزندی پذیرفته شده‌ای؟"]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:aggregate','aggregate','n','جمع، مجموع','(formal)combined, overall','They purchased an aggregate of 3000 shares in the company.','[["They purchased an aggregate of 3000 shares in the company.","آنها مجموعاً 3000 سهام شرکت را خریداری کردند."],["As the run-off increases, the aggregation of algae and bacteria increases, further eroding the marine environment.","با افزایش رواناب، تجمع جلبک‌ها و باکتری‌ها بیشتر می‌شود و محیط دریایی را بیش از پیش فرسوده می‌کند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:alarm','alarm','n','آزیر، هشدار','/əˈlɑːrm/ · sound, warning','The alarm goes off at eight.','[["The alarm goes off at eight.","ساعت هشت زنگ ساعت به صدا در می‌آید."],["Did you turn on the alarm?","آیا زنگ هشدار را روشن کردی؟"]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:albeit','albeit','conj','اگرچه','/ɒːlˈbiːɪt/ · even though, although','It was a success, albeit a small one.','[["It was a success, albeit a small one.","موفقیتی بود، هرچند کوچک."],["The plan worked, albeit slowly.","این طرح کار کرد، هرچند به کندی."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ally-with','ally with','phr','پیوستن به، متحد شدن با','/preposition]/ · link to, to help and support other people or countries, especially in a war or disagreement','Algeria will not ally with Saudi Arabia against Yemen.','[["Algeria will not ally with Saudi Arabia against Yemen.","الجزایر با عربستان سعودی علیه یمن متحد نخواهد شد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:alter','alter','v','تغییر دادن، کردن','/ˈɒːltər/ · make different; change; vary','Climate change alters habitats.','[["Climate change alters habitats.","تغییر اقلیم زیستگاه‌ها را تغییر می‌دهد."],["Climate change could alter the ecosystem.","تغییرات آب و هوایی می‌تواند اکوسیستم را تغییر دهد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ambitious','ambitious','adj','جاه طلب، بلندهمت','/æmˈbɪʃəs/ · keen/energetic','She is ambitious and hardworking.','[["She is ambitious and hardworking.","او جاه طلب و سخت کوش است."],["She is ambitious and wants to start her own company.","او جاه طلب است و می‌خواهد شرکت خود را راه اندازی کند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:anchor','anchor','v','لنگر انداختن، محکم بستن','/ˈæŋkə/ · hold (sth. especially a ship) in place- syn, moor','Gabriel heard an anchor dropping.','[["Gabriel heard an anchor dropping.","جبرئیل صدای افتادن لنگر را شنید."],["The skipper is weighing anchor.","ناخدا در حال وزن کردن لنگر است."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:annually','annually','adv','سالانه','/ˈænjʊəli/ · yearly-once a year- ever year','Annually we work on our land.','[["Annually we work on our land.","ما سالانه روی زمین‌هایمان کار می‌کنیم."],["We talk about him annually.","ما هر سال درباره او صحبت می‌کنیم."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:anonymous','anonymous','adj','ناشناس','/əˈnɑːnɪməs/ · nameless/incognito- unknown by name','They are the anonymous ones — not us.','[["They are the anonymous ones — not us.","آنها گمنام هستند - نه ما."],["His identity remains anonymous to the recipients.","هویت او برای گیرندگان ناشناس باقی می‌ماند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:appealing','appealing','adj','درخواست','/əˈpēliNG/ · attractive, interesting','This topic is appealing to many.','[["This topic is appealing to many.","این موضوع برای خیلی‌ها جذاب است."],["I think that''s really appealing.","به نظر من که واقعاً جذابه."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:architect','architect','n','معمار','/ˈɑːr.kə.tekt/ · a person who designs buildings/structure','The architect designed a modern library.','[["The architect designed a modern library.","معمار یک کتابخانه مدرن طراحی کرد."],["Christopher Wren was the chief architect of the rebuilding.","کریستوفر رن معمار اصلی بازسازی بود."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:archive','archive','n','بایگانی','/ˈɑːr.kaɪv/ · record, stock, store- a place where a large number of history records are stored','I will not archive her photographs.','[["I will not archive her photographs.","عکس‌هایش را آرشیو نمی‌کنم."],["She was in the archive.","توی آرشیو بود."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:arise','arise','v','بوجود امدن، ظاهر شدن','/əˈrʌɪz/ · come about, emerge','Differences of opinion arise often.','[["Differences of opinion arise often.","اختلاف نظرها اغلب پیش می‌آید."],["Heroes arise in troubled times.","قهرمانان در زمان‌های دشوار ظهور می‌کنند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:arrangement','arrangement','n','توافق','/əˈreɪndʒ.mənt/ · configuration-the action, process, or result of arranging or being arrange','We need to start making arrangements.','[["We need to start making arrangements.","باید شروع به انجام هماهنگی‌ها کنیم."],["We''ve come to an arrangement.","ما به یه توافقی رسیدیم."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:array','array','n','ارائه','/əˈreɪ/ · range-an impressive display or range of a particular type of thing.','The trigonometric functions satisfy a wide array of notable algebraic identities.','[["The trigonometric functions satisfy a wide array of notable algebraic identities.","توابع مثلثاتی طیف گسترده‌ای از اتحادهای جبری قابل توجه را برآورده می‌کنند."],["The batteries store energy collected by the station''s solar panel arrays.","باتری‌ها انرژی جمع‌آوری‌شده توسط آرایه‌های پنل خورشیدی ایستگاه را ذخیره می‌کنند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:asset','asset','n','دارایی','/ˈasɛt/ · advantage-a useful or valuable thing or person','He lost all his assets.','[["He lost all his assets.","تمام دارایی‌هایش را از دست داد."],["Perseverance became my greatest asset.","پشتکار بزرگترین دارایی من شد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:assumption','assumption','n','فرض','/əˈsʌmpʃən/ · premise-a thing that is accepted as true or as certain to happen, without proof','Your assumptions may rob someone of their dignity.','[["Your assumptions may rob someone of their dignity.","فرضیات شما ممکن است عزت نفس کسی را از بین ببرد."],["Your assumption that I love food is correct.","فرض شما مبنی بر اینکه من عاشق غذا هستم درست است."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:attachment','attachment','n','دلبستگی، وابستگی، تعلق خاطر','/əˈtætʃmənt/ · preference for, a feeling that you like or love someone or something and that you would be unhappy without them','The resume is in the attachment.','[["The resume is in the attachment.","رزومه در فایل پیوست موجود است."],["Ziri felt no attachment to reality.","زیری هیچ دلبستگی به واقعیت احساس نمی‌کرد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:barrier','barrier','n','مانع، سد، حصار','/ˈbæriər/ · impediment, obstacle','The old barrier has completely rusted.','[["The old barrier has completely rusted.","دیوار قدیمی کاملاً زنگ زده است."],["Fear creates barriers to effective communication.","ترس مانع ارتباط موثر می‌شود."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:be-inclined-to','be inclined to','phr','تمایل داشتن','tend','People are inclined to believe what they read in the newspaper.','[["People are inclined to believe what they read in the newspaper.","مردم معمولاً آنچه را که در روزنامه می‌خوانند باور می‌کنند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:beneficial','beneficial','adj','سودمند','/ˌbenɪˈfɪʃəl/ · advantageous','Regular exercise is beneficial to health.','[["Regular exercise is beneficial to health.","ورزش منظم برای سلامتی مفید است."],["The agreement will be beneficial for both countries.","این توافق برای هر دو کشور مفید خواهد بود."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:boundary','boundary','n','مرز، کرانه','/ˈbaʊndəri/ · periphery','I am going to impose boundaries on her.','[["I am going to impose boundaries on her.","من قصد دارم برایش حد و مرز تعیین کنم."],["I need someone who respects my boundaries.","من به کسی نیاز دارم که به مرزهای من احترام بگذارد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:breakthrough','breakthrough','n','پیشرفت غیر منتظره، انقلاب','/ˈbreɪkθruː/ · revolution','That was a huge and real breakthrough.','[["That was a huge and real breakthrough.","این یک پیشرفت بزرگ و واقعی بود."],["Benedito''s findings could lead to important breakthroughs.","یافته‌های بندیتو می‌تواند به پیشرفت‌های مهمی منجر شود."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:breed','breed','v','تولید کردن، دوباره ساختن','/briːd/ · reproducebreeding behavior, sitting on the eggs','Evil only breeds more suffering, never peace.','[["Evil only breeds more suffering, never peace.","شر فقط رنج بیشتری به بار می‌آورد، هرگز صلح را به ارمغان نمی‌آورد."],["Racism and dehumanization breed division and hatred.","نژادپرستی و غیرانسانی‌سازی، تفرقه و نفرت می‌آفریند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:broadly','broadly','adv','به طور کلی، گسترده','/ˈbrɒːdli/ · generally, extensively','Broadly speaking, the project was successful.','[["Broadly speaking, the project was successful.","به طور کلی، این پروژه موفقیت‌آمیز بود."],["Well, broadly speaking that''s right.","خب، به طور کلی، درست است."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:bulk','bulk','n','پرحجم، بصورت عمده، قسمت عمده','/bʌlk/ · largest area, major part, great quantity, large part, large portion, majority','We spent the bulk of the summer at the beach.','[["We spent the bulk of the summer at the beach.","ما بیشتر تابستان را در ساحل گذراندیم."],["This store sells everything in bulk.","این فروشگاه همه چیز را به صورت عمده می‌فروشد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cardinal','cardinal','adj','اصلی، اساسی','/ˈkɑːrdənəl/ · fundamental, essential, vital, basic','Do you want to become a cardinal?','[["Do you want to become a cardinal?","می‌خوای کاردینال بشی؟"],["The cardinals have elected a new pope.","کاردینال‌ها پاپ جدید را انتخاب کردند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cargo','cargo','n','بار، محموله، کالای حمل‌شده باکشتی','/ˈkɑːrɡoʊ/ · shipment','He hid in a cargo bin.','[["He hid in a cargo bin.","او در یک سطل زباله مخفی شد."],["They had to jettison the cargo.","آنها مجبور شدند محموله را به دریا بیندازند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:celebrated','celebrated','adj','مشهور، معروف','/ˈselɪbreɪtɪd/ · famous','She celebrated her birthday every year.','[["She celebrated her birthday every year.","او هر سال تولدش را جشن می‌گرفت."],["With the job finished, they celebrated.","با پایان کار، آنها جشن گرفتند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:chronic','chronic','adj','مزمن، دیرینه، همیشگی','/ˈkrɑ:nɪk/ · confirmed, inveterate, habitual, persistent','He suffers from a chronic disease destined to get progressively worse.','[["He suffers from a chronic disease destined to get progressively worse.","او از یک بیماری مزمن رنج می‌برد که به تدریج بدتر می‌شود."],["COPD, chronic obstructive pulmonary disease, blocks airflow through the lungs.","بیماری انسدادی مزمن ریوی (COPD)، جریان هوا را از طریق ریه‌ها مسدود می‌کند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:clue','clue','n','اشاره، سرنخ','/kluː/ · hint','The outlaw left a trail of clues.','[["The outlaw left a trail of clues.","یاغی ردی از سرنخ‌ها به جا گذاشت."],["The police are looking for clues.","پلیس در حال جستجوی سرنخ‌هایی است."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cluster','cluster','n','دسته، گروه','/ˈklʌstə/ · group, bunch','The grapes grow in clusters.','[["The grapes grow in clusters.","انگورها به صورت خوشه ای رشد می‌کنند."],["Leonid heard something rustling through the leaves and bamboo clusters.","لئونید صدای خش خش چیزی را از میان برگ‌ها و خوشه‌های بامبو شنید."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:coincidence','coincidence','n','اتفاقی، حوادث با احتمال بالا','/kəʊˈɪnsɪdəns/ · likely events','What a coincidence to meet you here!','[["What a coincidence to meet you here!","چه تصادفی است که شما را در اینجا ملاقات کردم!"],["It was no coincidence that they arrived together.","تصادفی نبود که با هم رسیدند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:collaboration','collaboration','n','همکاری، اثر مشترک','/kəˌlæbəˈreɪʃən/ · joint effect','Collaboration with technicians helped finalize the invention.','[["Collaboration with technicians helped finalize the invention.","همکاری با تکنسین‌ها به نهایی شدن اختراع کمک کرد."],["Collaboration increases productivity in complex projects.","همکاری باعث افزایش بهره وری در پروژه‌های پیچیده می‌شود."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:compact','compact','adj','مختصر، فشرده، جمع و جور','/kəmˈpækt/ · concise compressed','The heathers formed a compact bush.','[["The heathers formed a compact bush.","خلنگزارها بوته‌های فشرده‌ای را تشکیل می‌دادند."],["The compact edition is lower priced.","نسخه فشرده قیمت پایین‌تری دارد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:comparable','comparable','adj','قابل مقایسه، معادل','/ˈkɒmpərəbəl/ · equivalent, similar to something so that we can make a comparison','The two cities are comparable in size and population.','[["The two cities are comparable in size and population.","این دو شهر از نظر وسعت و جمعیت قابل مقایسه هستند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:compatible','compatible','adj','سازگار، تطابق','/kəmˈpætəbəl/ · consistent, suitable','Are healthy oceans compatible with an industrialized world?','[["Are healthy oceans compatible with an industrialized world?","آیا اقیانوس‌های سالم با جهانِ صنعتی‌شده سازگارند؟"],["Yanni and Skura are compatible.","یانی و اسکورا با هم سازگار هستند."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:compelling','compelling','adj','قانع‌کننده، جذاب','/kəmˈpelɪŋ/ · 1) convincing-forcing 2) interesting','There is compelling evidence for this view.','[["There is compelling evidence for this view.","شواهد قانع کننده ای برای این دیدگاه وجود دارد."],["She made a compelling argument for change.","او یک استدلال قانع کننده برای تغییر ارائه کرد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:configuration','configuration','n','پیکربندی، آرایش، فرم','/kənˌfɪɡəˈreɪʃən/ · arrangement, form','We were running out of disk space due to a configuration issue.','[["We were running out of disk space due to a configuration issue.","به دلیل مشکل پیکربندی، فضای دیسک ما رو به اتمام بود."],["The configuration file for your database server is located in this directory.","فایل پیکربندی سرور پایگاه داده شما در این دایرکتوری قرار دارد."]]','t1212',8,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:confront','confront','v','روبرو شدن، مواجه شدن','/kənˈfrʌnt/ · face','Humanity must confront its greatest challenges.','[["Humanity must confront its greatest challenges.","بشریت باید با بزرگترین چالش‌های خود روبرو شود."],["You must confront your inner demon.","باید با شیطان درونت روبرو شوی."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consecutive','consecutive','adj','متوالی، پی در پی','/kənˈsekjətɪv/ · successive','It rained for five consecutive days.','[["It rained for five consecutive days.","پنج روز متوالی باران بارید."],["The team won its third consecutive title.","این تیم سومین عنوان متوالی خود را کسب کرد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consensus','consensus','n','توافق، رضایت','/kənˈsensəs/ · agreement','The team reached a consensus before implementing changes.','[["The team reached a consensus before implementing changes.","تیم قبل از اعمال تغییرات به اجماع رسید."],["Experts reached a consensus on results.","کارشناسان در مورد نتایج به اجماع رسیدند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consequence','consequence','n','نتیجه','/ˈkɒnsəkwəns/ · 1) importance e.g. of little consequence 2)result','Every decision has consequences.','[["Every decision has consequences.","هر تصمیمی عواقبی دارد."],["If you break the rules, you must accept the consequences.","اگر قوانین را زیر پا بگذارید، باید عواقب آن را بپذیرید."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consequently','consequently','adv','در نتیجه، بنابراین','/ˈkɒnsəkwəntli/ · therefore, thus, as a result','He missed the bus and consequently arrived late for work.','[["He missed the bus and consequently arrived late for work.","او اتوبوس را از دست داد و در نتیجه دیر به محل کار رسید."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:considerable','considerable','adj','قابل توجه','/kənˈsɪdərəbəl/ · large amount of, substantial/significant','The project needs considerable investment.','[["The project needs considerable investment.","این پروژه نیاز به سرمایه گذاری قابل توجهی دارد."],["The project cost a considerable amount of money.","این پروژه هزینه قابل توجهی داشته است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consist-of','consist of','phr','تشکیل شدن از','/kənˈsɪdərəbəl/ · compose of, constitute','What does cancel culture consist of?','[["What does cancel culture consist of?","فرهنگ لغو شامل چه چیزهایی می‌شود؟"],["A coalition consists of different parties.","ائتلافی متشکل از احزاب مختلف."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consistently','consistently','adv','همواره، منظم','/kənˈsɪstənt/ · regularly, uniformly','You consistently struggle to meet deadlines.','[["You consistently struggle to meet deadlines.","شما دائماً برای رسیدن به ضرب‌الاجل‌ها تلاش می‌کنید."],["You are consistently late to work.","شما مرتباً دیر به محل کار می‌رسید."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:constitute','constitute','v','دربرداشتن، تشکیل دادن','/ˈkɒnstɪtjuːt/ · comprise/consist of, make up','A given name plus the inherited title usually constitute their public names, such as King Faisal or Queen Elizabeth.','[["A given name plus the inherited title usually constitute their public names, such as King Faisal or Queen Elizabeth.","یک نام کوچک به‌علاوهٔ عنوان موروثی معمولاً نام رسمی آن‌ها را تشکیل می‌دهد، مانند ملک فیصل یا ملکه الیزابت."],["Chordates constitute the largest group of deuterostomes.","مازه‌داران بزرگترین گروه دوتروستوم‌ها را تشکیل می‌دهند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consume','consume','v','خوردن، بلعیدن، مصرف کردن، آشامیدن','/kənˈsuːm/ · eat up','Cows consume a lot of grass.','[["Cows consume a lot of grass.","گاوها علف زیادی مصرف می‌کنند."],["Many consumers are not comfortable making purchases on the Internet.","بسیاری از مصرف کنندگان برای خرید از طریق اینترنت راحت نیستند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:consumed','consumed','adj','کاملاً مصرف‌شده','/kənˈsuːmd/ · used completely, used up','I am consumed by absurd jealousies.','[["I am consumed by absurd jealousies.","حسادت‌های پوچ و بی‌اساس وجودم را فرا گرفته است."],["She is greatly consumed by remorse.","او به شدت غرق در پشیمانی است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:continuous','continuous','adj','پیوسته، بی وقفه، بی مکث، همواره، مستمر، مداوم، متداوم','/kənˈtɪn.ju.əs/ · uninterrupted, ongoing','The healing was gradual but continuous.','[["The healing was gradual but continuous.","بهبودی تدریجی اما مداوم بود."],["Do you believe in continuous growth?","آیا به رشد مداوم اعتقاد دارید؟"]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:controversy','controversy','n','بحث، بگو مگو، مباحثه، جرو بحث، جدل، مناقشه، قیل و قال','/ˈkɑːn.trə.vɝː.si/ · conflict, disagreement','The judges'' decision provoked controversy.','[["The judges'' decision provoked controversy.","تصمیم داوران جنجال برانگیخت."],["There is controversy over the use of animals in research.","در مورد استفاده از حیوانات در تحقیقات اختلاف نظر وجود دارد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:conventional','conventional','adj','عرفی، سنتی، قراردادی، متداول، معمول، متعارف، عادی','/kənˈven.ʃən.əl/ · customary, traditional','The US is regularly defeated in conventional warfare.','[["The US is regularly defeated in conventional warfare.","آمریکا مرتباً در جنگ‌های متعارف شکست می‌خورد."],["Shale gas is more expensive than conventional gas.","گاز شیل گران‌تر از گاز معمولی است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:convert','convert','v','تبدیل کردن یا شدن','/kənˈvɝːt/ · transform, change to','The sofa converts to a bed.','[["The sofa converts to a bed.","مبل به تخت تبدیل می‌شود."],["To turn things around, you have to convert your product’s old-fashioned image into something new, and make sure consumers get the message.","برای تغییر اوضاع، باید تصویر قدیمی محصولتان را به چیزی تازه تبدیل کنید و مطمئن شوید مصرف‌کنندگان پیام را دریافت می‌کنند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:convey','convey','v','رساندن، معنی دادن، بیان کردن','/kənˈveɪ/ · communicate','Language conveys both facts and emotions.','[["Language conveys both facts and emotions.","زبان هم حقایق و هم احساسات را منتقل می‌کند."],["His smile conveyed warmth and friendliness.","لبخندش گرمی و صمیمیت را منتقل می‌کرد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:conviction','conviction','n','اعتقاد راسخ، عقیده ی محکم','/kənˈvɪk.ʃən/ · strong beliefopinionperspective','Ziri lacked conviction in his words.','[["Ziri lacked conviction in his words.","زیری در سخنانش قاطعیت نداشت."],["They plan to appeal their convictions.","آنها قصد دارند به احکام خود اعتراض کنند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:convince','convince','v','متقاعد کردن، مجاب کردن، قانع کردن','/kənˈvɪns/ · persuade','She convinced me to join the club.','[["She convinced me to join the club.","او مرا متقاعد کرد که به باشگاه بپیوندم."],["I''m not convinced that this is a good idea.","من متقاعد نشده ام که این ایده خوبی است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cope-with','cope with','phr','از پس (چیزی یا کسی) برآمدن، از عهده برآمدن، حریف شدن، چیره شدن، جوابگو بودن','/koʊp/ · deal with, handle','How will he cope with it?','[["How will he cope with it?","او چگونه با آن کنار خواهد آمد؟"],["Ziri can cope with his fears.","زیری می‌تواند با ترس‌هایش کنار بیاید."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:correspondence','correspondence','n','همخوانی، مطابقت، تطابق، مشابهت','/ˌkɔːr.əˈspɑːn.dəns/ · harmony','He left the correspondence on the table.','[["He left the correspondence on the table.","او نامه‌ها را روی میز گذاشت."],["The correspondence is kept in several files.","مکاتبات در چندین پرونده نگهداری می‌شود."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:costly','costly','adj','گران، پر هزینه، پر خرج','/ˈkɑːst.li/ · expensive','Repairing the old bridge proved to be very costly.','[["Repairing the old bridge proved to be very costly.","تعمیر پل قدیمی بسیار پرهزینه بود."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:counsel','counsel','v','نصیحت کردن، توصیه کردن','/ˈkaʊn.səl/ · advise','Give neither counsel nor salt until you are asked for.','[["Give neither counsel nor salt until you are asked for.","تا وقتی از شما خواسته نشده، نه نصیحت کنید و نه نمک بپاشید."],["She made the decision by herself, without seeking my counsel.","او خودش به تنهایی تصمیم گرفت، بدون اینکه از من نظرخواهی کند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:countless','countless','adj','بی شمار، شمارش‌ناپذیر، بسیار زیاد','/ˈkaʊnt.ləs/ · innumerable','The universe contains countless stars.','[["The universe contains countless stars.","کیهان شامل ستارگان بی‌شماری است."],["There are countless civilian casualties.","تلفات غیرنظامیان بی‌شمار است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:coupled-with','coupled with','phr','همراه با، توأم با','/ˈkʌp.əl wɪð/ · together with','Acne coupled with eczema is a nasty combination.','[["Acne coupled with eczema is a nasty combination.","آکنه همراه با اگزما ترکیبی ناخوشایند است."],["Tom''s face clearly showed bewilderment coupled with irritation.","چهره تام به وضوح گیجی همراه با ناراحتی را نشان می‌داد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:crucial','crucial','adj','بسیار مهم، حیاتی','/ˈkru·ʃəl/ · important, vital, essential, critical','Sleep is crucial for good health.','[["Sleep is crucial for good health.","خواب برای سلامتی بسیار مهم است."],["This is a crucial moment in the game.","این یک لحظه حیاتی در بازی است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:crude','crude','adj','زمخت، ناشیانه، خالی از ظرافت، خشن','/kruːd/ · unsophisticated','The ogre brandished a crude cudgel.','[["The ogre brandished a crude cudgel.","غول چماق خامی را تکان داد."],["The method was crude but effective.","روش خام اما مؤثری بود."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:crushed','crushed','v','له کردن یا شدن، خرد کردن یا شدن، آرد کردن','/krʌʃd/ · ground, put down','They enjoyed pepper and crushed tomato.','[["They enjoyed pepper and crushed tomato.","آنها از فلفل و گوجه فرنگی له شده لذت بردند."],["Vladimir crushed the cockroach to death.","ولادیمیر سوسک را له کرد و کشت."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dam','dam','n','مانع، جلوبست، بازدار، راه بند، جلوگیر','/dæm/ · block','The dam provides electricity for the region.','[["The dam provides electricity for the region.","این سد برق منطقه را تامین می‌کند."],["Servile people are dams of freedom.","مردمانِ خدمتگزار، سدهای آزادی هستند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:delicate','delicate','adj','ظریف، حساس','/ˈdɛlɪkət/ · dainty, graceful','I need to approach the topic delicately.','[["I need to approach the topic delicately.","باید با ظرافت به موضوع نزدیک شوم."],["Dogs have a delicate sense of smell.","سگ‌ها حس بویایی ظریفی دارند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:delight','delight','n','لذت، شادی؛ خوشحال کردن','/dɪˈlʌɪt/ · 1)please 2)pleasure','Red sky at night — sailors'' delight.','[["Red sky at night — sailors'' delight.","آسمان سرخ در شب - لذت ملوانان."],["Everyone was delighted with the lady.","همه از خانم خوشحال شدند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dense','dense','adj','متراکم','/dɛns/ · 1)crowded 2)thick','Credit cards are surprisingly dense.','[["Credit cards are surprisingly dense.","کارت‌های اعتباری به طرز شگفت‌آوری متراکم هستند."],["The trees were so dense.","درخت‌ها خیلی انبوه بودند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:depend','depend','v','وابسته، بستگی داشتن','/dɪˈpɛnd/ · rely on, belong','What does you coming depend on?','[["What does you coming depend on?","آمدنت به چه چیزی بستگی دارد؟"],["It all depends on the region.","همه چیز به منطقه بستگی دارد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:deposit','deposit','v','سپرده، انباشتن','/dɪˈpɒzɪt/ · accumulate, lay down, put/set down','Large gold deposits were found.','[["Large gold deposits were found.","ذخایر بزرگ طلا پیدا شد."],["The river leaves deposits of mud on its banks.","رودخانه رسوبات گلی را در سواحل خود به جا می‌گذارد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:detected','detected','adj','شناسایی‌شده','/dɪˈtektɪd/ · identified, specified','The radar detected a mysterious signal.','[["The radar detected a mysterious signal.","رادار یک سیگنال مرموز را شناسایی کرد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:devoted','devoted','adj','وفادار، فداکار','/dɪˈvəʊtɪd/ · dedicated','Lucy is devoted to her cats.','[["Lucy is devoted to her cats.","لوسی به گربه هایش اختصاص دارد."],["This lesson was devoted to adjectives.","این درس به صفت‌ها اختصاص داشت."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:devoted-to','devoted to','adj','وقف‌شده، اختصاصی','/dɪˈvəʊtɪd/ · concentrated on, dedicated to','This lesson was devoted to adjectives.','[["This lesson was devoted to adjectives.","این درس به صفت‌ها اختصاص داشت."],["She is devoted to her parents.","او به والدینش وفادار است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:differential','differential','adj','متفاوت، ناهمسان','/ˌdɪfəˈrenʃəl/ · uneven, dissimilar, different','Can you help me with differential equations?','[["Can you help me with differential equations?","میشه در مورد معادلات دیفرانسیل کمکم کنید؟"],["Tom taught himself differential calculus.","تام حساب دیفرانسیل و انتگرال را خودش یاد گرفت."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dimension','dimension','n','بعد، ابعاد، مقدار، اندازه','/daɪˈmenʃən/ · aspect, size','His coaching has added another dimension to my game.','[["His coaching has added another dimension to my game.","مربیگری او بعد دیگری به بازی من اضافه کرده است."],["They slipped into a different dimension.","آنها به بُعد دیگری لغزیدند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:discharge','discharge','v','خالی کردن، مرخص کردن، بیرون ریختن','/dɪsˈtʃɑːdʒ/ · release, unload','My eyes are filled with ocular discharge.','[["My eyes are filled with ocular discharge.","چشمانم پر از ترشحات چشمی شده است."],["Rodrigo is healthy enough to be discharged.","رودریگو به اندازه کافی سالم است که مرخص شود."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:discipline','discipline','v','تنبیه کردن','/ˈdɪsɪplɪn/ · punish, penalize','Virtually militaristic discipline reigned in the summer camp.','[["Virtually militaristic discipline reigned in the summer camp.","عملاً نظم و انضباط نظامی در اردوی تابستانی حاکم بود."],["Geishas have a very strict and disciplined lifestyle.","گیشاها سبک زندگی بسیار سخت‌گیرانه و منضبطی دارند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dismiss','dismiss','v','رد کردن','/dɪsˈmɪs/ · reject, ignore','He dismisses others without a second thought.','[["He dismisses others without a second thought.","او بدون هیچ تردیدی دیگران را نادیده می‌گیرد."],["He dismisses the importance of mental health.","او اهمیت سلامت روان را نادیده می‌گیرد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dispute','dispute','n','بحث، گفتمان، مشاجره، جدل','/dɪˈspjuːt/ · argument, contention','Scientists dispute how intelligence should be measured.','[["Scientists dispute how intelligence should be measured.","دانشمندان در مورد چگونگی اندازه گیری هوش اختلاف نظر دارند."],["Disputes can foster deeper knowledge.","اختلافات می‌توانند دانش عمیق‌تری را پرورش دهند."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:distant','distant','adj','دور','/ˈdɪstənt/ · far','He is a distant relative of mine.','[["He is a distant relative of mine.","او از اقوام دور من است."],["I had a distant relative living overseas.","من یک فامیل دور داشتم که در خارج از کشور زندگی می‌کرد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:distinct','distinct','adj','مجزا، متمایز','/dɪˈstɪŋkt/ · separate, clear and recognizable','There are two distinct groups.','[["There are two distinct groups.","دو گروه متمایز وجود دارد."],["The region has a distinct culture.","این منطقه دارای فرهنگ متمایز است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:distinction','distinction','n','تفاوت، تمایز، برجستگی، برتری','/dɪˈstɪŋkʃən/ · difference, excellence, honor','the distinction between formal and informal language','[["the distinction between formal and informal language","تمایز بین زبان رسمی و غیر رسمی"],["He received several military distinctions.","او چندین نشان نظامی دریافت کرد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:distinctive','distinctive','adj','شاخص، خاص، متمایز، برجسته','/dɪˈstɪŋktɪv/ · characteristic, distinguishing','A giraffe has a distinctive look.','[["A giraffe has a distinctive look.","زرافه ظاهری متمایز دارد."],["Our band needs a distinctive logo.","گروه ما به یک لوگوی متمایز نیاز دارد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:distinguish','distinguish','v','تشخیص دادن، تمیز دادن','/dɪˈstɪŋɡwɪ/ · notice from the difference, differentiate, recognize, identify','Can you distinguish between the twins?','[["Can you distinguish between the twins?","آیا می‌توانید بین دوقلوها تشخیص دهید؟"],["What distinguishes this phone from others?","چه چیزی این گوشی را از سایرین متمایز می‌کند؟"]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:diverse','diverse','adj','متنوع، گوناگون','/dəˈvɜːrs/ · distinct, various','London is a diverse city.','[["London is a diverse city.","لندن شهری متنوع است."],["The city has a diverse population.","این شهر دارای جمعیت متنوعی است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:doctrine','doctrine','n','طریق، مکتب، طریقت، دکترین','/ˈdɒktrən/ · principle, a set of beliefs that form an important part of a religion or system of ideas','The US military doctrine approves of the use of tactical nukes.','[["The US military doctrine approves of the use of tactical nukes.","دکترین نظامی ایالات متحده استفاده از سلاح‌های هسته‌ای تاکتیکی را تأیید می‌کند."],["Epicurus laid down the doctrine that pleasure was the chief good.","اپیکور این آموزه را مطرح کرد که لذت، خیر اصلی است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dramatically','dramatically','adv','به طور چشم‌گیری','/drəˈmæt.ɪ.kəl.i/ · noticeably, greatly, exceedingly','Sales rose dramatically in December.','[["Sales rose dramatically in December.","فروش در ماه دسامبر به طرز چشمگیری افزایش یافت."],["Prices have risen dramatically this year.","قیمت‌ها در سال جاری افزایش چشمگیری داشته است."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:dual','dual','adj','دوتایی','/ˈdjuːəl/ · double','Overtaking is simpler on a dual carriageway.','[["Overtaking is simpler on a dual carriageway.","سبقت گرفتن در جاده‌های دو بانده آسان‌تر است."],["I understand that you have dual citizenship.","متوجه شدم که شما تابعیت دوگانه دارید."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:elaborate','elaborate','adj','دقیق','/ɪˈlæbərət/ · detailed','They made elaborate plans.','[["They made elaborate plans.","آنها برنامه ریزی‌های دقیقی انجام دادند."],["She cooked an elaborate meal for the guests.","او یک غذای مفصل برای مهمانان پخت."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:eliminate','eliminate','v','از بین بردن، برداشتن','/ɪˈlɪmɪneɪt/ · remove, efface','We must eliminate errors from the report.','[["We must eliminate errors from the report.","ما باید خطاهای گزارش را حذف کنیم."],["The team was eliminated in the first round.","این تیم در دور اول حذف شد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:employ','employ','v','به کار بردن، استعمال کردن، بکار گماشتن','/ɪmˈplɔɪ/ · use, apply, hire','The company not employs a psychoanalyst.','[["The company not employs a psychoanalyst.","این شرکت روانکاو استخدام نمی‌کند."],["The police employed a water cannon.","پلیس از ماشین آب‌پاش استفاده کرد."]]','t1212',9,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:encounter','encounter','v','روبروشدن، مواجه شدن با','/ɪnˈkaʊntər/ · meet','Her suggestion has encountered a lot of opposition.','[["Her suggestion has encountered a lot of opposition.","پیشنهاد او با مخالفت‌های زیادی روبرو شده است."],["Male homosexual encounters still provoke strong reactions.","برخوردهای همجنسگرایان مرد هنوز واکنش‌های شدیدی را برمی‌انگیزد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:endangered','endangered','adj','در معرض خطر','/ɪnˈdeɪndʒərd/ · not abundant, put in danger','Without electricity, newborns and intensive care patients are endangered.','[["Without electricity, newborns and intensive care patients are endangered.","بدون برق، نوزادان و بیماران بخش مراقبت‌های ویژه در معرض خطر هستند."],["They are collecting tissue samples from critically endangered animals.","آنها در حال جمع‌آوری نمونه‌های بافت از حیوانات در معرض خطر انقراض هستند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enhance','enhance','v','بهبود دادن','/ɪnˈhæns/ · improve, intensify','Technology can enhance learning.','[["Technology can enhance learning.","فناوری می‌تواند یادگیری را تقویت کند."],["Good lighting can enhance the beauty of a room.","نور خوب می‌تواند زیبایی یک اتاق را افزایش دهد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enormous','enormous','adj','بزرگ','/əˈnɔːr.məs/ · huge, large, great, immense, massive, colossal','They live in an enormous house.','[["They live in an enormous house.","آنها در یک خانه بزرگ زندگی می‌کنند."],["The project was an enormous success.","این پروژه یک موفقیت بزرگ بود."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:enthusiastic','enthusiastic','adj','مشتاق','/ɪnˌθuː.ziˈæs.tɪk/ · eager, keen, avid','The islanders are enthusiastic about water sports.','[["The islanders are enthusiastic about water sports.","ساکنان جزیره به ورزش‌های آبی علاقه زیادی دارند."],["The youth is very enthusiastic about cycling.","جوانان علاقه زیادی به دوچرخه‌سواری دارند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:estimate','estimate','n','تخمین، تخمین زدن','/ˈestəmət/ · 1) projection 2) to try to judge the value, size, speed, cost etc of something','It is not easy to estimate how many people have the disease.','[["It is not easy to estimate how many people have the disease.","تخمین زدن تعداد افراد مبتلا به این بیماری آسان نیست."],["Scientists estimate that the tree is 2,000 years old.","دانشمندان تخمین می‌زنند که این درخت 2000 سال سن دارد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:evaluate','evaluate','v','ارزیابی کردن','/ɪˈvæljueɪt/ · judge, rate, assess','We need to evaluate the results.','[["We need to evaluate the results.","ما باید نتایج را ارزیابی کنیم."],["Teachers evaluate students'' progress every term.","معلمان پیشرفت دانش آموزان را در هر ترم ارزیابی می‌کنند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ever-shifting','ever-shifting','adj','همواره در حال تغییر','constant changing','The desert is a landscape of ever-shifting sand dunes.','[["The desert is a landscape of ever-shifting sand dunes.","کویر، چشم‌اندازی از تپه‌های شنیِ همیشه در حال تغییر است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:evident','evident','adj','آشکار، واضح','/ˈevɪdənt/ · obvious, apparent, clear, explicit','It is evident that prices are rising.','[["It is evident that prices are rising.","مشخص است که قیمت‌ها در حال افزایش است."],["It is evident that more needs to be done.","بدیهی است که باید کارهای بیشتری انجام شود."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:evolve','evolve','v','توسعه یافتن، دادن، تغییر پیدا کردن، دادن','/ɪˈvɑːlv/ · develop','Birds evolved from dinosaurs.','[["Birds evolved from dinosaurs.","پرندگان از دایناسورها تکامل یافته اند."],["The company has evolved into a global business.","این شرکت به یک تجارت جهانی تبدیل شده است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exceed','exceed','v','پیشی گرفتن','/ɪkˈsiːd/ · beyond above, surpass, 1) to be more than a particular number or amount, 2) to go beyond what rules or laws say you are allowed to do','The cost exceeded our budget.','[["The cost exceeded our budget.","هزینه بیشتر از بودجه ما بود."],["Do not exceed the speed limit.","از حد مجاز سرعت تجاوز نکنید."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exclusively','exclusively','adv','منحصرا، به تنهایی','/ɪkˈskluːsɪvli/ · only, solely','Lynxes feed exclusively on meat.','[["Lynxes feed exclusively on meat.","سیاهگوش‌ها منحصراً از گوشت تغذیه می‌کنند."],["Arabic writing is exclusively cursive.","خط عربی منحصراً به صورت شکسته نوشته می‌شود."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:execute','execute','v','انجام دادن','/ˈeksəkjuːt/ · perform, carry out, accomplish','Am I going to be executed?','[["Am I going to be executed?","آیا قرار است اعدام شوم؟"],["Miroslav mercilessly executed the young man.","میروسلاو بی‌رحمانه مرد جوان را اعدام کرد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exhausted','exhausted','adj','تحلیل رفته، استفاده‌شده','/ɪɡˈzɔːstɪd/ · tired, used up','Exhausted, she sunk into the cushion.','[["Exhausted, she sunk into the cushion.","خسته، در کوسن فرو رفت."],["They will get exhausted from running.","آنها از دویدن خسته خواهند شد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exhibit','exhibit','v','نشان دادن، نمایش دادن، ثابت کردن','/ɪɡˈzɪbɪt/ · demonstrate, display, illustrate','They will be exhibiting a collection of paintings.','[["They will be exhibiting a collection of paintings.","آنها مجموعه ای از نقاشی‌ها را به نمایش خواهند گذاشت."],["The museum exhibits ancient coins.","این موزه سکه‌های باستانی را به نمایش می‌گذارد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:explicit','explicit','adj','صریح و روشن، آشکار','/ɪkˈsplɪsɪt/ · obvious, clear, easily understandable','He was quite explicit as to what he expected us to do for him.','[["He was quite explicit as to what he expected us to do for him.","او کاملاً صریح بود که انتظار داشت ما برای او چه کاری انجام دهیم."],["The instructions were explicit.","دستورالعمل‌ها صریح بود."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:exploit','exploit','v','بهره برداری، سود بردن','/ɪkˈsplɔɪt/ · make use of, take advantage of, utilize','Some firms exploit cheap labor.','[["Some firms exploit cheap labor.","برخی از شرکت‌ها از نیروی کار ارزان بهره برداری می‌کنند."],["Some companies exploit their workers.","برخی از شرکت‌ها از کارگران خود استثمار می‌کنند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:expose','expose','v','نشان دادن چیزی که پوشیده یا مخفی‌شده، در معرض (خطر یا حمله یا سرما و یا هرچیز ناخوشایند) قرار دادن، بی پناه کردن','/ɪkˈspoʊz/ · subject to, susceptible to, make vulnerable to','Don''t expose the film to light.','[["Don''t expose the film to light.","فیلم را در معرض نور قرار ندهید."],["Don''t expose your skin to the sun for too long.","پوست خود را برای مدت طولانی در معرض نور خورشید قرار ندهید."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:faithful','faithful','adj','وفادار، باوفا، صدیق، پای بند','/ˈfeɪθfəl/ · loyal','A dog is a faithful companion.','[["A dog is a faithful companion.","سگ یک همراه وفادار است."],["He remained faithful through every challenge.","او در هر چالشی وفادار ماند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:fascinating','fascinating','adj','بسیار جالب و مجذوب‌کننده','/ˈfæsəneɪtɪŋ/ · extremely attractive','Synesthesia is a fascinating neurological condition.','[["Synesthesia is a fascinating neurological condition.","سینستزیا یک بیماری عصبی جذاب است."],["Maltese is such a fascinating language.","زبان مالتی واقعاً زبان جذابی است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:feast','feast','n','بزم، جشن، سور، مهمانی بزرگ، ضیافت','/fiːst/ · eating, banquet','The guests feasted all night.','[["The guests feasted all night.","مهمانان تمام شب را به جشن و پایکوبی پرداختند."],["He feasted on poached eggs.","او با تخم مرغ آب‌پز جشن گرفت."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ferry','ferry','n','کشتی مسافربری، کشتی گذاره؛ با کشتی جابه‌جا کردن','/ˈferi/ · transport, passenger boat','We took the ferry to the island.','[["We took the ferry to the island.","با کشتی به جزیره رفتیم."],["Where is that ferry going?","اون کشتی کجا میره؟"]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:flee','flee','v','گریختن، فرار کردن','/fled/ · run away from','I jumped with the intention to flee.','[["I jumped with the intention to flee.","با قصد فرار از جا پریدم."],["He desperately attempted to flee the area.","او با ناامیدی تلاش کرد از آن منطقه فرار کند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:flexible','flexible','adj','قابل انعطاف','/ˈfleksəbəl/ · adaptable, pliable, malleable','I have a flexible work schedule.','[["I have a flexible work schedule.","من یک برنامه کاری انعطاف پذیر دارم."],["My working hours are very flexible.","ساعت کاری من بسیار انعطاف پذیر است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:float','float','v','شناور شدن، شناور بودن','/floʊt/ · upward rise, stay on the top','A single leaf floated to the ground.','[["A single leaf floated to the ground.","یک برگ تنها روی زمین شناور شد."],["Ziri saw a blue balloon float away.","زیری بادکنک آبی رنگی را دید که در هوا شناور بود و دور شد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:foul','foul','adj','ناپاک','/faʊl/ · pollute, dirty, unclean','Harvestmen emit a foul odor when threatened.','[["Harvestmen emit a foul odor when threatened.","دروگران وقتی احساس خطر می‌کنند، بوی بدی از خود منتشر می‌کنند."],["They cried foul and demanded an explanation.","آنها فریاد اعتراض سر دادند و خواستار توضیح شدند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:frankly','frankly','adv','رک و پوست کنده، صادقانه','/ˈfræŋkli/ · openly, sincerely, honestly','Frankly, these parasites had it coming.','[["Frankly, these parasites had it coming.","راستش را بخواهید، این انگل‌ها از قبل آماده بودند."],["Frankly, I do not want these.","راستش را بخواهید، من اینها را نمی‌خواهم."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:furthermore','furthermore','adv','علاوه بر این، بعلاوه','/ˈfɜːrðərmɔːr/ · in addition, moreover','Candy costs money; furthermore, it''s bad for you.','[["Candy costs money; furthermore, it''s bad for you.","آب نبات هزینه دارد. علاوه بر این، برای شما بد است."],["Furthermore, their governments were not amalgamated in the same regions.","علاوه بر این، دولت‌های آنها در مناطق یکسانی ادغام نشده بودند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:generate','generate','v','تولید کردن','/ˈdʒenəreɪt/ · produce','Wind turbines generate electricity.','[["Wind turbines generate electricity.","توربین‌های بادی برق تولید می‌کنند."],["The new factory will generate hundreds of jobs.","کارخانه جدید صدها شغل ایجاد خواهد کرد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:genuinely','genuinely','adv','واقعاً','/dʒenjuɪnli/ · actually, in a real and sincere way','Something is genuinely wrong with him.','[["Something is genuinely wrong with him.","یه چیزی واقعاً براش مشکل داره."],["Ziri was a genuinely nice person.","زری واقعاً آدم خوبی بود."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:gesture','gesture','n','ژست، اشاره، حرکت','/ˈdʒestʃə/ · movement, a movement of part of your body, especially your hands or head, to show what you mean or how you feel','Gestures play a role in social communication.','[["Gestures play a role in social communication.","ژست‌ها در ارتباطات اجتماعی نقش دارند."],["Language may have evolved from gestures.","زبان ممکن است از ژست‌ها تکامل یافته باشد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:grasp','grasp','v','فهمیدن، درک کردن، گرفتن','/ɡræsp/ · understand, realize, grab','Debates can improve our grasp of issues.','[["Debates can improve our grasp of issues.","بحث‌ها می‌توانند درک ما از مسائل را بهبود بخشند."],["He grasped the situation with one glance.","با یک نگاه متوجه موقعیت شد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:halt','halt','v','ایست کردن، ایستادگی کردن','/hɑlt/ · stop','Production came grinding to a halt.','[["Production came grinding to a halt.","تولید به طور ناگهانی متوقف شد."],["The truck screeched to a halt.","کامیون با صدای جیغی ایستاد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:handy','handy','adj','سودمند، دستی، راحت','/ˈhændi/ · convenient','The universal adaptor came in handy abroad.','[["The universal adaptor came in handy abroad.","آداپتور جهانی در خارج از کشور مفید واقع شد."],["I think this will come in handy.","فکر می‌کنم این به کارم بیاید."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:harsh','harsh','adj','خشن، زننده','/hɑːrʃ/ · drastic, unpleasantly rough to the senses','Use mild soap, avoiding harsh chemicals.','[["Use mild soap, avoiding harsh chemicals.","از صابون ملایم استفاده کنید و از مواد شیمیایی قوی اجتناب کنید."],["She attacked him with harsh words.","با کلماتی تند به او حمله کرد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:haul','haul','v','کشیدن، هل دادن','/hɔːl/ · pull, drag','They were caught with some of the haul.','[["They were caught with some of the haul.","آنها با مقداری از محموله دستگیر شدند."],["They hauled everything in large bags.","آنها همه چیز را در کیسه‌های بزرگ حمل می‌کردند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hazard','hazard','n','خطر، مخاطره','/ˈhæzəd/ · danger, peril','Volcanic ash poses a hazard to aircraft.','[["Volcanic ash poses a hazard to aircraft.","خاکستر آتشفشانی برای هواپیماها خطرناک است."],["Flooding is a natural hazard in coastal regions.","سیل یک خطر طبیعی در مناطق ساحلی است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:heir','heir','n','وارث','/er/ · inheritor','He made me his heir.','[["He made me his heir.","او مرا وارث خود کرد."],["Tom is the sole heir.","تام تنها وارث است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hint','hint','n','سر نخ، مفهوم، شاخص، رهبری','/hɪnt/ · clue, implication, indication, lead','I need a hint for this riddle.','[["I need a hint for this riddle.","برای این معما به یه راهنمایی نیاز دارم."],["A hint of anxiety crosses my mind.","رگه ای از اضطراب از ذهنم عبور می‌کند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hobby','hobby','n','سرگرمی','/ˈhɑː.bi/ · pastime','I write songs as a hobby.','[["I write songs as a hobby.","من به عنوان یک سرگرمی آهنگ می‌نویسم."],["Drawing is one of my hobbies.","نقاشی یکی از علایق من است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hollow','hollow','n','جای خالی','/ˈhɒləʊ/ · an empty space','He made a hollow promise.','[["He made a hollow promise.","او وعده توخالی داد."],["The creature had hollow eyes.","آن موجود چشمانی گود و توخالی داشت."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:hub','hub','n','مرکز','/hʌb/ · center, focal point, core','It is a major logistics hub.','[["It is a major logistics hub.","این یک مرکز لجستیکی بزرگ است."],["India is a hub of cultures.","هند، مرکز فرهنگ‌هاست."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:identical','identical','adj','یکسان، همانند','/aɪˈdentɪkəl/ · the same (exactly), indistinguishable','The results were identical to those of the first test.','[["The results were identical to those of the first test.","نتایج با نتایج آزمایش اول یکسان بود."],["The two computers were otherwise identical.","این دو کامپیوتر از جهات دیگر کاملاً یکسان بودند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:illusion','illusion','n','وهم، خیال، خیال باطل','/ɪˈluːʒən/ · impression 1)an idea or opinion that is wrong, especially about yourself.2)something that seems to be different from the way it really is','Optical illusions reveal brain processing limits.','[["Optical illusions reveal brain processing limits.","توهمات نوری محدودیت‌های پردازش مغز را نشان می‌دهد."],["My illusions were taken away by fate.","توهمات من توسط سرنوشت از بین رفت."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:immense','immense','adj','بسیار بزرگ، عظیم','/ɪˈmens/ · enormous, very big, great, huge, vast, extensive, massive','The project was an immense success.','[["The project was an immense success.","این پروژه یک موفقیت بزرگ بود."],["Despite our differences, we respect each other immensely.","با وجود تفاوت‌هایمان، ما بی‌نهایت به یکدیگر احترام می‌گذاریم."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:implement','implement','v','اجرا کردن، انجام دادن؛ ابزار، وسیله','/ˈɪmpləment/ · 1)put into action, tool, a tool, especially one used for outdoor physical work.2)carry out, to take action or make changes that you have officially decided should happen','The policy was implemented in 2019.','[["The policy was implemented in 2019.","این سیاست در سال 2019 اجرا شد."],["The school will implement the new rules next year.","این مدرسه سال آینده قوانین جدید را اجرا خواهد کرد."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:imply','imply','v','اشاره کردن','/ɪmˈplaɪ/ · indicate','Early reports implied that the judge''s death was not an accident.','[["Early reports implied that the judge''s death was not an accident.","گزارش‌های اولیه حاکی از آن است که مرگ قاضی یک تصادف نبوده است."],["His silence implied agreement.","سکوت او به معنای توافق بود."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:incentive','incentive','n','انگیزه','/ɪnˈsentɪv/ · motive, stimulus, impetus','Tax incentives encourage green energy.','[["Tax incentives encourage green energy.","مشوق‌های مالیاتی انرژی سبز را تشویق می‌کند."],["Tax breaks are an incentive for companies to invest.","معافیت‌های مالیاتی انگیزه ای برای شرکت‌ها برای سرمایه گذاری است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:incorporate','incorporate','v','ادغام کردن، ترکیب کردن','/ɪnˈkɔːpəreɪt/ · include, merge','His book incorporates all his thinking on the subject.','[["His book incorporates all his thinking on the subject.","کتاب او تمام افکار او را در مورد این موضوع در بر می‌گیرد."],["The new design incorporates solar panels.","طراحی جدید شامل پنل‌های خورشیدی است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:indigenous','indigenous','adj','بومی','/ɪnˈdɪdʒɪnəs/ · native','Indigenous peoples have lived here for centuries.','[["Indigenous peoples have lived here for centuries.","مردمان بومی قرن‌ها در اینجا زندگی می‌کنند."],["The indigenous people of the region speak their own language.","مردم بومی منطقه به زبان خودشان صحبت می‌کنند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inevitable','inevitable','adj','اجتناب‌ناپذیر','/ɪˈnevətəbəl/ · unavoidable','Change is inevitable in life.','[["Change is inevitable in life.","تغییر در زندگی اجتناب ناپذیر است."],["With such poor planning, failure was inevitable.","با چنین برنامه ریزی ضعیفی، شکست اجتناب ناپذیر بود."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:inherent','inherent','adj','ذاتی، بالقوه، طبیعی، اصلی','/ˈher-/ · essential, essential, in characteristic, instinctive, internal','There are risks inherent in any business.','[["There are risks inherent in any business.","خطرات ذاتی در هر کسب و کاری وجود دارد."],["Curiosity is inherent in human nature.","کنجکاوی در ذات انسان نهفته است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:innovative','innovative','adj','خلاقانه، جدید','/ˈinəˌvātiv/ · new, featuring new methods','technological innovations designed to save energy','[["technological innovations designed to save energy","نوآوری‌های تکنولوژیکی که برای صرفه جویی در انرژی طراحی شده اند"],["The company is known for its innovative products.","این شرکت به خاطر محصولات نوآورانه خود شناخته شده است."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:insight-into','insight into','phr','بینش نسبت به، درک عمیق از','perceive, comprehension into','Physics provides insight into the universally applicable laws of our world.','[["Physics provides insight into the universally applicable laws of our world.","فیزیک بینشی در مورد قوانین جهانی قابل اجرا در جهان ما ارائه می‌دهد."],["Human beings often lack insight into their own faults and failings.","انسان‌ها اغلب فاقد بینش نسبت به خطاها و شکست‌های خود هستند."]]','t1212',10,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:install','install','v','نصب، راه اندازی','/inˈstôl/ · put in place, mount','They are installing face recognition cameras.','[["They are installing face recognition cameras.","دارن دوربین‌های تشخیص چهره نصب می‌کنن."],["The relevant components should be installed.","اجزای مربوطه باید نصب شوند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intact','intact','adj','سالم، دست نخورده','/inˈtakt/ · untouched, complete','The ancient walls are still intact.','[["The ancient walls are still intact.","دیوارهای باستانی هنوز دست نخورده هستند."],["All his teeth were intact.","تمام دندان‌هایش سالم بودند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:integral','integral','adj','ضروری','/ˈɪntəɡrəl/ · essential, forming a necessary part of something','Sport is an integral part of school life.','[["Sport is an integral part of school life.","ورزش بخشی جدایی ناپذیر از زندگی مدرسه است."],["Music is integral to the film.","موسیقی جزء لاینفک فیلم است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intentionally','intentionally','adv','از قصد، عمداً','/ɪnˈtenʃənəli/ · deliberately','Leon was intentionally shaking the curtain.','[["Leon was intentionally shaking the curtain.","لئون عمداً داشت پرده را تکان می‌داد."],["Michael made a few mistakes intentionally.","مایکل عمداً چند اشتباه مرتکب شد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intermediate','intermediate','adj','متوسط','/ˌintərˈmēdē-it/ · in-between, a person who is learning something and who has more than a basic knowledge of it but is not yet advanced, being between two other related things, levels, or points','intermediate learners of English','[["intermediate learners of English","زبان آموزان متوسط انگلیسی"],["I''m in the intermediate class.","من در کلاس متوسط ​​هستم."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:intimate','intimate','adj','صمیمی، خصوصی؛ عمیق (دانش)','/ˈɪn.tə.mət/ · 1)adjective, familiar, close 2)verb, to make people understand what you mean without saying it directly 3)noun, a close personal friend','The dance gradually became intimate.','[["The dance gradually became intimate.","رقص کم کم صمیمی شد."],["Ziri started having intimate experiences.","زیری شروع به تجربه‌های جنسی کرد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:isolated','isolated','adj','جدا‌شده','/ˈīsəˌlātid/ · separated, far away from other places, buildings, or people; remote','He is completely isolated from society.','[["He is completely isolated from society.","او کاملاً از جامعه منزوی است."],["He lives in an isolated place.","او در مکانی دورافتاده زندگی می‌کند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:junction','junction','n','اتصال','/ˈjəNGkSHən/ · connection','The accident happened at that junction.','[["The accident happened at that junction.","تصادف در آن تقاطع اتفاق افتاد."],["At the first junction, turn left.","در اولین تقاطع، به چپ بپیچید."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:justified','justified','adj','حق دادن، تصدیق کردن، تعدیل‌شده','/ˈdʒʌstɪfaɪd/ · right, having an acceptable explanation or reason','Do you think that was justified?','[["Do you think that was justified?","به نظر شما این توجیه داشت؟"],["He justified his decision at length.","او تصمیم خود را به تفصیل توجیه کرد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:justify','justify','v','توجیه کردن، حق دادن','/ˈjəstəˌfī/ · prove, give reasons for, give a justification for','Can the high cost be justified?','[["Can the high cost be justified?","آیا هزینه بالا قابل توجیه است؟"],["How can you justify spending so much money?","چگونه می‌توانید خرج کردن این همه پول را توجیه کنید؟"]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:leisure','leisure','n','فراغت، مجال','/ˈliː.ʒɚ/ · free time','Leisure travel has grown due to cheaper flights.','[["Leisure travel has grown due to cheaper flights.","سفرهای تفریحی به دلیل پروازهای ارزان‌تر رشد کرده است."],["He imagined leisurely mornings without rush.","او صبح‌های آرام و بدون عجله را تصور می‌کرد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:lethal','lethal','adj','مرگ بار، مهلک','/ˈliːθəl/ · deadly, fateful, fatal','His fart was so lethal that I nearly passed out.','[["His fart was so lethal that I nearly passed out.","باد معده‌اش آنقدر کشنده بود که نزدیک بود از حال بروم."],["The court condemned the man to death by lethal injection.","دادگاه این مرد را به اعدام با تزریق سم محکوم کرد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:likewise','likewise','adv','همچنین','/ˈlaɪk-waɪz/ · similarly, in a like manner','The fish was delicious. Likewise, the eggplant was excellent.','[["The fish was delicious. Likewise, the eggplant was excellent.","ماهی خوشمزه بود بادمجان هم عالی بود."],["Likewise, passing is prohibited on bridges.","به همین ترتیب، عبور از روی پل‌ها ممنوع است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:magnitude','magnitude','n','بزرگی، اندازه، مقدار، اهمیت','/ˈmæɡnɪtjuːd/ · size; amount; extent, hugeness','Scientists measured the eruption''s magnitude using modern instruments.','[["Scientists measured the eruption''s magnitude using modern instruments.","دانشمندان بزرگی فوران را با استفاده از ابزارهای مدرن اندازه گیری کردند."],["The earthquake was very severe, with a magnitude of 5.2.","زلزله بسیار شدیدی بود و قدرت آن ۵.۲ ریشتر بود."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mandatory','mandatory','adj','اجباری، الزامی','/ˈmændətɔːri/ · obligatory; required, compulsory','Wearing a helmet is mandatory.','[["Wearing a helmet is mandatory.","استفاده از کلاه ایمنی الزامی است."],["In programming as in logic, testing edge cases is mandatory.","در برنامه‌نویسی نیز مانند منطق، آزمایش موارد حاشیه‌ای الزامی است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mature','mature','v','رشد کردن، بحد بلوغ یا رشد رساندن، کامل کردن','/məˈtʊr/ · develop, get older, be fully grown, reach adulthood','Laura is very mature for her age.','[["Laura is very mature for her age.","لورا نسبت به سن خود بسیار بالغ است."],["Shawn is very bright, but not academically mature.","شان بسیار باهوش است، اما از نظر تحصیلی بالغ نیست."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mechanism','mechanism','n','مکانیک، مکانیک ماشین آلات','/ˈmekənɪzəm/ · means, a natural or established process by which something takes place or is brought about','Sweating is the body''s cooling mechanism.','[["Sweating is the body''s cooling mechanism.","عرق کردن مکانیسم خنک کننده بدن است."],["There is no mechanism for solving such disputes.","هیچ مکانیزمی برای حل چنین اختلافاتی وجود ندارد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:merit','merit','n','شایستگی، لیاقت، استحقاق؛ سزاوار بودن','/ˈmerɪt/ · 1)[n] worth, an advantage or good feature of something.2)[v] to be good, important, or serious enough for praise or attention.','Show gratitude to those who merit it.','[["Show gratitude to those who merit it.","از کسانی که شایسته‌ی قدردانی هستند، قدردانی کنید."],["The world was created in its merit.","جهان بر اساس شایستگی خود آفریده شده است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:misleading','misleading','adj','گمراه‌کننده','/mɪsˈliːdɪŋ/ · erroneous, inaccurate, unreliable, giving the wrong idea or impression','That summary is misleading, a bunch of stuff was left out.','[["That summary is misleading, a bunch of stuff was left out.","این خلاصه گمراه‌کننده است، خیلی چیزها از قلم افتاده."],["There are few things more dishonorable than misleading the young.","کمتر چیزی شرم‌آورتر از گمراه کردن جوانان است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:mock','mock','v','مسخره کردن، دست انداختن؛ ساختگی، تقلیدی','/mɑːk/ · pretend','The way he mocked me felt so disrespectful.','[["The way he mocked me felt so disrespectful.","جوری که مسخره‌ام می‌کرد، خیلی بی‌احترامی به نظر می‌رسید."],["I have to prepare for that mock trial.","باید برای آن دادگاه ساختگی آماده شوم."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:moderate','moderate','adj','معتدل، میانه‌رو، متوسط','/ˈmɑdərət/ · temperate, mediocre, mild','Your risk of prostate cancer is moderate.','[["Your risk of prostate cancer is moderate.","خطر ابتلا به سرطان پروستات در شما متوسط ​​است."],["This is moderately spicy but arouses appetite.","این ادویه نسبتاً تند است اما اشتها را تحریک می‌کند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:modest','modest','adj','نسبتاً کم','/ˈmɑːdɪst/ · limited, small, relatively moderate (of an amount, rate, or level of something)','This is a modest gift for you.','[["This is a modest gift for you.","این یک هدیه‌ی کوچک و بی‌ارزش برای شماست."],["A modest ceremony would suit me perfectly.","یک مراسم ساده و معمولی کاملاً مناسب من است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:monopoly','monopoly','n','انحصار','/məˈnɒpəli/ · domination','Government policies prevent market monopolies.','[["Government policies prevent market monopolies.","سیاست‌های دولت از انحصار بازار جلوگیری می‌کند."],["Nobody has a monopoly on truth.","هیچ‌کس انحصار حقیقت را ندارد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:moreover','moreover','adv','علاوه بر این، به اضافه','/mɔːrˈəʊvə/ · additionally, in addition, furthermore','Moreover, how much did you pay for that?','[["Moreover, how much did you pay for that?","بعلاوه، چقدر برای آن هزینه کردید؟"],["They laugh and, moreover, with an open throat.","آنها می‌خندند و علاوه بر این، با گلوی باز."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:nevertheless','nevertheless','adv','با این وجود','/ˌnev.ɚ.ðəˈles/ · however, in spite of','It was raining; nevertheless, we went out.','[["It was raining; nevertheless, we went out.","باران می‌بارید؛ با این حال رفتیم بیرون"],["The task was difficult; nevertheless, they finished it.","کار دشوار بود؛ با این حال آنها آن را تمام کردند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:notable','notable','adj','قابل توجه، مهم','/ˈnoʊ.tə.bəl/ · important, outstanding','Numerous notable individuals have been actively involved with the charity.','[["Numerous notable individuals have been actively involved with the charity.","افراد سرشناس زیادی به طور فعال در این خیریه مشارکت داشته‌اند."],["The area is notable for its scenery and wildlife.","این منطقه به دلیل مناظر و حیات وحش خود قابل توجه است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:notably','notably','adv','ویژه، به ویژه، به خصوص','/ˈnəʊtəbli/ · especially1) used to say that a person or thing is a typical example or the most important example of something 2)formal in a way that is clearly different, important, or unusual','Namibia has a notably low population density.','[["Namibia has a notably low population density.","نامیبیا تراکم جمعیت بسیار پایینی دارد."],["Diet affects health, notably the heart.","رژیم غذایی بر سلامت، به ویژه قلب، تأثیر می‌گذارد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:notion','notion','n','ایده','/ˈnoʊ.ʃən/ · idea, vision','He has some pretty strange notions.','[["He has some pretty strange notions.","او تصورات بسیار عجیبی دارد."],["The notion that the Earth is flat was rejected.","این تصور که زمین مسطح است رد شد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:obscure','obscure','adj','مبهم، گمنام، تیره؛ مبهم کردن، پنهان کردن','/əbˈskjʊr/ · 1)not well known and usually not very important, 2)unclear, difficult to understand','Mark writes his academic papers obscurely.','[["Mark writes his academic papers obscurely.","مارک مقالات دانشگاهی خود را مبهم می‌نویسد."],["Thick morning fog obscured the horizon.","مه غلیظ صبحگاهی افق را پوشانده بود."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:obsession-with','obsession with','phr','وسواس، فکر دائمی، علاقه بیش از اندازه','/əbˈseʃ.ən/ · fixation on, something or someone that you think about all the time','What is your obsession with kids?','[["What is your obsession with kids?","وسواس شما نسبت به بچه‌ها چیه؟"],["He has an obsession with cleanliness.","او به نظافت علاقه دارد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:offset','offset','v','جبران کردن، موازنه کردن','/ˈɒːfset/ · 1)balance 2)compensate 3)make up 4)counterbalance','Higher prices were offset by better quality.','[["Higher prices were offset by better quality.","قیمت‌های بالاتر با کیفیت بهتر جبران شد."],["For the last two months, your profit has offset your expenses.","در دو ماه گذشته، سود شما هزینه‌هایتان را جبران کرده است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:on-the-contrary','on the contrary','phr','برعکس، بر خلاف','1)on the other hand 2)whereas','Was he in poverty? on the contrary, he was rich.','[["Was he in poverty? on the contrary, he was rich.","آیا او در فقر بود؟ برعکس، او ثروتمند بود."],["On the contrary, I''d never say such a thing.","برعکس، من هرگز چنین چیزی نمی‌گویم."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:optimal','optimal','adj','بهینه','/ˈɑːptəməl/ · 1)most advantageous 2)ideal, best or most favorable; optimum','The decision is not optimal, but I concur.','[["The decision is not optimal, but I concur.","این تصمیم بهینه نیست، اما من موافقم."],["Finding an optimal solution will take some time.","پیدا کردن یک راه حل بهینه کمی زمان می‌برد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:orientation','orientation','n','گرایش، جهت','/ˌɔːriənˈteɪʃən/ · 1)perspective 2) introduction','How can we get students to adopt a serious orientation to learning?','[["How can we get students to adopt a serious orientation to learning?","چگونه می‌توانیم دانش آموزان را وادار کنیم که جهت گیری جدی برای یادگیری اتخاذ کنند؟"],["Animals rely on visual orientation for navigation.","حیوانات برای ناوبری به جهت گیری بصری متکی هستند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:outbreak','outbreak','n','ظهور، شیوع','/ˈaʊtbreɪk/ · sudden increase','Algeria is able to contain the coronavirus outbreak.','[["Algeria is able to contain the coronavirus outbreak.","الجزایر قادر به مهار شیوع ویروس کرونا است."],["The legionellosis outbreak has exceeded 100 cases.","شیوع لژیونلوز از ۱۰۰ مورد فراتر رفته است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:overview','overview','n','بررسی اجمالی، خلاصه','/ˈoʊvərvjuː/ · summary','We will conclude our overview, however, with a positive example.','[["We will conclude our overview, however, with a positive example.","با این حال، بررسی اجمالی خود را با یک مثال مثبت به پایان خواهیم رساند."],["We had lost the overview a long time ago.","ما مدت‌ها پیش، دید کلی را از دست داده بودیم."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:overwhelming','overwhelming','adj','طاقت فرسا، خورد‌کننده، فشاراور، سخت','/ˌoʊvərˈwelmɪŋ/ · powerful, very great in amount','Learning a new language feels overwhelming.','[["Learning a new language feels overwhelming.","یادگیری یک زبان جدید احساس طاقت‌فرسایی دارد."],["The emptiness inside me is overwhelming.","خلأ درونم به شدت مرا فرا گرفته است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:patch','patch','n','نقطه، وصله','/pætʃ/ · 1)area 2) spot','He went through a rough patch.','[["He went through a rough patch.","او دوران سختی را پشت سر گذاشت."],["Your vegetable patch is a mess.","باغچه سبزیجاتت حسابی بهم ریخته است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:permit','permit','v','اجازه دادن','/pərˈmɪt/ · allow, enable','You are not permitted to smoke.','[["You are not permitted to smoke.","شما مجاز به سیگار کشیدن نیستید."],["Permit him to water the ground.","بگذار زمین را آبیاری کند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:persistent','persistent','adj','مداوم','/pərˈsɪstənt/ · long lasting','Persistent reports of human rights abuses by the military','[["Persistent reports of human rights abuses by the military","گزارش‌های مداوم از نقض حقوق بشر توسط ارتش"],["He has a persistent cough.","سرفه مداوم دارد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:phenomenon','phenomenon','n','حادثه، اثر طبیعی','/nə/ · 1)observable fact 2)occurrence','Globalization is a modern phenomenon.','[["Globalization is a modern phenomenon.","جهانی شدن یک پدیده مدرن است."],["Northern lights are a natural phenomenon.","شفق شمالی یک پدیده طبیعی است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pioneer','pioneer','n','پیشرو، پیشقدم','/ˌpaɪəˈnɪə/ · initiate, forerunner, progenitor','Samuel Morse was a pioneer of modern communication.','[["Samuel Morse was a pioneer of modern communication.","ساموئل مورس از پیشگامان ارتباطات مدرن بود."],["He was a pioneer of Canadian photography.","او از پیشگامان عکاسی کانادا بود."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:plague','plague','n','آزار رساندن، به ستوه آوردن؛ طاعون، بلا','/pleɪɡ/ · 1) to cause pain, suffering, or trouble to someone,especially for a long period of time.2) a disease that causes death and spreads quicklyto a large number of people','Bureaucracy is plaguing our lives.','[["Bureaucracy is plaguing our lives.","بوروکراسی زندگی ما را فلج کرده است."],["She was plagued by anxieties.","او گرفتار اضطراب بود."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:portable','portable','adj','قابل حمل','/ˈpɔːrtəbl/ · can be carried or moved easily','Octopuses use coconut shells as portable shelters.','[["Octopuses use coconut shells as portable shelters.","اختاپوس‌ها از پوسته نارگیل به عنوان پناهگاه‌های قابل حمل استفاده می‌کنند."],["The guitar is a portable instrument.","گیتار یک ساز قابل حمل است."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pose','pose','n','ژست، ژست دروغین، فیگور، حالت','/poʊz/ · present, place, the position in which someone stands or sits, especially in a painting, photograph etc','Pollution poses a threat to health.','[["Pollution poses a threat to health.","آلودگی سلامتی را تهدید می‌کند."],["He poses us no threat.","او هیچ خطری ما را تهدید نمی‌کند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:practically','practically','adv','تقریباً','/ˈpræktɪkli/ · nearly, virtually; almost, in a practical manner','He''s practically drowning in gold.','[["He''s practically drowning in gold.","او عملاً در طلا غرق شده است."],["Tom practically threw himself at me.","تام تقریباً خودش را به سمت من انداخت."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:precise','precise','adj','دقیق و درست','/prɪˈsaɪs/ · exact','We need precise measurements.','[["We need precise measurements.","ما به اندازه گیری‌های دقیق نیاز داریم."],["At that precise moment, the phone rang.","در همان لحظه تلفن زنگ خورد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:precision','precision','n','دقت','/prɪˈsɪʒən/ · accuracy','Precision in time measurement improved global trade.','[["Precision in time measurement improved global trade.","دقت در اندازه گیری زمان تجارت جهانی را بهبود بخشید."],["Precision in research ensures reliability.","دقت در تحقیق، قابلیت اطمینان را تضمین می‌کند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prediction','prediction','n','پیش بینی، پیشگویی','/prɪˈdɪkʃən/ · prophecy, forecast','His prediction might possibly come true.','[["His prediction might possibly come true.","پیش بینی او ممکن است به حقیقت بپیوندد."],["None of his predictions came true.","هیچ کدام از پیش بینی‌های او درست از آب درنیامد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:predominantly','predominantly','adv','عمدتا، اغلب','/prɪˈdɑːmənəntli/ · mostly or mainly, principally, primitively, dominantly','The area is predominantly residential.','[["The area is predominantly residential.","این منطقه عمدتاً مسکونی است."],["The town''s population is predominantly young.","جمعیت این شهر عمدتاً جوان هستند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:premise','premise','n','فرض، بنیاد و اساس چیزی','/premɪs/ · assume, a statement or idea that you accept as true and use as a base for developing other ideas, assumption','These premises need a makeover.','[["These premises need a makeover.","این مکان‌ها نیاز به بازسازی اساسی دارند."],["We entered the school premises.","وارد محوطه مدرسه شدیم."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:preserve','preserve','v','حفظ کردن','/prɪˈzɜːrv/ · protect, retain, save, keep','Efforts are made to preserve endangered languages.','[["Efforts are made to preserve endangered languages.","تلاش‌ها برای حفظ زبان‌های در معرض خطر انجام می‌شود."],["They have preserved this eating technique and still use chopsticks today.","آن‌ها این شیوهٔ غذا خوردن را حفظ کرده‌اند و هنوز هم از چوب غذاخوری استفاده می‌کنند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:presumably','presumably','adv','احتمالاً','/prɪˈzuːməbli/ · probably','Presumably it was lost in translation.','[["Presumably it was lost in translation.","احتمالاً در ترجمه گم شده است."],["Presumably, he buys them abroad.","احتمالاً، او آنها را از خارج از کشور می‌خرد."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:primitive','primitive','adj','اولیه','/ˈprɪmətɪv/ · early, basic and simple, primary, preliminary','Primitive tools were made of stone.','[["Primitive tools were made of stone.","ابزارهای اولیه از سنگ ساخته می‌شدند."],["Primitive people used stone tools.","مردم بدوی از ابزار سنگی استفاده می‌کردند."]]','t1212',11,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:probe','probe','v','کاوش کردن','/proʊb/ · explore','The probe flew off into space.','[["The probe flew off into space.","کاوشگر به فضا پرتاب شد."],["The probe inserted itself into orbit.","کاوشگر خود را در مدار قرار داد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:profound','profound','adj','عمیق، دور از دسترس','/prəˈfaʊnd/ · far-reaching, deep','Spanish society is profoundly feminist.','[["Spanish society is profoundly feminist.","جامعه اسپانیا عمیقاً فمینیستی است."],["Abundant but not profound intelligence.","هوش فراوان اما نه عمیق."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prolonged','prolonged','adj','طولانی مدت','/prəˈlɔːŋd/ · lengthy','The treatment prolonged the agony.','[["The treatment prolonged the agony.","این درمان، درد و رنج را طولانی‌تر کرد."],["There followed a prolonged silence.","سکوتی طولانی حکمفرما شد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prompt','prompt','v','باعث شدن، برانگیختن','/prɑːmpt/ · cause','His success prompted other scientists to try new ideas.','[["His success prompted other scientists to try new ideas.","موفقیت او دانشمندان دیگر را بر آن داشت تا ایده‌های جدیدی را امتحان کنند."],["He promptly threw a tantrum.","او فوراً قشقرق به پا کرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pronounced','pronounced','adj','قابل توجه، واضح','/prəˈnaʊnst/ · definite, clear, notable, very noticeable or marked; conspicuous','I know how it is pronounced.','[["I know how it is pronounced.","من می‌دانم چطور تلفظ می‌شود."],["You pronounced all the words correctly.","همه کلمات رو درست تلفظ کردی."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:propose','propose','v','پیشنهاد کردن، مطرح کردن','/prəˈpoʊz/ · suggest, put forward (an idea or plan) for consideration or discussion by others','He agrees with the offer proposed.','[["He agrees with the offer proposed.","او با پیشنهاد ارائه شده موافق است."],["May I propose an alternative solution?","میشه یه راه حل جایگزین پیشنهاد بدم؟"]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prosperity','prosperity','n','کامیابی، سلامت','/prɑːˈsperəti/ · wellbeing, success, the state of being prosperous','Algeria needs to determine its own prosperity.','[["Algeria needs to determine its own prosperity.","الجزایر باید خودش سرنوشت خودش را رقم بزند."],["Each of them wishes prosperity to another.","هر یک از آنها برای دیگری آرزوی سعادت و خوشبختی می‌کند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:prototype','prototype','n','نمونه اولیه','/ˈproʊtətaɪp/ · model, a first, typical or preliminary model of something','The engineers built a prototype of the new car.','[["The engineers built a prototype of the new car.","مهندسان یک نمونه اولیه از ماشین جدید ساختند."],["The prototype was crude but functional.","نمونه اولیه خام اما کاربردی بود."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:proximity','proximity','n','نزدیکی','/prɑːkˈsɪməti/ · nearness, closeness, vicinity','They want to build a hotel in proximity to the beach.','[["They want to build a hotel in proximity to the beach.","آنها می‌خواهند هتلی در نزدیکی ساحل بسازند."],["The big change is the proximity to death.","تغییر بزرگ، نزدیکی به مرگ است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:pursue','pursue','v','دنبال کردن، تعقیب کردن','/pərˈsuː/ · chase, follow','He wants to pursue a career in medicine.','[["He wants to pursue a career in medicine.","او می‌خواهد حرفه پزشکی را دنبال کند."],["She left her job to pursue a career in music.","او کار خود را رها کرد و به دنبال حرفه موسیقی بود."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rational','rational','adj','منطقی','/ˈræʃənəl/ · sensible/logical, reasonable','There is no rational explanation for his actions.','[["There is no rational explanation for his actions.","هیچ توضیح منطقی برای اعمال او وجود ندارد."],["Economists assumed people make rational decisions.","اقتصاددانان تصور می‌کردند که مردم تصمیمات منطقی می‌گیرند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:readily','readily','adv','به راحتی','/ˈredəli/ · easily, eagerly','I could readily believe it.','[["I could readily believe it.","به راحتی می‌توانستم باور کنم."],["Tom readily agreed to it.","تام به راحتی با آن موافقت کرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
