INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rebellion','rebellion','n','شورش','/rɪˈbeljən/ · revolt, riot','The rebellion was abruptly called off.','[["The rebellion was abruptly called off.","شورش ناگهان متوقف شد."],["What caused such a great rebellion?","چه چیزی باعث چنین شورش بزرگی شد؟"]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
