INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:refuge','refuge','n','پناه، پناهگاه','/ˈrefuːdʒ/ · safety, shelterm refugee (n)','Welcome to my little refuge.','[["Welcome to my little refuge.","به پناهگاه کوچک من خوش آمدید."],["My deed is my refuge.","عمل من پناهگاه من است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:regulate','regulate','v','تنظیم کردن، میزان کردن','/ˈreɡjəleɪt/ · adjust; control; control or maintain the rate or speed of (a machine or process) so that it operates properly','The government regulates food safety.','[["The government regulates food safety.","دولت ایمنی مواد غذایی را تنظیم می‌کند."],["The government regulates the price of bread.","دولت قیمت نان را تنظیم می‌کند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:reluctant','reluctant','adj','بی میل بودن به چیزی، مخالف بودن','/rɪˈlʌktənt/ · disinclined; unwilling and hesitant','She was reluctant to lend him money.','[["She was reluctant to lend him money.","او تمایلی به قرض دادن به او نداشت."],["Many people are reluctant to change their habits.","بسیاری از افراد تمایلی به تغییر عادات خود ندارند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:remarkable','remarkable','adj','قابل توجه، زیاد','/rɪˈmɑːkəbəl/ · 1)notable 2)incredible','There was a remarkable rise in exports.','[["There was a remarkable rise in exports.","افزایش قابل توجهی در صادرات بود."],["The city has made remarkable progress in reducing pollution.","این شهر پیشرفت چشمگیری در کاهش آلودگی داشته است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:remedy','remedy','n','درمان','/ˈremədi/ · cure, treatment, therapy','Honey is a traditional remedy for a sore throat.','[["Honey is a traditional remedy for a sore throat.","عسل یک درمان سنتی برای گلودرد است."],["Chicken broth is a renowned remedy.","آب مرغ یک درمان شناخته شده است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
