INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:respective','respective','adj','مخصوص، ویژه، قابل احترام','/rɪˈspektɪv/ · particular','The students returned to their respective classrooms.','[["The students returned to their respective classrooms.","دانش‌آموزان به کلاس‌های درس خود بازگشتند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:restricted','restricted','adj','محدود','/rɪˈstrɪktɪd/ · limited','The island was restricted from the public.','[["The island was restricted from the public.","این جزیره از دسترس عموم مردم خارج بود."],["Dmitri was spotted in a restricted area.","دیمیتری در یک منطقه ممنوعه دیده شد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:resume','resume','v','از سر گرفتن، دوباره شروع کردن','/rɪˈzjuːm/ · start again','The resume is in the attachment.','[["The resume is in the attachment.","رزومه در فایل پیوست موجود است."],["The championship will resume this week.","مسابقات قهرمانی این هفته از سر گرفته خواهد شد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:retain','retain','v','حفظ کردن، نگه داری کردن','/rɪˈteɪn/ · maintain, keep','You have the right to retain possession of the goods.','[["You have the right to retain possession of the goods.","شما حق دارید که مالکیت کالا را حفظ کنید."],["Clay soil retains water well.","خاک رسی آب را به خوبی حفظ می‌کند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:retreat','retreat','v','عقب نشینی کردن، عقب نشستن','/rɪˈtriːt/ · recede','Fyodor arrived just as the sun began to retreat.','[["Fyodor arrived just as the sun began to retreat.","فئودور درست زمانی رسید که خورشید شروع به غروب کردن کرد."],["The fog was retreating back to the creek.","مه داشت به سمت نهر عقب‌نشینی می‌کرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:revival','revival','n','احیا، تجدید','/rɪˈvaɪvəl/ · restoration, resuscitation','Berber is undergoing a strong revival movement.','[["Berber is undergoing a strong revival movement.","بربر در حال گذراندن یک جنبش احیای قوی است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ritual','ritual','n','آیین، مراسم، تشریفات','/ˈrɪtʃuəl/ · ceremonial','Music and dance were part of sacred rituals.','[["Music and dance were part of sacred rituals.","موسیقی و رقص بخشی از آیین‌های مقدس بود."],["Rituals were central to prehistoric spiritual life.","تشریفات در زندگی معنوی ماقبل تاریخ نقش اساسی داشتند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:rival','rival','v','رقابت کردن','/ˈraɪvəl/ · compete vrivalry, a situation in which two or more people are competing for something','No one can rival her in beauty.','[["No one can rival her in beauty.","هیچ کس از نظر زیبایی نمی‌تواند با او رقابت کند."],["He got his rival arrested by trickery.","او با حیله و نیرنگ رقیبش را دستگیر کرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:robust','robust','adj','سالم، تنومند','/rəˈbʌst/ · healthy','France has a robust public transit network.','[["France has a robust public transit network.","فرانسه شبکه حمل و نقل عمومی قدرتمندی دارد."],["Cardboard is more robust than paper.","مقوا از کاغذ مقاوم‌تر است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sacred','sacred','adj','مقدس، وقف‌شده','/ˈseɪkrɪd/ · holy','Sacred and sweet was all I saw in her.','[["Sacred and sweet was all I saw in her.","تنها چیزی که در او می‌دیدم، مقدس و شیرین بود."],["The cow is sacred to the local people.","گاو برای مردم محلی مقدس است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:satisfied','satisfied','adj','راضی، متقاعد، خشنود','/ˈsætəsfaɪd/ · fulfilled','Most customers were satisfied with the service.','[["Most customers were satisfied with the service.","اکثر مشتریان از خدمات راضی بودند."],["Are you satisfied with your parenting?","آیا از فرزندپروری خود راضی هستید؟"]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scenario','scenario','n','سناریو، وضعیت، حالت','/səˈner.i.oʊ/ · situation','There are several possible scenarios.','[["There are several possible scenarios.","چند سناریو احتمالی وجود دارد."],["He has devised a new scenario.","او سناریوی جدیدی را طراحی کرده است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scope','scope','n','محدوده، دامنه، گستره','/skoʊp/ · extent, horizon','A full discussion of that issue is beyond the scope of this book.','[["A full discussion of that issue is beyond the scope of this book.","بحث کامل درباره آن موضوع از حوصله این کتاب خارج است."],["Ziri purchased his first thermal scope in 2004.","زیری اولین دوربین حرارتی خود را در سال ۲۰۰۴ خریداری کرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:scrap','scrap','n','تکه، قطعه، اوراق، پاره','/skræp/ · fragment, piece, flake','Ziri is bringing his scrap book.','[["Ziri is bringing his scrap book.","زیری دفترچه خاطراتش را آورده است."],["The entire plan has been scrapped.","کل طرح منتفی شده است."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:segment','segment','n','بخش، سهم','/ˈseɡ.mənt/ · portion','The students are learning how to solve problems using line segments.','[["The students are learning how to solve problems using line segments.","دانش‌آموزان یاد می‌گیرند که چگونه با استفاده از پاره خط‌ها، مسائل را حل کنند."],["Many firms are competing for the wealthier segment of the market.","بسیاری از شرکت‌ها برای بخش ثروتمندتر بازار رقابت می‌کنند."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:seize','seize','v','گرفتن، تصرف کردن','/siːz/ · take','Seizing the initiative leads to victory.','[["Seizing the initiative leads to victory.","به دست گرفتن ابتکار عمل منجر به پیروزی می‌شود."],["He seized the opportunity to escape.","او از فرصت استفاده کرد و فرار کرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shallow','shallow','adj','کم عمق','/ˈʃæl.oʊ/ · not deep','Kalman dipped his legs into the shallows.','[["Kalman dipped his legs into the shallows.","کالمن پاهایش را در آب‌های کم‌عمق فرو برد."],["The water was too shallow for swimming.","آب برای شنا خیلی کم عمق بود."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sheer','sheer','adj','محض، مطلق، صرف','/ʃɪr/ · absolute','She persevered through sheer willpower.','[["She persevered through sheer willpower.","او با اراده‌ی خالصانه‌اش استقامت کرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shortage','shortage','n','کمبود، محدودیت','/ˈʃɔːr.tɪdʒ/ · limitation','There is a serious water shortage.','[["There is a serious water shortage.","کمبود آب جدی است."],["This area suffers from water shortages.","این منطقه از کمبود آب رنج می‌برد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:showcase','showcase','n','ویترین، نمایشگاه، صفحه نمایش','/ˈʃoʊ.keɪs/ · display v.','I love to showcase my artistic side.','[["I love to showcase my artistic side.","من عاشق این هستم که جنبه هنری خودم را نشان بدهم."],["What should you showcase in your resume?","چه چیزهایی را باید در رزومه خود به نمایش بگذارید؟"]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:shy-away-from','shy away from','phr','اجتناب کردن از، دوری جستن از','avoid','He tends to shy away from anything that involves public speaking.','[["He tends to shy away from anything that involves public speaking.","او معمولاً از هر چیزی که شامل سخنرانی عمومی باشد، دوری می‌کند."],["He did not shy away from challenges. He accepted missions that seemed impossible.","او از چالش‌ها طفره نمی‌رفت. او ماموریت‌هایی را که غیرممکن به نظر می‌رسیدند، می‌پذیرفت."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:signature','signature','n','امضا','/ˈsɪɡ.nə.tʃɚ/ · identifying mark','My signature is on all my books.','[["My signature is on all my books.","امضای من پای همه کتاب‌هایم هست."],["The signature had been a forgery.","امضا جعلی بود."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:significance','significance','n','اهمیت، قدر، مفاد','/sɪɡˈnɪf.ə.kəns/ · importance','The result was of little significance.','[["The result was of little significance.","نتیجه اهمیت چندانی نداشت."],["Did that have any special significance?","آیا این اهمیت خاصی داشت؟"]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:simultaneously','simultaneously','adv','به‌طور همزمان','/ˌsaɪ.məlˈteɪ.ni.əs/ · at the same time','Gustavo can do several things simultaneously.','[["Gustavo can do several things simultaneously.","گوستاو می‌تواند چندین کار را همزمان انجام دهد."],["He is learning four languages simultaneously.","او همزمان چهار زبان را یاد می‌گیرد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sink','sink','v','غرق شدن، پایین آمدن، فرود آمدن','/sɪŋk/ · descend, drop to the bottom, pass out of sight','The rats desert the sinking ship.','[["The rats desert the sinking ship.","موش‌ها کشتی در حال غرق شدن را ترک می‌کنند."],["Put your cup in the sink.","لیوانت را توی سینک بگذار."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:slight','slight','adj','جزئی، کم، کوچک','/slaɪt/ · small','I am running a slight fever.','[["I am running a slight fever.","یه تب خفیف دارم."],["We have a slight problem here.","ما اینجا یک مشکل جزئی داریم."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:slope','slope','v','سرازیر کردن یا شدن، متمایل شدن','/sloʊp/ · incline v.','I ran down the slope.','[["I ran down the slope.","از سراشیبی پایین دویدم."],["The icy slope seemed inaccessible.","شیب یخی غیرقابل دسترس به نظر می‌رسید."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:snap','snap','v','شکستن، ضربه محکم و ناگهانی','/snæp/ · break v.','It keeps me from snapping at people.','[["It keeps me from snapping at people.","این باعث میشه از مردم ایراد نگیرم."],["Janos heard a twig snapping behind him.","یانوش صدای شکستن شاخه‌ای را از پشت سرش شنید."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sole','sole','adj','منحصر به فرد، یگانه، تنها','/soʊl/ · only, unique','I was the sole survivor.','[["I was the sole survivor.","من تنها بازمانده بودم."],["He solely focuses on money.","او فقط روی پول تمرکز دارد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sophisticated','sophisticated','adj','پیچیده، در سطح بالا، ماهرانه','/səˈfɪs.tə.keɪ.tɪd/ · complex, refined, elaborated','The black suit made him look sophisticated.','[["The black suit made him look sophisticated.","کت و شلوار مشکی، او را شیک و مجلسی نشان می‌داد."],["He looks quite sophisticated for his age.","او برای سنش کاملاً شیک به نظر می‌رسد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:span','span','n','دوره','/spæn/ · period n.','The roof spans more than 60 meters.','[["The roof spans more than 60 meters.","طول سقف بیش از 60 متر است."],["There are two spans between them.","بین آنها دو دهانه وجود دارد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spectacular','spectacular','adj','تماشایی','/spekˈtæk.jə.lɚ/ · impressive','There is a spectacular view of the mountains.','[["There is a spectacular view of the mountains.","منظره ای دیدنی از کوه‌ها وجود دارد."],["The steak was inadvertently burnt, but nonetheless it tasted spectacular.","استیک ناخواسته سوخت، اما با این وجود طعم فوق‌العاده‌ای داشت."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:spectrum','spectrum','n','طیف','/ˈspek.trəm/ · range','I''m on the ace spectrum.','[["I''m on the ace spectrum.","من روی طیف آس هستم."],["He''s somewhere on the spectrum.","او جایی در این طیف قرار دارد."]]','t1212',12,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sphere','sphere','n','حوزه','/sfɪr/ · area','The highest sphere of life is mathematics.','[["The highest sphere of life is mathematics.","والاترین عرصه زندگی، ریاضیات است."],["The earth is shaped like a sphere.","زمین به شکل یک کره است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sponsor','sponsor','v','حمایت کردن','/ˈspɑːn.sɚ/ · support','Prizes are sponsored by individual community members and companies.','[["Prizes are sponsored by individual community members and companies.","جوایز توسط اعضای جامعه و شرکت‌های مختلف حمایت مالی می‌شوند."],["He was sponsored by a bunch of brands.","او توسط تعدادی از برندها حمایت مالی می‌شد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:strictly','strictly','adv','مؤکداً','/ˈstrɪkt.li/ · only','His parents raised him very strictly.','[["His parents raised him very strictly.","والدینش او را بسیار سختگیر بار آوردند."],["She follows the hygiene protocols strictly.","او پروتکل‌های بهداشتی را به شدت رعایت می‌کند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:striking','striking','adj','قابل توجه، برجسته','/ˈstraɪ.kɪŋ/ · dramatic','Ziri continued striking the woman furiously.','[["Ziri continued striking the woman furiously.","زیری با خشم به زدن زن ادامه داد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:stunning','stunning','adj','خیره‌کننده','/ˈstʌn.ɪŋ/ · astounding','This city has a stunning skyline.','[["This city has a stunning skyline.","این شهر افق خیره‌کننده‌ای دارد."],["I love the stunning winter landscapes.","من عاشق مناظر خیره کننده زمستانی هستم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:subjected-to','subjected to','phr','در معرض (چیزی) قرار گرفتن','/səbˈdʒektɪd/ · dominated by','They were subjected to terrible conditions.','[["They were subjected to terrible conditions.","آنها در شرایط وحشتناکی قرار داشتند."],["He was subjected to violence.","او مورد خشونت قرار گرفت."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:subsequently','subsequently','adv','متعاقبا','/ˈsʌb.sɪ.kwənt.li/ · later','The olives are subsequently placed in brine.','[["The olives are subsequently placed in brine.","سپس زیتون‌ها را در آب نمک قرار می‌دهند."],["I am subsequently sending you two pictures.","در ادامه دو عکس برایتان ارسال می‌کنم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:subsidiary','subsidiary','adj','فرعی','/səbˈsɪd.i.er.i/ · less important, secondary','It''s a wholly-owned subsidiary, but it maintains some independence from its parent company.','[["It''s a wholly-owned subsidiary, but it maintains some independence from its parent company.","این یک شرکت تابعه کاملاً متعلق به شرکت مادر است، اما تا حدودی استقلال خود را از شرکت مادر حفظ می‌کند."],["Overseas subsidiaries are putting out top-of the-line products.","شرکت‌های تابعه خارج از کشور، محصولات درجه یک را عرضه می‌کنند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:substantially','substantially','adv','به طور قابل ملاحظه‌ای','/səbˈstæn.ʃəl.i/ · importantly','Algeria will need to increase its interest rates substantially.','[["Algeria will need to increase its interest rates substantially.","الجزایر باید نرخ بهره خود را به میزان قابل توجهی افزایش دهد."],["Over the last few decades, Thailand has reduced poverty substantially.","در طول چند دهه گذشته، تایلند فقر را به میزان قابل توجهی کاهش داده است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:substitute','substitute','n','جایگزین، جایگزین کردن','/ˈsʌb.stə.tuːt/ · 1) replace 2)replacement','They substituted a small wheel for the giant front wheel and put the driving mechanism in a larger rear wheel.','[["They substituted a small wheel for the giant front wheel and put the driving mechanism in a larger rear wheel.","آن‌ها چرخ کوچکی را جایگزین چرخ جلوی غول‌پیکر کردند و سازوکار حرکت را در چرخ عقبِ بزرگ‌تر قرار دادند."],["Honey can be used as a substitute for sugar.","می‌توان از عسل به عنوان جایگزین شکر استفاده کرد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:subtle','subtle','adj','نامحسوس، ظریف، کم','/ˈsʌt.əl/ · small','I tried to be subtle.','[["I tried to be subtle.","سعی کردم ظریف و زیرکانه حرف بزنم."],["Am I being too subtle?","آیا من خیلی ظریف و دقیق هستم؟"]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:succession','succession','n','سلسله','/səkˈseʃ.ən/ · series','She won the competition three times in succession.','[["She won the competition three times in succession.","او سه بار متوالی برنده این مسابقه شد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:successive','successive','adj','پی در پی','/səkˈses.ɪv/ · continuous','The team has won three successive championships.','[["The team has won three successive championships.","این تیم سه بار پیاپی قهرمان شده است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sue','sue','v','شکایت کردن، اقامه ی دعوی کردن','/suː/ · raise a legal action againstfile a grievance','They probably want to sue for peace.','[["They probably want to sue for peace.","احتمالاً می‌خواهند برای صلح شکایت کنند."],["I am not going to sue you.","من از تو شکایت نخواهم کرد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:suited','suited','adj','مناسب','/ˈsuː.tɪd/ · appropriated','The hours suited his schedule perfectly.','[["The hours suited his schedule perfectly.","ساعت‌ها کاملاً با برنامه‌ی او مطابقت داشتند."],["I''m not suited for relationships.","من برای روابط مناسب نیستم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:supplement','supplement','n','مکمل؛ تکمیل کردن','/ˈsʌp·ləˌment/ · n)something that is added to something else in order to improve it or complete it v)to add to something','There are many different kinds of dietary supplements.','[["There are many different kinds of dietary supplements.","مکمل‌های غذایی انواع مختلفی دارند."],["Many people say that supplements are a scam.","خیلی‌ها می‌گویند مکمل‌ها کلاهبرداری هستند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:surplus','surplus','n','مازاد، اضافه','/ˈsɜrˌplʌs/ · n) extra, excess','Thanks to exports, the trade surplus is maintained.','[["Thanks to exports, the trade surplus is maintained.","به لطف صادرات، مازاد تجاری حفظ می‌شود."],["There will be a surplus of personnel.","نیروی انسانی مازاد خواهد بود."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:surveillance','surveillance','n','نظارت، مراقبت','/sərˈveɪ·ləns/ · n)careful observation','Igor was under constant surveillance.','[["Igor was under constant surveillance.","ایگور تحت نظر مداوم بود."],["Santiago inspected the surveillance cameras.","سانتیاگو دوربین‌های مداربسته را بررسی کرد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sustain','sustain','v','تحمل کردن، حمایت کردن از','/səˈsteɪn/ · v) support, persist','The part hardest to believe is that a plan like that could be sustained for decades without the secret being revealed.','[["The part hardest to believe is that a plan like that could be sustained for decades without the secret being revealed.","باورنکردنی‌ترین بخش این است که چنین نقشه‌ای بتواند دهه‌ها بدون فاش شدن راز ادامه یابد."],["Can the island sustain itself without trade?","آیا جزیره می‌تواند بدون تجارت، خود را حفظ کند؟"]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:sustainable','sustainable','adj','قابل تحمل، پایدار','/səˈsteɪ·nə·bəl/ · adj) endurable','We need sustainable sources of energy.','[["We need sustainable sources of energy.","ما به منابع انرژی پایدار نیاز داریم."],["The company is committed to sustainable farming.","این شرکت متعهد به کشاورزی پایدار است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:synthesis','synthesis','n','ترکیب، تلفیق','/siːz/ · n) combination','The smooth endoplasmic reticulum is the organelle responsible for lipid synthesis.','[["The smooth endoplasmic reticulum is the organelle responsible for lipid synthesis.","شبکه آندوپلاسمی صاف اندامکی است که مسئول سنتز لیپیدها می‌باشد."],["Additive synthesis involves manually controlling harmonics, and uses only sine waves.","سنتز افزایشی شامل کنترل دستی هارمونیک‌ها است و فقط از امواج سینوسی استفاده می‌کند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tendency','tendency','n','گرایش، تمایل','/ˈten·dən·si/ · inclination','You have the tendency to forget.','[["You have the tendency to forget.","شما تمایل به فراموش کردن دارید."],["She has a tendency to fantasise.","او تمایل به خیال‌پردازی دارد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tension','tension','n','فشار','/ˈten·ʃən/ · pressure','Exercise is the ideal way to relieve tension after a hard day.','[["Exercise is the ideal way to relieve tension after a hard day.","ورزش راهی ایده آل برای کاهش تنش پس از یک روز سخت است."],["There are many people who fuel tensions.","افراد زیادی هستند که به تنش‌ها دامن می‌زنند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:terrain','terrain','n','زمین','/təˈreɪn/ · tract','The mouflon grazed in the mountainous terrain.','[["The mouflon grazed in the mountainous terrain.","قوچ و میش در زمین‌های کوهستانی چرا می‌کرد."],["Felix is familiar with that rugged terrain.","فلیکس با آن زمین ناهموار آشناست."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:testify','testify','v','شهادت دادن، گواهی دادن','/ˈtes·təˌfɑɪ/ · give evidence','Who do you think will testify?','[["Who do you think will testify?","به نظر شما چه کسی شهادت خواهد داد؟"],["She agreed to testify against him.","او موافقت کرد که علیه او شهادت دهد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:thorough','thorough','adj','کامل، تمام','/ˈθɜr·oʊ/ · complete','The police made a thorough search.','[["The police made a thorough search.","پلیس جستجوی کامل انجام داد."],["She has a thorough knowledge of the subject.","او شناخت کاملی از موضوع دارد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:thoroughly','thoroughly','adv','به‌طور کامل','/ˈθɜr·ə·li/ · completely','He thoroughly checked the entire shop.','[["He thoroughly checked the entire shop.","او تمام مغازه را با دقت بررسی کرد."],["Ziri swept the basement floor thoroughly.","زیری کف زیرزمین را کاملاً جارو کرد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:threaten','threaten','v','تهدید کردن، ترساندن','/ˈθret·ən/ · endanger','The president is threatened by impeachment.','[["The president is threatened by impeachment.","رئیس جمهور با استیضاح تهدید می‌شود."],["He threatened to call the police.","او تهدید کرد که با پلیس تماس خواهد گرفت."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:threshold','threshold','n','آستانه، حد','/ˈθreʃˌoʊld/ · limitation, limit','The catalyst system efficiency is below the threshold.','[["The catalyst system efficiency is below the threshold.","راندمان سیستم کاتالیزوری پایین‌تر از حد آستانه است."],["I finally crossed the threshold of that house.","بالاخره از آستانه‌ی آن خانه عبور کردم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tolerate','tolerate','v','تحمل کردن، مدارا کردن','/ˈtɑː.lə.reɪt/ · endure','I can''t tolerate rude behavior.','[["I can''t tolerate rude behavior.","من نمی‌توانم رفتار بی ادبانه را تحمل کنم."],["These plants can tolerate very dry conditions.","این گیاهان می‌توانند شرایط بسیار خشک را تحمل کنند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:toxic','toxic','adj','سمی','/ˈtɑːk.sɪk/ · poisonous','Thallium is a highly toxic heavy metal.','[["Thallium is a highly toxic heavy metal.","تالیم یک فلز سنگین بسیار سمی است."],["His words often create a toxic atmosphere.","سخنان او اغلب فضایی مسموم ایجاد می‌کند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:transform','transform','v','دگرگون کردن، تبدیل کردن','/trænsˈfɔːrm/ · deform','The caterpillar transforms into a butterfly.','[["The caterpillar transforms into a butterfly.","کاترپیلار به پروانه تبدیل می‌شود."],["The internet has transformed the way we live.","اینترنت شیوه زندگی ما را دگرگون کرده است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:transformation','transformation','n','دگرگونی، تغییر شکل','/ˌtræns.fɚˈmeɪ.ʃən/ · shuffle, change, rotation','transformation from dictatorship to democracy','[["transformation from dictatorship to democracy","تبدیل از دیکتاتوری به دموکراسی"],["The city has undergone a complete transformation.","این شهر دستخوش دگرگونی کامل شده است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:trauma','trauma','n','آسیب، ضربه روحی، زخم','/ˈtrɑː.mə/ · damage, (a) severe emotional shock and pain caused by an extremely upsetting experience','You can recover from your trauma.','[["You can recover from your trauma.","شما می‌توانید از آسیب‌های روحی خود بهبود یابید."],["Boldi has a psychological trauma.","بولدی دچار آسیب روانی شده است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tremendous','tremendous','adj','عظیم، شگفت','/trɪˈmen.dəs/ · enormous','Fadil must have felt a tremendous amount of guilt.','[["Fadil must have felt a tremendous amount of guilt.","فاضل حتماً احساس گناه زیادی کرده بود."],["Coming out of the closet requires tremendous courage.","بیرون آمدن از لاک خود، شجاعت فوق‌العاده‌ای می‌خواهد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:tricky','tricky','adj','مشکل و نیازمند توجه','/ˈtrɪk.i/ · difficult, (of a task, problem, or situation) requiring care and skill because difficult or awkward.','This is a little tricky.','[["This is a little tricky.","این کمی مشکل است."],["Look how tricky you are.","ببین چقدر حیله گر هستی."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:trigger','trigger','v','راه انداختن، آغاز کردن کاری','/ˈtrɪɡər/ · initiate, start','The earthquake triggered a tsunami.','[["The earthquake triggered a tsunami.","زمین لرزه باعث سونامی شد."],["Loud noises can trigger a panic attack.","صداهای بلند می‌تواند باعث حمله پانیک شود."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:undergo','undergo','v','تجربه کردن','/ˌʌndərˈɡoʊ/ · experience','The city has undergone major changes.','[["The city has undergone major changes.","این شهر دستخوش تغییرات اساسی شده است."],["He underwent surgery on his knee.","او زانویش را تحت عمل جراحی قرار داد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:underlying','underlying','adj','اساسی','/ˌʌndərˈlaɪ-ɪŋ/ · inner','Stress is the underlying cause of many illnesses.','[["Stress is the underlying cause of many illnesses.","استرس عامل اصلی بسیاری از بیماری هاست."],["We need to understand the underlying principles.","ما باید اصول اساسی را درک کنیم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:unprecedented','unprecedented','adj','بی سابقه، بی نظیر','/ʌnˈpresɪdentɪd/ · novel, unique, initial, new, unexampled','The pandemic caused unprecedented changes.','[["The pandemic caused unprecedented changes.","همه گیری باعث تغییرات بی سابقه ای شد."],["Prices have risen to unprecedented levels.","قیمت‌ها به سطوح بی سابقه ای افزایش یافته است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:utterly','utterly','adv','کاملاً','/adverb]/ · completely','The whole thing is utterly oppressive.','[["The whole thing is utterly oppressive.","کل ماجرا کاملاً سرکوبگرانه است."],["After that, I was utterly exhausted.","بعد از آن، کاملاً بی‌رمق شدم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:variation','variation','n','تفاوت','/ˌveəriˈeɪʃən/ · difference','There are many regional variations of English.','[["There are many regional variations of English.","تنوع منطقه ای زیادی در زبان انگلیسی وجود دارد."],["Autism is a natural variation in the human condition.","اوتیسم یک تغییر طبیعی در شرایط انسانی است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:varied','varied','adj','مختلف','/ˈveərid/ · different','Kurdish food is very delicious and varied.','[["Kurdish food is very delicious and varied.","غذاهای کردی بسیار خوشمزه و متنوع هستند."],["I enjoy a full and varied life.","من از یک زندگی کامل و متنوع لذت می‌برم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vicinity','vicinity','n','نزدیکی، مجاورت، همسایگی','/vəˈsɪnəti/ · neighborhood','Ziri heard a crunch of leaves in the vicinity.','[["Ziri heard a crunch of leaves in the vicinity.","زیری صدای خش خش برگ‌هایی را از همان نزدیکی شنید."],["I stayed in the vicinity of his house.","من در نزدیکی خانه‌اش ساکن شدم."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:virtually','virtually','adv','واقعا، تقریباً','/ˈvɜːrtʃuəli/ · nearly, almost, nearly, actually, in fact','We spent virtually all day shopping.','[["We spent virtually all day shopping.","ما تقریبا تمام روز را صرف خرید کردیم."],["Both candidates are virtually unknown.","هر دو نامزد عملاً ناشناخته هستند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:virtue','virtue','n','تقوا، پرهیزکاری، پاکدامنی، شایستگی','/ˈvɜːrtʃuː/ · merit','Why not make a virtue of necessity?','[["Why not make a virtue of necessity?","چرا از ضرورت، فضیلت نسازیم؟"],["Patience is a virtue not everyone has.","صبر فضیلتی است که هر کسی ندارد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:visual-barrier','visual barrier','n','مانع بصری','obstacle to view','The tall trees act as a visual barrier between the house and the road.','[["The tall trees act as a visual barrier between the house and the road.","درختان بلند به عنوان یک مانع بصری بین خانه و جاده عمل می‌کنند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:vulnerable','vulnerable','adj','آسیب‌پذیر، حساس، ضعیف','/ˈvʌlnərəbəl/ · open to attack, open to break, susceptible, weak','Older people are more vulnerable to the flu.','[["Older people are more vulnerable to the flu.","افراد مسن در برابر آنفولانزا آسیب پذیرتر هستند."],["The city is vulnerable to earthquakes.","این شهر در برابر زلزله آسیب پذیر است."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:warrant','warrant','v','گواهی کردن، تضمین کردن، تعهد کردن','/ˈwɑːrənt/ · authorize, justify','We got a search warrant.','[["We got a search warrant.","ما حکم تفتیش گرفتیم."],["Come back with a warrant.","با حکم برگرد."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:wholly','wholly','adv','کاملاً','/ˈhōl(l)ē/ · completely','The decision is wholly up to you.','[["The decision is wholly up to you.","تصمیم کاملاً به عهده شماست."],["Her words were wholly void of meaning.","حرف‌هایش کاملاً بی‌معنی بود."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:yearly','yearly','adj','سالیانه','/ˈyi(ə)rlē/ · annual','The festival is a yearly event that attracts thousands of visitors.','[["The festival is a yearly event that attracts thousands of visitors.","این جشنواره یک رویداد سالانه است که هزاران بازدیدکننده را به خود جذب می‌کند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:yield','yield','n','بازده، محصول؛ به بار آوردن','/jiːld/ · produce, provide','The experiment yielded useful data.','[["The experiment yielded useful data.","آزمایش داده‌های مفیدی به دست آورد."],["The farm yields two crops a year.","مزرعه دو محصول در سال تولید می‌کند."]]','t1212',13,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:abrupt','abrupt','adj','اتفاقی، غیر منتظره، غیردوستانه و گستاخانه','/əˈbrʌpt/ · 1)sudden and unexpected; or 2) seeming rude and unfriendly','Yuri abruptly changed the tone of the conversation.','[["Yuri abruptly changed the tone of the conversation.","یوری ناگهان لحن مکالمه را تغییر داد."],["Bruno abruptly snapped back to consciousness and listened.","برونو ناگهان به هوش آمد و گوش داد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:abundant','abundant','adj','فراوان، زیاد','/əˈbʌndənt/ · affluent, ample, numerous, plentiful, substantial, copious','Fish are abundant in these waters.','[["Fish are abundant in these waters.","ماهی در این آب‌ها فراوان است."],["The region has abundant natural resources.","این منطقه دارای منابع طبیعی فراوانی است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:accelerate','accelerate','v','سرعت بخشیدن','/əkˈseləreɪt/ · speed up/get faster','Social networks can accelerate the spread of misinformation.','[["Social networks can accelerate the spread of misinformation.","شبکه‌های اجتماعی می‌توانند سرعت انتشار اطلاعات نادرست را افزایش دهند."],["The engine hummed smoothly as the car accelerated.","همزمان با شتاب گرفتن ماشین، موتور به نرمی وزوز می‌کرد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:acclaimed','acclaimed','adj','تحسین‌شده','/əˈkleɪmd/ · praised- publicly praised by a lot of people','The audience acclaimed the actors for their performance.','[["The audience acclaimed the actors for their performance.","تماشاگران از بازیگران به خاطر بازی‌شان تمجید کردند."],["The crowd acclaimed the new king.","جمعیت پادشاه جدید را تشویق کردند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:accumulate','accumulate','v','انباشتن پول، دانش و غیره','/əˈkjuːmjʊleɪt/ · collect, pile up, build up- to gradually more and more money, possessions, knowledge etc over a period of time','Snow accumulated on the roof.','[["Snow accumulated on the roof.","برف روی پشت بام انباشته شد."],["Dust accumulates quickly in an empty house.","گرد و غبار به سرعت در یک خانه خالی جمع می‌شود."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:adept','adept','adj','ماهر، زیردست','/əˈdɛpt/ · very skilled; having a natural ability to do something that needs skill (at doing sth)','This man is quite adept at telling lies.','[["This man is quite adept at telling lies.","این مرد در دروغ گفتن مهارت زیادی دارد."],["Sci-fi readers are adept at hypothetical scenarios.","خوانندگان علمی تخیلی در سناریوهای فرضی مهارت دارند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:adequately','adequately','adv','به اندازه کافی','/ˈadɪkwətli/ · enough in quantity, or good enough in quality, for a particular purpose or need','You must be adequately prepared.','[["You must be adequately prepared.","شما باید به اندازه کافی آماده باشید."],["Uranus hasn''t been adequately probed.","اورانوس به اندازه کافی مورد بررسی قرار نگرفته است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:administer','administer','v','مدیریت کردن','/ədˈmɪnɪstə/ · manage','I know how to administer injections.','[["I know how to administer injections.","من بلدم تزریقات رو انجام بدم."],["The doctor is administering a jab.","دکتر در حال تزریق آمپول است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:advent','advent','n','ظهور، پیدایش','/ædvent/ · arrival, beginning','The advent of stormtroopers brought about a turn in trench warfare.','[["The advent of stormtroopers brought about a turn in trench warfare.","ظهور سربازان ضربت‌زن، چرخشی در جنگ‌های سنگر به سنگر ایجاد کرد."],["Pottery usually appears in a culture after the advent of agriculture.","سفالگری معمولاً پس از ظهور کشاورزی در یک فرهنگ ظاهر می‌شود."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:agile','agile','adj','باهوش، زیرک، چابک','/ˈædʒəl/ · astute, clever, moving and acting quickly, quick and active','The slippery body of the nymph swam agilely like a fish.','[["The slippery body of the nymph swam agilely like a fish.","بدن لغزنده‌ی حوری، مثل ماهی، چابک شنا می‌کرد."],["Crawl forward is done much more agilely - scuttle like a cockroach!","خزیدن به جلو بسیار چابک‌تر انجام می‌شود - مثل سوسک بدوید!"]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:allocation','allocation','n','تخصیص','/æləˈkeɪʃən/ · distribution','Algeria''s state budget gives generous allocations to education and healthcare.','[["Algeria''s state budget gives generous allocations to education and healthcare.","بودجه دولتی الجزایر بودجه سخاوتمندانه‌ای را به آموزش و مراقبت‌های بهداشتی اختصاص می‌دهد."],["It''s all about intelligent allocation of resources.","همه چیز در مورد تخصیص هوشمندانه منابع است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ambiguous','ambiguous','adj','مبهم، دارای بیش از یک معنی','/æmˈbɪɡjuəs/ · more than one meaning, vague','The question was ambiguous.','[["The question was ambiguous.","سوال مبهم بود."],["The instructions were ambiguous.","دستورالعمل‌ها مبهم بود."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ample','ample','adj','انبوه، فراوان','/ˈæmpəl/ · spacious, plentiful;sufficient','The shelter provided ample space for us.','[["The shelter provided ample space for us.","پناهگاه فضای کافی برای ما فراهم کرده بود."],["We got a short but ample respite.","ما یک استراحت کوتاه اما کافی داشتیم."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:analogous-to','analogous to','phr','شبیه به','/əˈnæləɡəs/ · similar to','In the economic sphere communism is analogous to democracy in the political sphere.','[["In the economic sphere communism is analogous to democracy in the political sphere.","کمونیسم در حوزه اقتصادی مشابه دموکراسی در حوزه سیاسی است."],["The human heart is analogous to a pump.","قلب انسان شبیه یک پمپ است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:ancestor','ancestor','n','جد','/ˈænsestər/ · forefather/progenitor','My ancestors came from Shiraz.','[["My ancestors came from Shiraz.","اجداد من از شیراز آمده اند."],["The dog''s wild ancestors were wolves.","اجداد وحشی این سگ گرگ بودند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:anomaly','anomaly','n','ناهنجاری','/əˈnɑːməli/ · irregularity- something that is noticeable because it is different from what is usual','The scientists noticed an anomaly in the data.','[["The scientists noticed an anomaly in the data.","دانشمندان متوجه یک ناهنجاری در داده‌ها شدند."],["The warm winter was an anomaly.","زمستان گرم یک ناهنجاری بود."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:antagonist','antagonist','n','مخالف، حریف، رقیب','/ænˈtæɡənɪst/ · competitor- your opponent in competition, battle','Despite being the antagonist in the movie, I liked her character.','[["Despite being the antagonist in the movie, I liked her character.","با اینکه نقش منفی فیلم را بازی می‌کرد، شخصیتش را دوست داشتم."],["The antagonist of the book was introduced on the second page.","شخصیت منفی کتاب در صفحه دوم معرفی شد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:anticipate','anticipate','v','پیش بینی کردن، توقع داشتن','/ænˈtɪsɪpeɪt/ · expect, foresee, predict, project, estimate','We anticipate a busy summer.','[["We anticipate a busy summer.","تابستان شلوغی را پیش بینی می‌کنیم."],["We don''t anticipate any problems with the new system.","ما هیچ مشکلی با سیستم جدید پیش بینی نمی‌کنیم."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:apparatus','apparatus','n','دستگاه، لوازم، تجهیزات','/ˌapəˈreɪtəs/ · equipment-the technical equipment or machinery needed for a particular activity or purpose','The fire department dispatched several fire apparatus to the scene.','[["The fire department dispatched several fire apparatus to the scene.","آتش نشانی چندین دستگاه خودرو اطفاء حریق را به محل حادثه اعزام کرد."],["The physics laboratory has the best apparatus I''ve ever seen.","آزمایشگاه فیزیک بهترین دستگاه‌هایی را دارد که تا به حال دیده‌ام."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:arid','arid','adj','خشک','/arɪd/ · dry; barren- having little or no rain; too dry or barren to support vegetation','Cacti grow in arid regions.','[["Cacti grow in arid regions.","کاکتوس‌ها در مناطق خشک رشد می‌کنند."],["The climate of central Iran is arid.","اقلیم ایران مرکزی خشک است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:assert','assert','v','تشریح کردن','/əˈsəːt/ · declare-state a fact or belief confidently and forcefully','The guards tried to assert their dominance.','[["The guards tried to assert their dominance.","نگهبانان سعی کردند تسلط خود را نشان دهند."],["I wanted to assert my independence.","می‌خواستم استقلالم را ثابت کنم."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:assertion','assertion','n','ادعا','/əˈsɝː.ʃən/ · strong statement-a confident and forceful statement of fact or belief','An assertion isn''t a proof.','[["An assertion isn''t a proof.","ادعا، دلیل و مدرک نیست."],["Tom refuted that assertion with a counterexample.","تام این ادعا را با یک مثال نقض رد کرد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:astonishing','astonishing','adj','خارق العاده','/əˈstɑː.nɪ.ʃɪŋ/ · amazing','The human hand is astonishingly flexible.','[["The human hand is astonishingly flexible.","دست انسان به طرز شگفت انگیزی انعطاف پذیر است."],["The exhibition contained really astonishing paintings.","این نمایشگاه شامل نقاشی‌های واقعاً شگفت‌انگیزی بود."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:attain','attain','v','به دست آوردن','/əˈteɪn/ · achieve','Few students attain a perfect score.','[["Few students attain a perfect score.","تعداد کمی از دانش آموزان به نمره کامل می‌رسند."],["She attained the highest score in the class.","او بالاترین نمره را در کلاس کسب کرد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:attribute','attribute','n','خصوصیت، ویژگی، نسبت دادن','/əˈtrɪb.juːt/ · 1)characteristic 2)credit with-accredit','Scientists attribute the change to pollution.','[["Scientists attribute the change to pollution.","دانشمندان این تغییر را به آلودگی نسبت می‌دهند."],["He attributes his success to hard work.","او موفقیت خود را مرهون سخت کوشی می‌داند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:attribution','attribution','n','تخصیص، نسبت','/ˌætrɪˈbjuːʃn/ · character','The attribution of the painting to Rembrandt is now doubted by experts.','[["The attribution of the painting to Rembrandt is now doubted by experts.","انتساب این نقاشی به رامبراند اکنون توسط کارشناسان مورد تردید است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:avid','avid','adj','مشتاق، ارزومند، متمایل','/ˈævɪd/ · enthusiastic, extremely eager or interested','Are you an avid reader?','[["Are you an avid reader?","آیا شما یک خواننده مشتاق هستید؟"],["Leonid is an avid jogger.","لئونید یک دونده‌ی مشتاق است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:barge','barge','n','قایق، لنج','/bɑːrdʒ/ · boat','I barged into the room.','[["I barged into the room.","با عجله وارد اتاق شدم."],["Lorenzo barged through the gate.","لورنزو با عجله از دروازه عبور کرد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:be-accustomed-to','be accustomed to','phr','خو گرفتن به، عادت داشتن','get used to','After a few months, she was accustomed to the cold winters.','[["After a few months, she was accustomed to the cold winters.","بعد از چند ماه، او به زمستان‌های سرد عادت کرده بود."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:be-susceptible-to','be susceptible to','phr','در معرض بودن (یک بیماری یا مشکل)','be subject to','Young children are susceptible to colds in winter.','[["Young children are susceptible to colds in winter.","کودکان خردسال در زمستان مستعد سرماخوردگی هستند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:bear-a-close-resemblance-to','bear a close resemblance to','phr','بسیار شبیه به چیزی بودن','be more like','The new species bears a close resemblance to a common house cat.','[["The new species bears a close resemblance to a common house cat.","این گونه جدید شباهت زیادی به گربه خانگی معمولی دارد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:become-extinct','become extinct','phr','منقرض شدن','die out','How do you think humans are going to become extinct?','[["How do you think humans are going to become extinct?","به نظر شما انسان‌ها چگونه منقرض می‌شوند؟"],["We must colonize other planets if we are not to become extinct.","اگر قرار نیست منقرض شویم، باید سیارات دیگر را استعمار کنیم."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:beforehand','beforehand','adv','قبل از رویداد دیگه‌ای به وقوع پیوستن','/bɪˈfɔːrhændf/ · foreordain, before something else happens or is done','Please use the bathroom beforehand.','[["Please use the bathroom beforehand.","لطفا قبلش از دستشویی استفاده کنید."],["Did you know that beforehand?","آیا از قبل این را می‌دانستید؟"]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:blossom','blossom','n','شکوفه، شکوفا کردن','/ˈblɑ:səm/ · flourish, thrive','Plum blossom by plum blossom comes warmth.','[["Plum blossom by plum blossom comes warmth.","شکوفه آلو، با شکوفه آلو گرما می‌آید."],["Try to truly blossom in your career.","سعی کنید واقعاً در حرفه خود شکوفا شوید."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:boast','boast','v','به رخ کشیدن، مبالغه','/boʊst/ · exaggerate, puff','It suits him to boast.','[["It suits him to boast.","لاف زدن برایش مناسب است."],["He boasts at my expense.","او به قیمت من فخر می‌فروشد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:boon','boon','n','مزیت','/buːn/ · great benefit','This dictionary is great boon up to us.','[["This dictionary is great boon up to us.","این فرهنگ لغت برای ما نعمت بزرگی است."],["The talented comedian Danny Boon is a Kabyle.","کمدین بااستعداد، دنی بون، اهل کابیل است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:brew','brew','v','به عمل آوردن، سرشتن','/bruː/ · develop','The smell of freshly brewed tea filled the room.','[["The smell of freshly brewed tea filled the room.","بوی چای تازه دم، فضای اتاق را پر کرده بود."],["She had the distinct feeling that something was brewing.","او این حس مشخص را داشت که چیزی در حال شکل‌گیری است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:camouflage','camouflage','n','استتار، پوشش، مخفی کردن، پنهان کردن','/ˈkæməflɑːʒ/ · hide, blend with circumstances, decorate, disguise','The chameleon uses camouflage.','[["The chameleon uses camouflage.","آفتاب پرست از استتار استفاده می‌کند."],["Soldiers wore camouflage uniforms.","سربازان لباس استتار به تن داشتند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:catastrophic','catastrophic','adj','مضر، بد، مصیبت بار، فاجعه آمیز','/ˌkætəˈstrɑːfɪk/ · badly harmful','Catastrophic weather events are increasing.','[["Catastrophic weather events are increasing.","حوادث آب و هوایی فاجعه بار در حال افزایش است."],["The damage could be catastrophic.","خسارت می‌تواند فاجعه‌بار باشد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:chaotic','chaotic','adj','بی نظم، پرهرج و مرج','/keɪˈɑːtɪk/ · disorganized','Fadil was raised by a single mother in a chaotic household.','[["Fadil was raised by a single mother in a chaotic household.","فاضل توسط یک مادر مجرد در یک خانواده‌ی آشفته بزرگ شد."],["My mornings became more tranquil without the chaotic news cycle starting my day.","صبح‌هایم بدون چرخه‌ی آشفته‌ی اخبار، آرام‌تر شدند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cherish','cherish','v','گرامی داشتن','/ˈtʃerɪʃ/ · value','She cherished their unshakable bond.','[["She cherished their unshakable bond.","او پیوند تزلزل‌ناپذیرشان را گرامی می‌داشت."],["You need to cherish him.","باید او را گرامی بداری."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:circumstance','circumstance','n','پیشامد، شرایط محیط، وضعیت','/ˈsɜːrkəmstæns/ · condition, situation','The circumstances of his death are suspicious.','[["The circumstances of his death are suspicious.","شرایط مرگ او مشکوک است."],["Under those circumstances, they may not try to steal from large museums.","در چنین شرایطی، ممکن است دیگر برای دزدی از موزه‌های بزرگ تلاش نکنند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cite','cite','v','استناد کردن، نقل قول کردن','/saɪt/ · refer to, quote, mention','She cited 3 reasons why people get into debt.','[["She cited 3 reasons why people get into debt.","او به 3 دلیل برای بدهکاری مردم اشاره کرد."],["The report cites several studies.","در این گزارش به چندین مطالعه اشاره شده است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:cling-to','cling to','phr','چسبیدن به، الحاق شدن، نگه داشتن','/ˈkliŋ/ · attach to, hold','Ziri noticed crumbs clinging to his fingers.','[["Ziri noticed crumbs clinging to his fingers.","زیری متوجه خرده نان‌هایی شد که به انگشتانش چسبیده بودند."],["Wet clothing clings to the skin.","لباس‌های خیس به پوست می‌چسبند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:coating','coating','n','پوشش، رویه، جلد','/ˈkəʊtɪŋ/ · covering','The pan has a special coating so food does not stick.','[["The pan has a special coating so food does not stick.","این تابه دارای روکش مخصوص است تا غذا به آن نچسبد."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:coincide-with','coincide with','phr','همزمان با','/ˌkəʊənˈsaɪd/ · be as the same time as, accord with','The date of the festival coincides with that of the exam.','[["The date of the festival coincides with that of the exam.","تاریخ برگزاری جشنواره با تاریخ برگزاری آزمون همزمان است."],["Some reptile species have a breeding season that coincides with rainy seasons.","برخی از گونه‌های خزندگان فصل تولید مثلی دارند که با فصول بارانی همزمان است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:collaborate','collaborate','v','همکاری، همکاری کردن','/kəˈlæbəreɪt/ · cooperate','He was accused of collaborating with the enemy.','[["He was accused of collaborating with the enemy.","او به همکاری با دشمن متهم شد."],["Who do you want to collaborate with?","با چه کسی می‌خواهید همکاری کنید؟"]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:colossal','colossal','adj','بزرگ، عظیم الجثه','/kəˈlɒsəl/ · enormous','The war damage is colossal.','[["The war damage is colossal.","خسارات جنگ بسیار هنگفت است."],["They made a colossal mistake.","آنها اشتباه بزرگی مرتکب شدند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:commemorate','commemorate','v','جشن تجلیل برگزار کردن، بزرگداشت','/kəˈmeməreɪt/ · celebrate','Today we commemorate the defeat of the military regime.','[["Today we commemorate the defeat of the military regime.","امروز ما شکست رژیم نظامی را گرامی می‌داریم."],["The children commemorate the centenary of the armistice.","بچه‌ها صدمین سالگرد آتش‌بس را گرامی می‌دارند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:comparative','comparative','adj','مقایسه‌ای، به‌طور نسبی','/kəmˈpærətɪv/ · relative','She is doing a comparative study of the two languages.','[["She is doing a comparative study of the two languages.","او در حال انجام یک مطالعه تطبیقی ​​​​بین دو زبان است."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:compensate','compensate','v','جبران کردن، خسارت دادن، غرامت دادن، تاوان دادن','/ˈkɒmpənseɪt/ · make up','Some animals compensate for poor sight with hearing.','[["Some animals compensate for poor sight with hearing.","برخی از حیوانات ضعف بینایی را با شنوایی جبران می‌کنند."],["Nothing can compensate for the loss of a child.","هیچ چیز نمی‌تواند فقدان یک کودک را جبران کند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('t1212:compensate-for','compensate for','phr','جبران کردن، خنثی کردن، تعدیل کردن','/ˈkɒmpənseɪt/ · 1)balance 2)reimburse','I worked hard to compensate for the loss.','[["I worked hard to compensate for the loss.","من برای جبران این باخت خیلی تلاش کردم."],["Expensive meals don''t compensate for lack of sleep.","غذاهای گران‌قیمت، کمبود خواب را جبران نمی‌کنند."]]','t1212',14,1792879531209,1792879531209) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
